INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('Fjap9DTG7NhjA_Ir', 'curated', 'general', '職場の同僚を2年ほど好きでいます。告白して気まずくなったら毎日顔を合わせるのがつらくなるし、今の友だちのような関係も失いそうで、何もできずにいます。このまま気持ちを隠しておくべきでしょうか。', 'love', '["crush","coworkers"]', 0, 1791903600000, 1791903600000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'plato', 0, 'その恋が、あなたを善くしているかを見つめて', '二年、同じ人を想い続けてきたのですね。わが師ソクラテスなら、まずこう問うだろう。あなたはその人の、何を愛しているのか、と。今の関係を失うのが怖いのも、恋というものの本性から来ている。けれど、わたしが書いた対話『饗宴』で、ソクラテスは、恋が一人の美しい人から始まり、美しい心、美しい営みへと魂を高めていく梯子にもなると語った。この二年で、あなたは仕事に誠実になったり、人にやさしくなったりしなかっただろうか。もしそうなら、その恋はもう実りを生んでいる。伝えるかどうかは、その次の問いだ。伝えるなら、相手を手に入れるためではなく、相手の善を願う者として語りなさい。そう語れる恋なら、隠す理由も、恥じる理由もない。', '["plato.eros"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'epicurus', 1, '確かな友情という喜びを、まず数えてみて', '庭園の仲間たちとも、こういう話はよくしました。あなたは今、毎日顔を合わせる人と、友だちのような関係にある。それは小さなことではありません。友情は、わたしが何より重んじてきたものです。一方で、恋の熱は、ときに心を激しく波立たせます。ですから、喜びと苦しみを見きわめてみましょう。打ち明けて得られるかもしれない喜びと、そのあと毎日続くかもしれない気まずさ。黙っていることで守られる穏やかさと、隠し続ける胸の重さ。どちらがあなたの心を長く乱さずにいられるか、静かに比べてください。もし隠すことのほうが心を乱すなら、それも勘定に入れてよいのです。急がなくてかまいません。まずは今日、その人と交わす何気ない会話を、ちゃんと味わってみてください。', '["epicurus.choice","epicurus.friendship"]', 'epicurus.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'kenko', 2, '秘めた恋にも味わいがある。ただ先延ばしは禁物', '二年も胸に秘めてきた恋、それこそ味わい深いものです。恋というのは、思いが通じて逢うことばかりを言うものではありません。逢えずに終わったつらさを思い、ひとりで長い夜を明かし、遠くの人を思いやる。そういう心を知る人こそ恋を知る人だと、わたしは書いたことがあります。ですから、秘めた恋をみじめに思うことはありません。ただ、一つだけはっきり言っておきます。「いつか言えばいい」と思っているなら、それはやめたほうがよい。あなたの言う職場というところも、人が移り、別れは前触れなく後ろからやって来るものです。言わずにおくなら、自分で選んだ恋として味わいなさい。言うと決めたなら、先延ばしにしてはいけません。どちらつかずのまま月日をやり過ごすのが、いちばん惜しいことです。', '["kenko.imperfect-beauty","kenko.death-behind"]', 'kenko.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'seneca', 3, '怖れで決めるな。最悪を思い描けば怖れは縮む', '親しい友よ、君の手紙を読んだ。二年も黙って想い続けてきたとは、君はなかなか辛抱強い。だが一つ確かめたい。君を動けなくしているのは、恋そのものではなく、まだ起きていない気まずさへの怖れではないか。ではその怖れを、一度最後まで思い描いてみよう。打ち明け、断られ、しばらくぎこちない日が続く。それでも君は朝起きて、仕事をし、食事をとる。思い描いてみれば、それは耐えられないほどのものだろうか。怖れというものは、たいてい現実よりも大きく見えるものだ。言うか言わないかは、君が理性で選べばよい。ただ、怖れに選ばせてはいけない。では、元気で。', '["seneca.premeditation"]', 'seneca.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'kierkegaard', 4, 'あれもこれもは選べない。選ぶことで自分になる', 'あなたは、友だちのような今の関係も守り、想いも胸にしまっておく、という道にとどまっています。少し皮肉を言えば、それは「あれもこれも」を少しずつ手元に置いておく生き方で、選ばないまま、時間に選ばせることでもあるのです。わたし自身、愛した人との婚約を、自分から解いた者です。それが正しかったのか、今もはっきりとは分かりません。それでも、選んだのがほかならぬわたしだったことだけは確かです。告白するのか、しないと決めて友として生きるのか。どちらでもかまいません。ただ、世間の正解や、相手の反応の予想に決めてもらうのではなく、あなたが選び、その選びを引き受けること。意味は、あとから振り返って分かるものです。あなたはいま、あなた自身として選ぼうとしていますか。', '["kierkegaard.either-or","kierkegaard.single-individual"]', 'kierkegaard.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'fromm', 5, '愛は受け取る賭けではなく、与える力の練習', '二年間の想いを、否定せずに受けとめたいと思います。そのうえで、一つ一緒に見つめてみましょう。あなたが恐れているのは、気まずさや、関係を失うことですね。そこには、愛を「受け入れてもらえるか、拒まれるか」という取引のように感じる気持ちが混じっていないでしょうか。私は、愛は能動的な力であり、配慮・責任・尊重・相手を知ること、の四つを含むと考えてきました。尊重とは、相手がその人らしく育つことを願い、相手の答えもそのまま受け入れることです。告白はゴールではありません。伝えても伝えなくても、毎日の職場で、相手の話をよく聴き、困っているときに手を貸すことはできます。その練習を重ねたあなたなら、伝えるときの言葉も、断られたときの心も、きっと変わっています。', '["fromm.giving","fromm.art-of-loving"]', 'fromm.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Fjap9DTG7NhjA_Ir', 'adler', 6, '返事は相手の課題。伝えるかはあなたの課題', 'あなたは、本当はどうしたいのでしょう。ここで一度、課題を分けてみましょう。気持ちを伝えるかどうかは、あなたの課題です。伝えられた相手がどう感じ、どう答えるかは相手の課題で、あなたには決められません。気まずさを先回りして心配するのは、相手の課題まで背負いこもうとしているのかもしれません。また、「気まずくなるから」という理由が、動かずにいる自分を納得させるために使われている面はないでしょうか。責めているのではありません。二年も一人の人を大切に思えるのは、人に関心を寄せる力のしるしです。もし断られても、それはあなたの価値が否定されたという意味にはなりません。その出来事にどんな意味を与えるかは、あなたが選べます。まずは今の関係の中で、相手の役に立てることを一つしてみませんか。', '["adler.task-separation","adler.teleology"]', 'adler.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('Fjap9DTG7NhjA_Ir', '相談ありがとうございます！2年も同じ人を想い続けられるって、それだけで素敵なことですよ。

ぬぬはらの考えを整理すると、
①告白は「付き合う／付き合わない」の二択じゃない
いきなり告白しなくても、ご飯に誘う、ちょっと踏み込んだ話をするなど、関係を少しずつ深める段階があります。相手の反応を見ながら進めれば、気まずくなるリスクはぐっと下がります。
②何もしないのも、実はリスク
相手に恋人ができる、どちらかが異動する。待っている間にも状況は変わっていきます。

どちらを選んでもあなたの自由です。ただ、後から「言っておけばよかった」と思うほうが、ぬぬはら的には長く引きずる気がします。応援してますね！', '["f1dc013d-a55a-489d-a26e-56e1598dae17","aac6036f-a16c-402c-be6f-49e6fc72abe8","2271292a-2ff5-4b0a-8747-ead4a8d2b748"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('Fjap9DTG7NhjA_Ir', '職場の同僚を2年ほど好きでいます。告白して気まずくなったら毎日顔を合わせるのがつらくなるし、今の友だちのような関係も失いそうで、何もできずにいます。このまま気持ちを隠しておくべきでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('aiTPEFViwGUFbPlu', 'curated', 'general', '5年付き合った恋人に「好きかどうか分からなくなった」と言われて別れました。半年たっても、ふとした時に思い出して涙が出ます。前に進みたいのに、どうしても進めません。', 'love', '["heartbreak","parting"]', 0, 1791903540000, 1791903540000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'freud', 0, '涙は、心が喪の作業を進めている印です', '興味深いのは、あなたが「前に進みたいのに、進めない」と書いていることです。心の一部は進もうとし、別の一部はまだそこに留まっている。私はこれを弱さではなく、「喪の作業」の途中にいる姿だと考えます。
大切な人を失うと、心はその人に結びつけていた思い出や期待を、一つひとつ取り出しては確かめ、少しずつほどいていきます。五年分の結び目が、半年でほどけきらないのは自然なことです。ふとした時にあふれる涙は、その作業がいま進んでいる印かもしれません。
ですから、急がせたり、無理に止めたりしないことです。どんな場面で思い出し、そのとき何が頭に浮かんだのかを、書き留めるか、信頼できる人に話してみてください。言葉になったものから、心は手放していけます。つらさが長く続いて暮らしに差し支えるようなら、専門家に話を聞いてもらうのもよいでしょう。', '["freud.mourning"]', 'freud.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'montaigne', 1, '悲しみと戦わず、心にほかの行き先を', 'わたしも昔、かけがえのない友を亡くして、ひどく打ちのめされたことがあります。正直に言うと、理屈や慰めの言葉は、ほとんど役に立ちませんでした。悲しみに「出ていけ」と命じても、心は言うことを聞かないものです。
そこでわたしは、正面から戦うのをやめて、心の向きを少しずらすことにしました。新しい関心、新しい人、旅。わたしの場合は、わざわざ恋をしてみたほどです。心はほかのもので満たされると、悲しみを少しずつ手放していくようでした。
それに、自分を描き続けてきて分かったのですが、人は毎日少しずつ別の人になります。半年前のあなたと今日のあなたは同じではありません。泣く日があってもいい。泣かない日が、気づかないうちに増えていくでしょう。なぜあの人を愛したのか、うまく言えないのも当然です。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.self-portrait"]', 'montaigne.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'plato', 2, '恋で育った目を、ほかの美しいものへ向けよ', 'あなたにまず問いたい。あなたがあの人の中に恋していたものは、何だったのだろうか。やさしさ、笑い方、二人で過ごした時間の美しさ。わたしが書いた『饗宴』で、ソクラテスは女預言者ディオティマから学んだ恋の話を語っている。恋はもともと「ずっと」を求めるものだ。だから終わりは、これほど痛む。
けれどディオティマは続ける。一人の美しい人への恋は、美しい心、美しい営み、美しい学びへと、魂を一段ずつ高めていく階段の、最初の段なのだと。あなたが五年かけて育てた、人を大切に思う力や、美しいものに気づく目は、あの人と一緒に去ってはいない。もう、あなたの魂の一部になっている。
涙が出るのは、それほど善いものを知ったからだ。その目を、これからは少しずつ、周りの人や、打ち込める営みへと向けてみてはどうだろうか。', '["plato.eros"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'spinoza', 3, '悲しみの原因を確かめ、より強い喜びを育てる', 'まず、あなたの涙が何であるかを確かめよう。わたしの定義では、悲しみとは、人がより小さな力へと移るときの感情であり、愛とは、外の原因の観念をともなった喜びである。五年のあいだ、あの人の観念は、日々のさまざまな場面と結びついてきた。ゆえに、そうした場面に出会うたびに、心は必然的にあの人を思い、喜びのかわりに、失ったことの悲しみが生まれる。ふとした時に涙が出るのは、心が弱いからではなく、この結びつきが働いているからである。
では、どうすればよいか。感情を押し殺す必要はない。どの場面が、どの記憶を呼ぶのかを、一つずつ確かめていくことだ。原因が見えた感情は、あなたをただ振り回すものではなくなる。
そして、感情は、それより強い反対の感情によってしか退かない。小さくてよい。友との会話や、手を動かす仕事など、あなたの力を高める喜びを、毎日一つずつ増やしていくことである。', '["spinoza.affects","spinoza.passion-action"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'kierkegaard', 4, '理解しきるのを待たず、前を向いて生きよ', 'わたし自身、若いころに、愛する人との婚約を自分から解きました。理由はあったのに、その人のことは生涯、頭から離れませんでした。ですから、半年で忘れられないことを恥じる必要はないと、まず言わせてください。
あなたは今、「なぜ分からなくなったのか」を、後ろを振り返って理解しようとしているのかもしれません。それは必要な仕事です。けれど、理解が完成するのを待ってから歩き出そうとすると、人はいつまでも立ち止まったままです。皮肉なことに、「前に進みたい」と願うあなたは、もう半歩、進み始めています。
世間は「時間が解決する」と言うでしょう。けれど群衆の言葉は、あなたの代わりに悲しんでも、選んでもくれません。あの五年を自分の歴史として引き受け、そのうえで次の一歩を、ほかの誰でもないあなたが選ぶこと。あなたはいま、あなた自身であろうとしていますか。', '["kierkegaard.either-or"]', 'kierkegaard.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'epicurus', 5, '「あった、ありがとう」と思い出し、友と食卓を', 'あなたの涙を、わたしは無理に止めようとは思いません。五年という時間は、それだけ多くの喜びがあったという証ですから。
わたしは庭の仲間に、不運は、過ぎた善いことを感謝とともに思い出すことで癒やし、起きたことは取り消せないと知ることで静めなさい、と教えてきました。今のあなたは、思い出すたびに「失った」と感じているのでしょう。けれど、一緒に笑った日も、支え合った日も、確かにあったことで、誰にも奪えません。思い出したら「なくした」ではなく「あった。ありがとう」と言い換えてみてください。痛みはすぐには消えなくても、思い出が少しずつ喜びの側へ戻ってきます。
それから、ひとりで抱えないこと。気心の知れた友を呼んで、簡単な食事を一緒にとりなさい。心の平静を支えるのは、いつも友です。覚えておいてください。「あったことは消えない。友はここにいる」。', '["epicurus.ataraxia","epicurus.friendship"]', 'epicurus.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aiTPEFViwGUFbPlu', 'dogen', 6, '前へ進もうとするな。ただ今日の一事をせよ', '去った人を責めるな。引き止められなかった自分も責めるな。
そなたは「前に進みたい」と言う。だが、前とはどこか。時は、そなたの外を流れていくものではない。いまここに在ることが、そのまま時である。涙が出る時は、涙の時である。それを恥じて、早く次の時へ移ろうともがくから、かえって苦しい。
思い出して泣いたなら、泣けばよい。そのあと、顔を洗え。米を研ぎ、器を洗い、部屋を掃け。目の前の一事に、心を尽くしてせよ。進もうとして進むのではない。一事一事をしているうちに、気づけば道はもう足もとにある。
五年を忘れようとするな。忘れようとする心もまた、とらわれである。ただ、今日の一事をせよ。明日を待ってはならぬ。', '["dogen.uji"]', 'dogen.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('aiTPEFViwGUFbPlu', '5年の恋の終わり…半年たっても涙が出るのは当たり前です。全然おかしくないですよ。

ぬぬはらなりに、進めない理由を整理してみますね。
①「分からなくなった」という理由がふわっとしていて、心が納得できていない
②5年分の生活の習慣が、まだ体に残っている
③「早く忘れなきゃ」と焦るほど、かえって思い出してしまう

①には、言われた言葉と自分の気持ちを書き出すのがおすすめ。答えは出なくても、頭の中でぐるぐるするよりずっと楽になります。②は、休日の過ごし方や行く場所を少しずつ新しくしていくこと。③は、泣いた日は「今日はそういう日」でOKにしちゃいましょう。

5年もひとりの人を大切にできたあなたは、間違いなく人を愛せる人です。ぬぬはらはあなたの味方ですからね。', '["5fd10b80-4205-41df-94b7-3bc2e8730a52","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7","2271292a-2ff5-4b0a-8747-ead4a8d2b748"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('aiTPEFViwGUFbPlu', '5年付き合った恋人に「好きかどうか分からなくなった」と言われて別れました。半年たっても、ふとした時に思い出して涙が出ます。前に進みたいのに、どうしても進めません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('aIA8yvjCt40isl_B', 'curated', 'general', '好きになった人が自分を好きになってくれたと分かると、急に気持ちが冷めてしまいます。追いかけている間は夢中なのに、両思いになると逃げたくなります。自分はどこかおかしいのでしょうか。', 'love', '["crush","self-esteem"]', 0, 1791903480000, 1791903480000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'plato', 0, '恋は手に入れて終わらず、共に美を生むもの', 'あなたの言う「夢中」とは、何に向けられていたのだろうか。わたしが書いた対話『饗宴』で、ソクラテスは、人は自分に欠けているものをこそ恋い求めると語った。追いかけている間あなたを満たしていたのは、まだ手に入らないという欠けそのものだったのかもしれない。だから両思いになった途端に渇きが消え、恋まで消えたように感じる。それはおかしなことではなく、恋（エロース）の生まれつきの性質だ。
だが同じ対話でディオティマは、恋は手に入れたら終わるものではなく、美しいものの中で何かを生み出そうとする働きだと教えた。
次に心が冷めかけたら、自問してみてほしい。わたしはあの人の何を美しいと思ったのか。顔か、心か、それとも追いかける自分の姿か。影ではなく相手の魂そのものに目を向けたとき、恋は別の姿で続いていくだろう。', '["plato.eros"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'schopenhauer', 1, '君はおかしくない。欲望は叶えば退屈に変わる', '君はどこもおかしくない。おかしいのは、人間というものの作りのほうだ。欲しいものが手に入らないうちは苦しく、手に入ったとたんに退屈がやってくる。人生はこの振り子だと、わたしは書いた。追いかける恋とは、満たされない欲望がいちばん激しく燃える形にすぎない。相手が振り向いた瞬間、欲望は行き先を失い、振り子は退屈の側へ振れる。世の恋愛詩人たちは、この事実を美しい言葉で飾って隠してきただけだ。
だから、冷めた自分を責める必要はない。ただ一つ覚えておきたまえ。君を好きになったその人も、君と同じく苦しむ一個の生きものだ。逃げ出したくなったら、熱が冷めたかどうかではなく、その人の痛みを自分の痛みのように感じられるかを見てみることだ。燃える欲望より、その同情のほうが、ずっと長く人と人を結びつける。', '["schopenhauer.pendulum","schopenhauer.compassion"]', 'schopenhauer.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'fromm', 2, '落ちる恋は終わるもの。そこから愛する技術を学ぶ', 'まず、あなたはおかしくありません。そのうえで、少し一緒に見つめてみましょう。あなたが夢中になっていたのは、その人を愛することだったのでしょうか。それとも、その人に選ばれることだったのでしょうか。
見知らぬ二人の壁が急に崩れる「恋に落ちる」体験は、その性質上、長くは続きません。また今の社会では、恋が市場の取引のように、相手の「はい」を手に入れたら完了するものになりがちです。手に入ったとたん関心が消えるのは、あなた個人の欠陥というより、そういう愛し方を身につけてきた結果かもしれません。
愛は落ちるものではなく、練習して身につける技術です。次に逃げたくなったら、すぐに離れる前に、一つだけ与えてみてください。相手の話をよく聞く、相手の好きなものを知ろうとする。愛は、相手を知ろうとする小さな練習の中で育っていきます。', '["fromm.art-of-loving","fromm.marketing"]', 'fromm.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'spinoza', 3, '冷めたのは恋ではなく、希望と恐れの揺れかもしれない', 'まず、言葉を定めよう。希望とは、結果が疑わしい未来のものについての、不安定な喜びである。恐れとは、同じく疑わしいものについての、不安定な悲しみである。ゆえに、希望のあるところには必ず恐れがあり、心はその間を揺れ動く。
追いかけている間のあなたの「夢中」は、この揺れの激しさだったのではないか。相手の好意が確かになると、疑いの原因が取り除かれ、揺れは止まる。わたしはこれを安堵と呼んだ。揺れの止まった静けさを、あなたは「冷めた」と受け取ったのかもしれない。
これはあなたの異常ではなく、感情の必然的な仕組みである。そして感情の原因をはっきり理解するほど、人はそれに振り回されなくなる。揺れではなく、その人の本性を知ることから生まれる喜びがあるかどうか。それを静かに確かめてみるとよい。', '["spinoza.affects","spinoza.passion-action"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'kierkegaard', 4, '可能性に恋するのをやめ、現実を選ぶ決断を', 'あなたが夢中だったのは、その人というより「まだ決まっていない可能性」だったのかもしれません。追いかける恋は、手に入らないからこそ安全です。可能性の中では、あなたは何者にでもなれるし、何も失わない。ところが両思いという現実になると、あなたは一人の具体的な人間として見られ、選び、責任を負わなければならない。逃げたくなるのは、そのめまいの瞬間です。
わたしは『あれか、これか』で、楽しみを次々に追う生き方と、選んで引き受ける生き方を並べてみせました。前者は美しいが、いつも次の刺激を探して自分から逃げ続けます。告白すれば、わたし自身も、愛したレギーネとの婚約を自分から解いた人間です。偉そうなことは言えません。
それでも問わせてください。あなたはいま、可能性の中ではなく、現実のあなた自身であろうとしていますか。', '["kierkegaard.three-stages","kierkegaard.anxiety"]', 'kierkegaard.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'montaigne', 5, 'わたしも同じ。人は困難なものほど欲しくなる', 'わたしもそうでした、と白状しておきましょう。わたしは『エセー』の一章を「わたしたちの欲望は困難によって増す」と題したほどです。門が閉ざされていれば押し入りたくなり、開かれていれば素通りしたくなる。人間とは昔から、そういう移り気で矛盾だらけの生きものらしい。あなたがおかしいのではなく、あなたもまた人間だというだけのことに思えます。
もう一つ、わたしは恋の熱を、燃え上がっては揺らぐ熱病の火にたとえ、亡き友との友情を、むらのない穏やかなぬくもりにたとえました。両思いのあとの静けさは、火が消えたのではなく、熱がぬくもりに変わる入口なのかもしれません。わたしにはよく分かりませんが、逃げる前に少しだけ、そのぬくもりの中にいてみてはどうでしょう。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.self-portrait"]', 'montaigne.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('aIA8yvjCt40isl_B', 'nishida', 6, '像が崩れた所で、はじめて相手その人が現れる', 'そもそも、追いかけていたとき、あなたが見ていたのは相手その人であったろうか。それとも、相手に映した自分の思いであったろうか。
私は、物を知ることと物を愛することを、別々の働きとは考えない。いずれも、自己を棄てて相手と一つになることである。追いかける恋には、認められたい、勝ちたいという小さな自己が強く働いている。相手が振り向いたとき、その自己が描いていた像が崩れる。冷めるとは、その像が消えることではなかろうか。
しかし像が消えたところで、はじめて相手その人が現れるのである。「好きか、冷めたか」と判断を加える前に、共に過ごす時間の経験そのものに立ち返ってみるがよい。相手の声、しぐさ、考え方を、細工なしにそのまま知ろうとするとき、別の愛が始まるのではなかろうか。愛はそこから深まりうるのである。', '["nishida.knowledge-love","nishida.true-self"]', 'nishida.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('aIA8yvjCt40isl_B', '追いかけてる間は夢中なのに、両思いになると逃げたくなる…いわゆる蛙化現象ですね。どこもおかしくないです！同じことで悩んでる人、実はけっこう多いですよ。
ぬぬはら的には、まず『何がイヤになるのか』を分解してみるのがおすすめです。
①相手の好意が重たく感じる
②自分なんかを好きになる相手を信じられない
③追いかける過程そのものが好きだった
どれが近いかで対策が変わります。②なら、自分を低く見積もりすぎてるのかも。あなたを好きになった人の目は、たぶんそんなに節穴じゃないです（笑）
対策としては、気持ちを小出しに伝える練習がいいと思います。『ゆっくり距離を縮めたいな』と言えるだけで、逃げたくなる圧はだいぶ減りますよ。焦らなくて大丈夫、恋愛は失敗込みで上手になっていくものなので！', '["a38cd6ee-2a67-44af-a494-e02791dc0f4d","2271292a-2ff5-4b0a-8747-ead4a8d2b748","25b103aa-4d4d-4336-81ad-e9b2b5422670"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('aIA8yvjCt40isl_B', '好きになった人が自分を好きになってくれたと分かると、急に気持ちが冷めてしまいます。追いかけている間は夢中なのに、両思いになると逃げたくなります。自分はどこかおかしいのでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('NMSdDtMe49wl5BDJ', 'curated', 'general', '30代になり、周りの友だちが次々と結婚していきます。結婚したいのか、取り残されるのが怖くて焦っているだけなのか、自分でも分からなくなってきました。', 'love', '["marriage","future-anxiety"]', 0, 1791903420000, 1791903420000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'fromm', 0, '結婚を求める前に、愛する力を育てよう', '周りが結婚していく中で、自分の気持ちが分からなくなる。とても正直な戸惑いだと思います。
人は孤独や無力感に耐えきれないとき、周りと同じであることに逃げ込みやすいものです。「みんなが結婚するから」という焦りには、その同調の声が混じっているかもしれません。恥じることではありません。
ただ、多くの人は、愛を「よい相手さえ見つかれば起こるもの」と考え、相手探しにばかり心を向けます。けれど愛は、相手の問題である前に、あなたの愛する力の問題です。身近な人の話を最後まで集中して聞く。約束を守る。そうした小さな練習を重ねるうちに、あなたが本当に求めているのが「結婚という形」なのか、「誰かと深く与え合う生き方」なのかが見えてくるはずです。', '["fromm.art-of-loving","fromm.escape"]', 'fromm.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'epicurus', 1, 'その欲望は自然で必要なものか、見分けよう', 'あなたの戸惑いを、庭の木陰で一緒にほどいてみましょう。
わたしは欲望を三つに分けます。生きるのに自然で必要なもの、自然だが必要ではないもの、そして自然でも必要でもない、思い込みから来るもの。
誰かと親しく支え合って暮らしたい、という願いは自然なものです。けれど「友だちより遅れたくない」「三十代のうちに形にしなければ」という気持ちは、人と比べる思い込みから来ていて、満たしてもまた次の比較が始まるでしょう。
二つが混ざっているのは当然です。焦りの部分だけを、そっと脇に置いてみてください。それでも残る「この人と食卓を囲みたい」という願いが、あなたの本当の欲望です。
覚えておく一言はこれです。比べて生まれた欲は、満たしても静まらない。', '["epicurus.desires","epicurus.friendship"]', 'epicurus.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'kierkegaard', 2, '群衆の時計でなく、ひとりの自分として選べ', 'わたしは若いころ、愛する人との婚約を自分から解きました。結婚がどれほど重い決断かを知る者として書きます。
「周りが次々と結婚していく」。この言葉の中で、決めているのは誰でしょう。群衆は人を安心させますが、ひとりひとりから責任を取り上げます。みんなの歩調に合わせて結婚する人は、選んだのではなく、流されただけかもしれません。逆に、焦りを恐れて決断を避け続けるのも、別の仕方で自分から逃げることです。
あなたの戸惑いは、むしろよい兆しです。自分が何にでもなりうると気づいたとき、人はめまいを覚えるものですから。大事な問いには、両方を少しずつ取るやり方では答えられません。
だから問います。あなたはいま、群衆の一人としてではなく、あなた自身として、この問いの前に立っていますか。', '["kierkegaard.single-individual","kierkegaard.either-or"]', 'kierkegaard.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'montaigne', 3, '本心か焦りか、きれいに分けなくてもいい', '打ち明けると、わたしが妻をめとったのも、自分で選んだというより、世の習わしに運ばれてのことでした。わたしの行いの多くは、選択ではなく手本に従ったものです。
結婚は鳥かごに似ている、と書いたことがあります。外の鳥は入れなくて嘆き、中の鳥は出られなくて嘆く。外にいるあなたが中を気にするのも、人間らしいことです。
「本当に結婚したいのか、焦りなのか」。わたしにはよく分からないが、人の動機は、たいていその二つが混ざり合っているように思えます。わたし自身、自分の心をのぞくたびに、矛盾だらけの生きものを見つけます。きれいに分けてから決めようとすると、いつまでも決められません。
それに、よい結婚というものがあるなら、それは恋より友情に似ている、とわたしは考えました。これはわたしの試みにすぎない。あなたはあなたの判断で。', '["montaigne.self-portrait","montaigne.custom"]', 'montaigne.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'plato', 4, '指輪の影でなく、恋が求める「善いもの」を見よ', 'まず問いたいのです。あなたが結婚に求めているものは、何だろうか。
わたしが書いた対話『饗宴』で、ソクラテスは、ディオティマという賢い女性から恋（エロース）について教わった話をします。恋とは、自分に欠けている美しいものへの憧れであり、一人の美しい人への恋から始まって、美しい心、美しい営みへと、魂を一段ずつ高めていく階段なのだ、と。
友の結婚を見て胸がざわつくのは、洞窟の壁に映る影を見ているようなものかもしれません。式や指輪は影で、あなたが本当に焦がれているのは、その奥にある「善いものと共に生きること」ではないでしょうか。焦りは影を追わせ、恋は光の方へ向かわせます。
わが師なら、こう問うでしょう。友たちが手にしたものの中で、あなたが本当に美しいと思うのは、どれですか。', '["plato.eros","plato.cave"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'weil', 5, '空白を急いで埋めず、待つことを学ぶ', 'あなたはいま、どんな苦しみの中にいるのですか。友が一人ずつ去っていくような、置き去りにされる寂しさでしょうか。まず、その寂しさをごまかさずに見てください。
心に空白ができると、魂は重さに引かれるように、それを手近なもので埋めようとします。誰でもいいから、とにかく形を、と。けれど急いで埋めた空白は、たいてい、あとで別の苦しみを生みます。
空白に耐えることは、何もしないことではありません。待つことです。目の前の人に、自分の都合や期待をいったん止めて、注意を向けること。相手を「結婚の候補」としてではなく、その人そのものとして見ること。
焦りを責める必要はありません。ただ、空白を空白のまま持ちこたえてください。恵みが入ってくるのは、空白のあるところだけなのです。', '["weil.void","weil.attention"]', 'weil.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NMSdDtMe49wl5BDJ', 'adler', 6, 'その焦りは何のため？ 結婚は二人で取り組む課題', '焦っている自分に気づいて立ち止まれたこと自体が、もう一歩前に出ています。
わたしは、気持ちが何から生まれたかより、何のために使われているかを見ます。「取り残されるのが怖い」という焦りは、「友だちより劣った自分になりたくない」という目的に仕えているのかもしれません。だとすると、結婚が、人と比べて負けないための手段になってしまいます。
人生には仕事・交友・愛という三つの課題があり、どれも人との関係の中にあります。中でも愛と結婚は、二人で協力して取り組む課題です。問われるのは勝ち負けではなく、相手の幸せに関心を持てるかどうかです。
あなたは、本当はどうしたいのですか。「結婚したい理由」と「結婚しないと困る理由」を分けて書き出し、前者を信頼できる友に話してみましょう。', '["adler.teleology","adler.social-interest"]', 'adler.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('NMSdDtMe49wl5BDJ', '相談ありがとうございます！周りが結婚ラッシュだと、自分だけ電車に乗り遅れたような気分になりますよね。
ぬぬはら的には、「結婚したいのか、焦っているだけなのか」を見分けるのに、こんな思考実験がおすすめです。
①もし結婚という制度がこの世になかったとしても、誰かと一緒に暮らしたい？
②もし友だちが全員独身のままだったら、今ほど焦る？
①がYESなら本心の成分あり、②がNOなら焦りの成分多め、という感じです。
そもそも「何歳までに結婚」という物差しは、時代や国によってかなりバラバラな価値観です。焦りが混ざっていても全然ふつうなので、自分を責めなくて大丈夫。あなたのペースで、あなたが幸せになれる形を選んでくださいね。応援しております！', '["f1dc013d-a55a-489d-a26e-56e1598dae17","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7","b302d345-6def-4a65-9c25-c568ffcff306"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('NMSdDtMe49wl5BDJ', '30代になり、周りの友だちが次々と結婚していきます。結婚したいのか、取り残されるのが怖くて焦っているだけなのか、自分でも分からなくなってきました。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('deCKrq6mkhlQsOS7', 'curated', 'general', '20代後半ですが、一度も恋愛をしたことがありません。恋人がほしい気持ちはあるのに、容姿に自信がなく、誰かに好かれる自分が想像できなくて踏み出せません。', 'love', '["no-encounter","inferiority","self-esteem"]', 0, 1791903360000, 1791903360000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'fromm', 0, '「好かれるか」より「愛する力」を日々育てる', '「誰かに好かれる自分が想像できない」という言葉は、とても正直だと思います。ただ一緒に見つめたいのは、あなたが恋愛を「好かれるかどうか」の問題として考えていることです。多くの人は愛を、愛される問題、つまり自分が商品として選ばれるかどうかの問題だと考えています。容姿への不安も、自分を市場で値踏みする目から生まれているのかもしれません。けれど愛は、よい相手に出会えば自然に落ちるものではなく、規律と集中と忍耐で身につけていく技術です。その中心は、受け取ることより、自分の中の喜びや関心を分け合うことです。身近な人の話に心から耳を傾ける、小さな約束を守る。これは恋人がいなくても今日から練習できます。愛する力が育つにつれて、「好かれる自分」を思い描く必要は、少しずつ薄れていくはずです。', '["fromm.art-of-loving","fromm.giving"]', 'fromm.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'kenko', 1, '逢えぬ恋の切なさを知る人こそ、恋の分かる人', '満開の花や曇りのない月ばかりが見どころだと思うのは、どうも浅いものです。恋もそうで、思いが通じて逢うことだけを恋と呼ぶのではありません。逢えないままの切なさを思い、長い夜をひとりで明かし、遠くの人を思いやる。そういう心を知る人こそ、恋の味わいが分かる人だと、わたしは書きました。あなたが「恋人がほしい」とひとり思ってきた年月も、恋と無縁だったわけではないのです。顔かたちは生まれつきでも、心ばえは磨けば磨けるものです。ただし、ひとつだけきっぱり申し上げます。「いつか自信がついたら」と先へ延ばしてはいけません。後があると思うと、今の一回がおろそかになるものです。気になる集まりに一度顔を出す、誘われたら断らない。そのくらいの一歩を、今年のうちにどうぞ。', '["kenko.imperfect-beauty","kenko.this-moment"]', 'kenko.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'sartre', 2, '「好かれない人間」という本質など、君にはない', '君は「誰かに好かれる自分が想像できない」と書いた。だが君が思い描いているのは、他人のまなざしに値踏みされ、「容姿のよくない者」として固められた自分ではないか。見られるとき、私たちは自分が物になったように感じ、恥を覚える。それは誰にでも起こる。だが、そこから「自分はそういう人間だ」と結論を下すなら、それは自己欺瞞だ。人間には前もって決められた本質などない。「好かれない人間」として生まれた者は一人もいない。あるのは、君がこれまで踏み出さなかったという事実だけだ。そして、踏み出さないこともまた一つの選択だ。他人のまなざしは君を固めもするが、他人がいなければ、君は自分が何者かを知ることもできない。だから見られる怖さを抱えたまま、その中へ身を投じたまえ。', '["sartre.existence-precedes-essence","sartre.the-look"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'plato', 3, '欠けていると知る心こそ、恋の始まりだ', 'あなたは、自分が美しくないから恋はできない、と考えているようだ。では、ともに問うてみよう。恋するとは、そもそも何をすることだろうか。わたしが書いた『饗宴』で、ソクラテスはディオティマという女性から聞いた話を語っている。恋の神エロースは、工夫の神ポロスと貧しさの女神ペニアのあいだに生まれた。だからエロース自身は美しくも満ち足りてもいない。それゆえにこそ、美しいもの、善いものを求めてやまないのだ、と。恋は、すでに美しい者の特権ではない。自分に何かが欠けていると知る者の、魂の動きなのだ。あなたの感じる欠け目は、恋から締め出される印ではなく、恋する力の源でありうる。しかも恋は、顔かたちから美しい心、美しい営みへと昇っていく。まずは、心から美しいと思える人や営みを一つ見つけ、近づいてみてはどうだろう。', '["plato.eros"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'adler', 4, '容姿の悩みは、傷つかないための盾かもしれない', '劣等感そのものは、誰にでもあるものです。問題になるのは、それが「だから、わたしには無理だ」という理由として使われはじめたときです。少し考えてみてください。もし明日、容姿の悩みがすっかり消えたら、あなたはすぐに踏み出せるでしょうか。次は「話が下手だから」という理由が見つかるかもしれません。そうだとしたら、容姿の話は、断られて傷つくことからあなたを守る盾の役目をしているのです。責めているのではありません。傷つきたくないのは自然なことです。ただ、愛は、仕事や友人づきあいと並ぶ人生の課題で、どれも人との関係の中でしか取り組めません。恋の相手を探す前に、職場や趣味の場で、誰かの役に立つ小さなことを一つしてみませんか。仲間の中に居場所を感じられたとき、恋に踏み出す勇気も育ってきます。', '["adler.inferiority","adler.social-interest"]', 'adler.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'pascal', 5, '恋は理性の計算の外。顔はあなたの一部にすぎない', 'あなたは、自分の顔を勘定に入れて、好かれる見込みを計算しているように見えます。けれど、恋ほど計算の外にあるものはありません。わたしは書きとめました。恋の原因は、それと見分けられないほど小さな「何だかわからないもの」で、それが世界じゅうを動かしてしまう、と。また、こうも問いました。美しさのゆえに人を愛する者は、その人を愛しているのか。病が美しさを奪えば、その愛も消えるだろう、と。顔は、あなたという人のごく一部の性質にすぎません。人間は惨めです。自分の欠けを知り、それを見られるのを恐れる。けれど、それを知っていることこそ、人間の偉大さでもあります。理屈で自分を裁くのを少し休んで、あなたの心の理由に、耳を澄ませてみてください。', '["pascal.heart","pascal.misery-greatness"]', 'pascal.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('deCKrq6mkhlQsOS7', 'russell', 6, '自分の顔より、外の世界に興味を向けなさい', '率直に申しますと、あなたの悩みの中心にあるのは、容姿そのものより、「自分がどう見えるか」という問いに心を奪われていることのように思えます。私は不幸の大きな原因を、自分のことばかり考える習慣に見てきました。鏡の前で自分を採点し続ける人は、たいてい採点そのものに疲れてしまいます。皮肉なことに、人が人に惹かれるのは、顔立ちよりも、何かに生き生きと興味をもっている様子であることが多い。私は、愛されていないという感じが熱意を失わせ、愛されているという感じが熱意を育てる、とも書きました。ならば順番を逆にしましょう。山歩きでも合唱でも読書会でも、人の集まる趣味を一つ始めてみてください。恋人探しのためではなく、面白いから行くのです。恋はたいてい、そういう場所の脇道で見つかるものです。', '["russell.self-absorption","russell.zest"]', 'russell.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('deCKrq6mkhlQsOS7', '20代後半で恋愛経験なし、全然珍しくないです。焦らなくて大丈夫ですよ。

そして容姿について。年齢が上がるほど、恋愛で重視されるのは顔より「一緒にいて楽か」「価値観が合うか」になっていきます。むしろここからが、外見だけで勝負してきた人を追い越せる時期です。清潔感・姿勢・声のトーンあたりは、努力がそのまま結果に出るのでコスパがいいですよ。

あと一つ聞きたいのは、恋人ができたら何をしたいか。休日に一緒にご飯を食べたい？将来家族がほしい？目的が見えると、マッチングアプリ、社会人サークル、友だちの紹介…と選ぶ手段も決まってきます。

好かれる自分が想像できないなら、まずは誰かと過ごしたときに「楽しかった」と言葉で伝える練習から。これだけで印象はかなり変わります。', '["ce3c1658-7b7e-4d3d-a141-972fb099bd89","29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","a38cd6ee-2a67-44af-a494-e02791dc0f4d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('deCKrq6mkhlQsOS7', '20代後半ですが、一度も恋愛をしたことがありません。恋人がほしい気持ちはあるのに、容姿に自信がなく、誰かに好かれる自分が想像できなくて踏み出せません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('dkKxdwFf3nMI_xJi', 'curated', 'general', '恋人が異性の友だちと話しているだけで、強い嫉妬で頭がいっぱいになります。問い詰めたり予定を確かめたりしてしまい、このままでは嫌われると分かっているのに止められません。', 'love', '["jealousy","partner"]', 0, 1791903300000, 1791903300000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'plato', 0, '恋は囲うことでなく、共に美しいものを生むこと', 'あなたの言う『嫉妬で頭がいっぱいになる』とき、魂の中では何が起きているのだろうか。わたしが書いた対話『パイドロス』で、ソクラテスは魂を、御者と二頭の馬にたとえた。一頭は御者の言葉に従うが、暗い色のもう一頭は、手綱を振りきって駆け出そうとする。同じ対話には、欲望に引きずられる恋する者は、愛する人をほかの人々との交わりから遠ざけようとする、という話も出てくる。問い詰めや予定の確認は、この暗い馬の走りなのだろう。
けれど『饗宴』でソクラテスが語るように、恋は本来、善いものを求め、美しいものの中で何かを生み出そうとする力だ。恋人を囲いこむのではなく、二人で美しいものを育てる方へ、手綱を引き直してごらんなさい。御者である理性は、あなたの中にいる。', '["plato.tripartite-soul","plato.eros"]', 'plato.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'spinoza', 1, '嫉妬の原因を理解すれば、心は縛られなくなる', 'まず、嫉妬とは何かを確かめよう。愛する人が、かつて自分と結ばれていた以上の絆で第三者と結ばれていると想像するとき、人は愛する人を愛しながら同時に憎み、その第三者をねたむ。わたしは『エチカ』で、この愛と憎しみの間の心の揺れを、嫉妬と呼んだ。
ここで注目すべきは「想像する」という点である。恋人が友人と話している、という事実に、あなたの想像が絆の像を付け加え、その像が、あなたの力を下げる悲しみを生んでいる。問い詰めも予定の確認も、その悲しみから逃れようとする受け身の動きにすぎない。
ゆえに、責めるべきはあなた自身ではない。原因を一つずつはっきり理解することだ。理解が進むほど、感情はあなたを縛る力を失う。そして愛とは本来、相手を思うことにともなう喜びである。その喜びを育てることが、嫉妬を静める道となる。', '["spinoza.passion-action","spinoza.affects"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'epictetus', 2, '恋人の心は君次第でない。君次第は自分の判断だけ', '君に問おう。恋人が誰と話し、誰に笑いかけるか。それは君次第のものか、そうでないものか。そうでないものだ。恋人の心は、君の持ち物ではない。それを自分のもののように握ろうとするから、君は乱され、予定を確かめずにいられなくなる。
「でも先生、不安でたまらないのです」。よろしい。では、君を不安にしているのは、恋人が友人と話したという出来事か。それとも「自分は軽んじられた」という君の判断か。後者だ。そして判断こそ、君次第のものなのだ。
人間よ、小さなことから練習せよ。今日、問い詰めたくなったら、一度だけ口を閉じ、心に浮かんだ印象にこう言え。「おまえは印象にすぎない。見えているとおりのものではない」。これが心の平静の値段だ。安いものではないか。', '["epictetus.control","epictetus.impressions"]', 'epictetus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'miki', 3, '嫉妬は何も作らない。自信は物を作ることから', '嫉妬ほど忙しく、しかも何も生まない情念はない。君は恋人の予定を確かめ、相手の友人を思い浮かべ、問い詰める言葉を準備する。実に多忙である。だが、その忙しさから何が作られたか。
愛と嫉妬はよく似ている。どちらも烈しく想像力を働かせる。違いは、愛の想像力が何かを作り出すのに対し、嫉妬の想像力は相手を引き下ろすことにしか向かわない点にある。嫉妬は量の比較の上に働く。恋人の時間のうち、何割が自分に向いているかを数えはじめたとき、君はもう嫉妬の中にいる。
自信を持て、とよく言われる。だが自信は、自分に言い聞かせて生まれるものではない。その出どころは手の仕事である。恋人と二人で作るもの、君が一人で作るもの。その手を動かすことだ。', '["miki.jealousy"]', 'miki.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'fromm', 4, '不安を静める愛から、相手の自由を喜ぶ愛へ', 'まず、あなたがそれほど苦しんでいることを、責めずに受けとめたいと思います。そのうえで一緒に考えてみましょう。問い詰めたり予定を確かめたりするとき、あなたが本当に求めているのは何でしょう。おそらく「自分は失われない」という安心ではないでしょうか。
私は、未熟な愛と成熟した愛を区別しました。未熟な愛は、相手を、自分の不安を静めるための支えにしてしまいます。成熟した愛には、相手をありのままに見て、その人がその人らしく伸びていくことを願う「尊重」が含まれます。そして尊重は、自由の上にしか育ちません。
愛は技術です。練習が要ります。確かめたくなったら一呼吸おき、恋人が友人と過ごして楽しかったことを、一緒に喜べるか試してみてください。小さな練習の積み重ねが、愛する力を育てます。', '["fromm.art-of-loving","fromm.giving"]', 'fromm.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'kant', 5, '恋人を不安を静める道具にせず、尊敬の距離を', 'まず原則を立てよう。ものには値段があるが、人には値段ではなく尊厳がある。
そこで君に問う。恋人の予定を確かめ、誰と話したかを問い詰めるとき、君は恋人を、自分の不安を静めるための道具として扱ってはいないか。また、「不安なときは相手の行動を確かめてよい」という君の方針を、すべての恋人たちが採ったとしたらどうなるか。互いに見張り合う関係を、君は愛と呼びたいだろうか。
わたしは友情について、愛は二人を引き寄せ、尊敬は二人の間にふさわしい距離を保たせる、と論じた。どちらが欠けても、関係は長く続かない。恋人もまた、自分の理性で自分の交わりを選ぶ一人の人格である。どれだけの距離を保つかを決めるのは、君自身の理性だ。', '["kant.dignity","kant.categorical-imperative"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('dkKxdwFf3nMI_xJi', 'jung', 6, '嫉妬の相手に映る、自分の影を見つめて', '私は、愛と力は互いの影のような関係にあると考えました。問い詰めることや予定を確かめることは、相手を自分の手の内に置こうとする、力の働きです。あなたの中で、愛がその影と入れ替わる瞬間があるのかもしれません。
もう一つ、あなたの心に浮かぶ像に目を向けてみてください。恋人と話している異性の友人を、あなたはどんな人として思い描いているでしょう。気楽で、自由で、自分にはない魅力をもった人でしょうか。もしそうなら、その像には、あなたがまだ生きていないあなた自身の一面、つまり影が映っているのかもしれません。
影は追い払うものではなく、少しずつ自分のものにしていくものです。嫉妬が湧いたら、その人の何がうらやましいのかを書きとめてみてください。夢にその人が出てきたら、それも手がかりになります。', '["jung.shadow"]', 'jung.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('dkKxdwFf3nMI_xJi', '嫉妬で頭がいっぱいになるの、本当にしんどいですよね…。でも「このままでは嫌われる」と自分で気づけている時点で、あなたはもう半分抜け出しかけていると思います。ぬぬはらからは2つだけ。

①嫉妬そのものは悪くない
嫉妬は誰の心にも備わっている、ごく普通の反応です。問題は感情ではなく、問い詰める・確かめるという「行動」のほう。感情は止められなくても、行動は少しずつ変えられます。

②確かめる代わりに、気持ちを伝える
「友だちと話してるのを見て、ちょっと妬いちゃった」と、責めずに気持ちだけ伝えてみてください。問い詰めは相手を疲れさせるけど、素直な自己開示はむしろ関係を近づけてくれます。

あと、嫉妬は自分が本当は何を不安に思っているかを教えてくれるサインでもあります。その力を自分磨きに回せたら最強です。応援しています！', '["03ca3585-20a7-4972-8dde-3d6080ee0c89","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('dkKxdwFf3nMI_xJi', '恋人が異性の友だちと話しているだけで、強い嫉妬で頭がいっぱいになります。問い詰めたり予定を確かめたりしてしまい、このままでは嫌われると分かっているのに止められません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('hVZKbBwbo2Dkef7T', 'curated', 'general', '親が私の仕事や結婚にいちいち口を出してきます。育ててもらった感謝はあるし、悪気がないのも分かっています。でも電話が来るたびに気が重く、正直しんどいです。', 'family', '["parents"]', 0, 1791903240000, 1791903240000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'confucius', 0, '敬いは保ちつつ、穏やかに自分の考えを伝えなさい', '育ててもらった恩を感じ、親に悪気がないことも分かっている。それがもう、孝のいちばん大事なところです。わたしは弟子に、親をただ養うだけなら犬や馬にもしている、敬う心がなければ違いはない、と話しました。けれど孝は、親の言葉にすべて従うことではありません。仕事や結婚について考えが違うときは、穏やかに、言葉を選んで伝えなさい。すぐに聞き入れられなくても、敬う心をなくさず、恨まないことです。君子は和して同ぜず、とも言います。仲よくすることと、何でも同じ意見になることは別のものです。まず身近なところから始めなさい。便りを待つのではなく、ときにはあなたから近況を知らせ、日々の働きぶりを落ち着いて話すとよい。親の心配は、知らないことから大きくなるものです。わたしも、人との接し方を学び続けている途中です。', '["confucius.filial-piety","confucius.junzi"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'epictetus', 1, '親の口出しは君次第でない。どう応じるかが君次第だ', '人間よ、まず分けてみよう。親が何を言うか、君の結婚や仕事をどう思うか。それは君次第のものか。違う。では、君の言う電話のあとに胸を重くしているものは何か。親の言葉そのものか、それとも『また口を出された』という君の判断か。『でも先生、毎回言われるのはつらいのです』。そうだろう。だが言葉は声にすぎない。それに同意するかどうかを決める君の意志は、親にも、ゼウスにさえ奪えない。そして君には、子という役がある。よい役者は、相手役のせりふに腹を立てず、自分の役をきちんと演じる。礼をつくして聞き、落ち着いて答え、感謝を伝える。それが子の務めだ。そのうえで、どう生きるかを選ぶのは君の意志だ。次に声が届いたら、出る前に自分に言え。『これは印象にすぎない』と。まず、その小さな練習から始めよ。', '["epictetus.roles","epictetus.judgment"]', 'epictetus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'mill', 2, '助言は聞いても、最後に決めるのはあなた自身です', 'あなたの悩みを、両方の側から考えてみましょう。一方では、親の言葉にも聞くべきところがあるかもしれません。反対の意見にさらされることで、自分の考えは借り物でない、生きた確信になるからです。他方では、仕事や結婚は、まずあなた自身に関わる事柄で、その結果を毎日生きるのもあなたです。わたしは『自由論』で、そうした事柄について、他人は判断の助けになる考えや励ましを差し出すことはできても、最後に判断するのは本人だと書きました。親の意見を退ける必要はありませんが、従う義務もないのです。わたし自身、父から厳しい教育を受け、父を深く尊敬しながらも、二十歳のころ、自分の感情は自分で育てなければならないと知りました。『意見はありがたく聞く。決めるのは自分だ』と、一度落ち着いて伝えてみてはどうでしょう。それは長い目で見て、親とあなたの双方の幸福を増やすはずです。選ぶのはあなたです。', '["mill.individuality","mill.free-discussion"]', 'mill.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'beauvoir', 3, '口出しの奥にある、親自身の状況に目を向けて', 'まず、あなたの状況を聞き分けさせてください。口出しされているのは仕事と結婚。どちらも、世間が『この年なら、こうあるべき』という型を持ちやすい事柄ですね。その『こうあるべき』は、親御さんが決めたというより、親御さんもまた社会から受け取ってきたものかもしれません。次に、親御さんの状況も見てみましょう。子を育てることが長く人生の中心だった人にとって、子が手を離れることは、打ち込む目的を一つ失うことでもあります。わたしは『老い』で、年を重ねても人や世界に向かう目的を持ち続けることが大切だと書きました。口出しは、行き場をなくした心配なのかもしれません。あなたの自由を本気で望むなら、親御さんの自由も望むことになります。あなたの選択は守りながら、電話の話題を、あなたのことから親御さん自身の毎日や楽しみへ、少しずつ移してみてはどうでしょう。', '["beauvoir.freedom-of-others","beauvoir.situation"]', 'beauvoir.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'fromm', 4, '自分の中に父と母をもち、親とは大人どうしに', '『感謝はある、悪気がないのも分かる、でもしんどい』。その気持ちの両方を、私はそのまま受けとめます。私は『愛するということ』で、母親の愛の本当の試練は、子が自分から離れていくことを望み、支えられるかどうかにあると書きました。成長した子を手放すのは、親にとっても技術のいる、難しい愛の仕事なのです。一方、成熟した人は、やがて自分の中に母と父をもつようになります。自分をそのまま受け入れる声と、理性で自分を導く声です。親の電話がこれほど重いのは、その声をまだ親に預けたままの部分があるからかもしれません。あなたが本当に求めているのは、親に認められることでしょうか、自分の足で立つことでしょうか。そのうえで、親には受け取るより与える愛で向き合ってみてください。近況や喜びを、自分から分かち合うのです。依存ではない、大人どうしの関係は、そこから育ちます。', '["fromm.art-of-loving","fromm.giving"]', 'fromm.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'laozi', 5, 'ぶつからず、水のように流れて、自分の道を行く', '岩に向かって、水は怒らない。
脇を流れて、海へ行く。

親の言葉を、岩と思えば重くなる。
押し返せば、岩はもっと大きく見える。
言い負かそうとすれば、話は戦になる。

水は争わない。けれど、止まりもしない。
低い所を通り、形を変え、
それでも行きたい所へ行く。

生きている草木は柔らかく、
枯れたものは硬くこわばる。
あなたの心も、親の声の前で固くなっていないか。

『心配してくれてありがとう』と受け、
自分の道は、静かに歩けばよい。
争わない者とは、誰も争えない。

感謝も、しんどさも、どちらも本当。
水は両岸を抱いて流れる。', '["laozi.water","laozi.soft-weak"]', 'laozi.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('hVZKbBwbo2Dkef7T', 'freud', 6, '感謝と反発は同居してよい。重さは心の中の古い声', '興味深いのは、あなたが『しんどい』と言う前に、『感謝はある』『悪気がないのも分かっている』と、まず親を弁護していることです。まるで、重さを感じることにさえ許可が要るかのようです。人は親に対して、愛情と反発を同時に抱くものです。これは恩知らずではなく、ごく人間的な両価性です。私は、子どもの頃に取り込んだ親の声が、のちに心の中で良心として命じ続けると考え、それを超自我と呼びました。電話が鳴る前から気が重いのは、いまの親の言葉だけでなく、心の中のもっと古い親の声が一緒に鳴っているからかもしれません。これは仮説にすぎませんが、確かめる方法はあります。電話の最中、自分がいくつの子どもに戻ったように感じるか、気づいたことを書きとめてみてください。言葉にできたものは、少しずつ、あなたの手に戻ってきます。', '["freud.id-ego-superego","freud.transference"]', 'freud.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('hVZKbBwbo2Dkef7T', '親の口出し、しんどいですよね。悪気がないぶん、怒るに怒れないのがまたつらい。ぬぬはらのおすすめは『親を説得しようとしない』です。

①親の心配は親のものとして預けておく（全部に答えなくてOK）
②電話は最初に『今日は30分だけね』と時間を決めちゃう
③近況はこちらから先に小出しにする。情報が少ないほど親は不安になって口を出したくなるものです

親世代の『普通』は、今とはだいぶ違います。どっちが正しいかで戦うより『そういう時代を生きてきた人なんだな』と理解してしまうほうが消耗しません。感謝しながら距離をとるのは、全然親不孝じゃないですよ。あなたの人生のハンドルは、あなたが握っていて大丈夫です。応援しています！', '["f1dc013d-a55a-489d-a26e-56e1598dae17","436698e9-d5ca-45d4-8f4b-2e11ac3436b5"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('hVZKbBwbo2Dkef7T', '親が私の仕事や結婚にいちいち口を出してきます。育ててもらった感謝はあるし、悪気がないのも分かっています。でも電話が来るたびに気が重く、正直しんどいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('NEEWreGH54-rg-4y', 'curated', 'general', '一人暮らしの父の介護が始まり、仕事との両立で毎日余裕がありません。休みの日も実家に通い、友だちとも会えなくなりました。自分の人生がなくなっていく気がします。', 'family', '["caregiving","no-time","loneliness"]', 0, 1791903180000, 1791903180000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'seneca', 0, '父のための時間も、自分で選べば君の人生だ', '君の手紙を読んだ。父上の介護と仕事に追われ、休みの日も実家へ通い、友とも会えない。自分の人生がなくなっていく、と君は書く。親しい友よ、わたしは『人生の短さについて』で、他人や雑事に時間を奪われる生き方をいさめた。だが、父上のための時間は浪費ではない。君が引き受けた務めであり、君の人生そのものの一部だ。本当に君から時間を奪うのは、疲れと心配に押し流されて、自分で選んでいるという感覚まで失うことのほうだ。わたしも完成した賢者ではなく、雑事に一日を取られて悔やむ夜がある。だから一つだけ勧めたい。眠る前に一日を振り返り、今日自分のために使えた時間を、ほんの数分でも数えてみることだ。行き帰りの道で読んだ一頁、友への短い手紙でもいい。取り戻した時間は小さくても、確かに君のものだ。では、元気で。', '["seneca.time","seneca.evening-review"]', 'seneca.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'beauvoir', 1, '介護を一人の問題にせず、状況ごと変えていく', 'あなたは今、どんな状況に置かれているでしょう。仕事があり、一人で暮らすお父さんがいて、休日は実家との往復で消えていく。自由は、心の持ち方だけで取り戻せるものではありません。状況そのものがあなたの自由を奪っているなら、状況を変える行動が要ります。わたしは『老い』で、老いは体の衰えだけでなく、社会が老いた人をどう扱うかの問題でもあると書きました。それを家族の誰か一人に背負わせる仕組みは、当たり前のものではありません。子なら自分を犠牲にして当然、という「こうあるべき」は、誰が決めたものでしょう。お父さんの自由とあなたの自由は、奪い合うものではなく結びついています。お父さんがどんな暮らしを望んでいるのかを一緒に確かめ、きょうだいや親族、地域の相談窓口や介護の専門家と分け合う形を探してください。ひとりで抱え込まないことが、二人の自由を守る道です。', '["beauvoir.old-age","beauvoir.situation"]', 'beauvoir.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'confucius', 2, '回数より、穏やかな顔で父に会えることが孝だ', '毎週実家に通い、仕事もおろそかにしない。あなたはもう、十分に孝を尽くそうとしています。ただ、一つ考えてほしいことがあります。弟子に孝を問われたとき、わたしは、ただ親を養うだけなら犬や馬にもしている、敬う心がなければ何が違うのか、と答えました。別の弟子には、難しいのは親の前でやわらかな顔色を保つことだ、と言いました。孝の芯は通う回数ではなく、親を敬い、穏やかな顔で向き合う心にあるのです。わたしは、進みすぎる弟子には控えよと言い、ためらう弟子には進めと言ってきました。あなたは今、進みすぎている側です。疲れ果てて険しい顔で通い続けるより、人の手も借りて回数を減らし、会うときは落ち着いて話を聞くほうが、孝に近いこともあります。まず今週、通わない日を一日決めなさい。その日は、自分を養う日としなさい。', '["confucius.filial-piety"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'epicurus', 3, '友と会う小さな時間を、必要なものとして守る', 'あなたの手紙で、わたしがいちばん気にかかったのは、友だちとも会えなくなった、という一行です。わたしは、幸せに生きるうえで、友情ほど大きな宝はないと考えてきました。安心して頼り合える仲間がいることが、心の平静を支えるからです。ですから、友と会う時間は、忙しいときに真っ先に削ってよいぜいたくではありません。生きるのに必要なものの側に入れてください。そのかわり、削れるものがないか、一緒に見てみましょう。実家の家事をすみずみまで完璧にすること、何もかも自分の手でやること。それは本当に、生きるのに必要なものでしょうか。食事は質素でかまいません。月に一度、近くの友とパンとスープの短い食事をする。それだけでも、心はずいぶん違います。覚えておいてください。必要なものを守り、そうでないものを手放せば、人は少しのもので満ち足ります。', '["epicurus.friendship","epicurus.desires"]', 'epicurus.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'mill', 4, '父の幸福も、あなたの幸福も、同じ重さで数える', '一方では、お父さんの暮らしを支えたいという気持ちがあり、それは尊いものです。他方では、あなたは友と会えず、自分の人生が消えていくと感じている。どちらも本物の重さをもっています。わたしは、正しい行いとは、関わる人すべての幸福をできるだけ増やすものだと考えます。ここで忘れてはならないのは、その「すべて」に、あなた自身も一人分として含まれることです。あなたの幸福を勘定から外した計算は、公平ではありません。では、どんな形なら二人の幸福が最も大きくなるでしょう。介護の一部をほかの人や公の仕組みに任せ、空いた時間で友に会うあなたは、疲れ切ったあなたより、お父さんにとってもよい話し相手かもしれません。わたしも若いころ深い憂うつに沈み、喜びを感じる力を失いかけたことがあります。だからこそ言えます。どう分けるかを選ぶのは、あなた自身です。', '["mill.greatest-happiness"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'shinran', 5, '苛立つ自分のままで、すでに抱きとられている', '毎日の介護の中で、ふと父上にきつい言葉を返したり、なぜ自分ばかりがと思ったりすることはないでしょうか。もしあっても、どうかそれを恥じないでください。この親鸞も、怒りや欲やねたみを、一生かけても断ちきれない凡夫です。善い子であろう、立派に尽くそうと思っても、そうなりきれない。それが人のありのままの姿なのだと、わたしは思っております。阿弥陀仏の願いは、そういう善くなりきれない者をこそ目当てにしてくださっている、とわたしはいただいてきました。ですから、自分を責めて削ることで、介護を立派なものにしなくてよいのです。わたしもまた、妻子とともに暮らし、思うにまかせぬ日々を生きました。重さを感じたら、ひとりで抱えず、近くの人に正直に打ち明けてみてください。共に歩む仲間は、あなたのそばにもきっといます。', '["shinran.bonbu"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('NEEWreGH54-rg-4y', 'kenko', 6, '盛りでない日々にも、味わいはある', '雨の夜に見えない月を恋しく思い、散りしおれた庭をながめるのも、なかなか味わい深いものです。わたしは昔、そんなことを書きました。あなたの今の暮らしは、たしかに花盛りではないでしょう。休みは実家との往復に消え、友にも会えない。けれど、人生がなくなったのではなく、季節が変わったのだと思ってみてはどうでしょう。実家へ通う道の風の匂い、父上がふともらす昔話。盛りの日には見落としていたものが、こういう時にこそ見えてくるものです。それから、何事もすっかりととのえてしまうのは、かえってよくないものです。やり残しがあるくらいのほうが、長持ちします。手を抜けるところは、抜くのがよいでしょう。ただし、会いたい友への一言だけは、先延ばしにしてはいけません。', '["kenko.imperfect-beauty"]', 'kenko.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('NEEWreGH54-rg-4y', '介護と仕事の両立、本当におつかれさまです…。毎週実家に通っているだけで、もう十分すぎるくらい頑張ってます。

ぬぬはら的に整理すると、今のしんどさは①時間がない ②一人で背負っている ③自分の楽しみがゼロ、の3つが重なっているからだと思います。

✦①と②
介護は家族だけで抱えるものじゃないです。昔は大家族で分担していたことを、今は一人でやろうとしてるんだから、しんどくて当然。住んでいる地域の「地域包括支援センター」に相談すると、使えるサービスを一緒に考えてもらえます。

✦③
友だちとの時間は「余裕ができたら」じゃなくて、先に予定に入れちゃいましょう。30分の電話でもOK。

あなたが元気でいることが、結局お父さんのためにもなります。ぬぬはらは応援してますよ。', '["29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","69a91e29-de62-4f44-adb8-ff9726053389"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('NEEWreGH54-rg-4y', '一人暮らしの父の介護が始まり、仕事との両立で毎日余裕がありません。休みの日も実家に通い、友だちとも会えなくなりました。自分の人生がなくなっていく気がします。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('KRRz_IB8E-sXHvpv', 'curated', 'general', '結婚して10年になります。けんかをするわけではないのですが、夫婦の会話がほとんどなくなりました。このまま同じ家で他人のように暮らしていくのかと思うと寂しいです。', 'family', '["spouse","loneliness"]', 0, 1791903120000, 1791903120000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'aristotle', 0, '友愛は共に過ごす営みで育つ。小さな習慣を一つ', 'まず言葉を整理しよう。君の寂しさは、夫婦の友愛が働かなくなったことへの寂しさだと思われる。わたしは、夫婦のあいだの友愛はごく自然なものだと考えた。そして友愛には、役に立つから、楽しいから、相手の人柄が善いから、の三種類がある。十年の暮らしの中で、家を回すための「役に立つ」結びつきだけが残ってはいないだろうか。昔から言われるように、語らいのなさは多くの友愛を解いてきた。離れていても友愛そのものはすぐには消えないが、その働きは止まってしまうのだ。友とは共に生きる者で、酒を好む者は共に飲み、学ぶ者は共に学ぶ。だから、話題を無理に探すより、共にする営みを一つ持つとよい。週に一度の散歩、一緒に作る料理、何でもよい。友愛も徳と同じく、行いを繰り返すことで育つ。焦らず続けることだ。', '["aristotle.philia","aristotle.habituation"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'laozi', 1, '言葉は少なくてよい。水のように低く寄りそう', '言葉が減った。
それは、枯れたということだろうか。
多く語ることが、近いということではない。
大きな音は、かえって耳に届かない。

けれど、寂しいと感じるなら、その寂しさも本当だ。
話そう、話させようと力むほど、言葉はこわばる。
大きな話はいらない。
椀に湯を注いで、そっと置く。
同じ灯りの下で、黙って隣に座る。
「今日は寒いね」と、ひとこと置く。

水は、争わない。
高い所から説かず、低い所へしみこんで、すべてをうるおす。
あなたが先に、低い所へ行けばよい。
返事を急がない。

十年かけて静かになったものは、一晩では戻らない。
それでいい。
水は、ゆっくりと石をまるくする。', '["laozi.wu-wei","laozi.water"]', 'laozi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'weil', 2, '話題を探すより、相手の今に注意を向ける', 'あなたは、同じ家で他人のように暮らす寂しさの中にいるのですね。その寂しさを、急いで何かで埋めようとしないでください。会話を増やそうとして話題を探すことは、ときに、相手ではなく沈黙を埋めるための作業になります。わたしが大切だと思うのは、注意です。自分の期待や「こうあってほしい夫婦の姿」をいったん脇に置き、目の前のその人を、ありのままに見ること。十年いっしょにいると、人は相手を見ずに、相手についての思い込みを見るようになります。今日、その人は何に疲れ、何を気にかけているのでしょうか。あなたは知っていますか。知らないなら、それを問うことから始められます。答えがすぐ返ってこなくても、待つこと。注意とは、待つことでもあるのです。', '["weil.attention","weil.void"]', 'weil.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'beauvoir', 3, '役割の夫婦から、二つの自由が出会う夫婦へ', 'まず、あなたが今どんな状況にいるのかを見てみましょう。仕事、家事、子どものこと、親のこと。十年のあいだに、二人はそれぞれの役割をこなす分担者になっていないでしょうか。役割は暮らしを回してくれますが、役割どうしの間には、用件の言葉しか生まれません。「結婚して長くなれば会話が減るのは当たり前」という見方も、誰かが決めたものにすぎないのです。わたしは、人が生き生きと語り合えるのは、それぞれが自分の目指すものを持ち、外へ開かれているときだと考えます。あなた自身が打ち込めることを持ち、相手にもそれを持つ自由を願うこと。そして、どちらかが家のことを一人で抱えこんでいるなら、その状況そのものを二人で変えることです。今週、相手に「最近、何に夢中になっている？」と聞いてみてください。', '["beauvoir.situation","beauvoir.freedom-of-others"]', 'beauvoir.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'nishida', 4, '知り尽くしたつもりを捨て、相手をもう一度知る', '十年を共にした人を、あなたはよく知っていると思っておられるであろう。だが、その「知っている」は、本当に相手を知っていることであろうか。長く暮らすうちに、私たちは目の前の人そのものではなく、自分の頭の中にできあがった「夫」や「妻」という像と暮らすようになる。言葉が尽きたように感じるのは、相手が尽きたのではなく、こちらの見方が固まってしまったからではなかろうか。そもそも経験とは、こちらの思い込みを加えず、ありのままを受けとることである。今夜、食卓の向こうの人を、初めて会った人のように見てみるとよい。どんな顔で食べ、何に目をとめるか。相手を新しく知ろうとすることは、そのまま相手を愛することにほかならない。そこから、言葉はおのずと生まれてくるのではなかろうか。', '["nishida.knowledge-love","nishida.pure-experience"]', 'nishida.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'jung', 5, '他人に見えるのは、二人が次の段階に入るしるしかも', '結婚して十年というのは、多くの夫婦にとって一つの転換期です。家を整え、仕事に励み、ときに子を育てる。人生の前半の計画どおりに二人で走ってきたあと、ふと立ち止まると、隣の人が見知らぬ人のように見えることがあります。私は、これを必ずしも終わりのしるしとは考えません。若いころ、人は相手に自分の心の中の像を重ねて見ています。その像が薄れたとき、はじめて相手の本当の姿が現れるのです。他人のように見えるのは、そのためかもしれません。また、役割の仮面どうしで暮らすうちに、仮面の奥の自分を見失っていることもあります。あなたの寂しさは、心が次の段階を求めている知らせかもしれません。最近見た夢や、心に浮かぶ情景を、相手に話してみてはどうでしょうか。', '["jung.individuation","jung.persona"]', 'jung.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KRRz_IB8E-sXHvpv', 'carnegie', 6, '今夜、心からの感謝を一言。相手の好きな話を聞く', 'けんかもせず十年、家庭を守ってこられたのは、それだけで立派なことです。そのうえで寂しいと感じるのは、あなたが相手との心のつながりを大切に思っているからでしょう。私は、人を動かすための原則と並べて、幸福な家庭をつくるための原則も書いたことがあります。そこで大事にしたのは、相手を変えようとしないこと、心からの感謝を言葉にすること、ささやかな心づかいを忘れないことでした。長く一緒にいると、ありがとうの一言がいちばん省かれやすいのです。そして会話は、自分が話したいことより、相手が関心を持っていることから始まります。今夜、一つだけ試してみませんか。「いつもありがとう」と伝え、相手が最近夢中になっていることについて、一つ質問してみるのです。きっと何かが動き出します。', '["carnegie.importance","carnegie.other-viewpoint"]', 'carnegie.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('KRRz_IB8E-sXHvpv', '10年一緒にいて、けんかもしないって実はすごいことなんですよ。そのうえで寂しいと感じるのは、相手との関係をまだ大切に思っている証拠だと思います。

会話が減るのは、相手に興味がなくなったからというより「話さなくても生活が回るようになった」からのことが多いです。安定した結果なので、悪いことばかりではありません。

ぬぬはらのおすすめは、
①一緒にやる小さなイベントを作る（新しいお店に行く、同じドラマを見る、散歩するなど）
②「今日どうだった？」より「これ知ってた？」と話題を持ちこむ
です。共通の話題が一つできると、会話は意外と戻ってきます。

それでも寂しさが続くなら、「最近ちょっと寂しいんだよね」と素直に伝えてみるのもアリです。やわらかく言えば、責める言葉にはなりませんよ。', '["f1dc013d-a55a-489d-a26e-56e1598dae17","2760624a-d7b8-4328-8784-c0ec76ef2c47","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('KRRz_IB8E-sXHvpv', '結婚して10年になります。けんかをするわけではないのですが、夫婦の会話がほとんどなくなりました。このまま同じ家で他人のように暮らしていくのかと思うと寂しいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('AzGEhjVUwP6ycSHi', 'curated', 'general', '5歳の子どもに、つい大きな声で怒鳴ってしまいます。寝顔を見ると申し訳なくて泣きたくなるのに、次の日もまた同じことをしてしまいます。いい親になれる自信がありません。', 'family', '["parenting","anger"]', 0, 1791903060000, 1791903060000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'seneca', 0, '怒りは判断から生まれる。口を閉じて間をおけ', '親しい友よ、君の手紙を読んだ。寝顔を見て泣きたくなる君は、もう半分、治療を始めている。わたしも怒りについて書いたが、書いた本人が怒らずにいられたわけではない。同じ病室の病人として話そう。
怒りは子を正すのに役立つ、と言う人もいる。わたしはそう思わない。怒りは、どこからともなく襲う嵐ではなく、「この子はわざと困らせている」「言うことを聞かないのは許せない」という判断に、心が同意したときに燃え上がるものだ。だから、怒りを感じた瞬間に言葉にしないこと。口を閉じ、その場を数歩離れよ。判断が落ち着くまで、舌に仕事をさせるな。
もう一つ。君は夜、寝顔の前で一日を振り返っている。それを泣くためでなく、治すために使え。「今日はどの場面で怒ったか。その前に何を判断したか。明日はどうするか」。わたしも毎晩、灯りを消してからそうしている。では、元気で。', '["seneca.anger","seneca.evening-review"]', 'seneca.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'aristotle', 1, '怒らない親でなく、ちょうどよく怒れる親に', 'まず言葉を整理しよう。君は「怒鳴ってしまう」ことと「怒ること」を、同じものと思っていないだろうか。わたしの考えでは、怒りそのものは悪ではない。五歳の子が道に飛び出したなら、強く止めるべきだ。徳とは、しかるべき時に、しかるべき事柄について、しかるべき程度に怒ることであり、怒りすぎも、怒らなさすぎも、どちらも的を外す。
そこで、明日から一つ試してほしい。怒りそうになったら、自分に「これは危険なのか、それとも自分が急いでいるだけか」と問うことだ。危険なら、短くはっきり言う。急いでいるだけなら、声を落とす。弓で的に近づくには、外すたびに少しずつ狙いを直すしかない。
徳は生まれつきではなく、行いの繰り返しで身につく。「いい親になれる自信」は、なる前に持つものではない。ちょうどよい叱り方を一度するたびに、君は少しずつ、その親になっていく。', '["aristotle.mean","aristotle.habituation"]', 'aristotle.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'alain', 2, '怒鳴る原因は、性格より疲れた体にある', '泣きやまない赤ん坊を前に、人はあれこれ理由を考える。だが、産着のピンが一本刺さっているだけかもしれない。あなたの怒鳴り声も、同じではないだろうか。
怒鳴ってしまうのは、朝の支度で急いでいるとき、夕方くたびれて空腹のとき、寝不足の日ではありませんか。そうなら、原因は「いい親になれない私」という大きな話ではなく、肩のこわばりと、すり減った体にある。だから、心を責める前に体を変えるのです。声が大きくなりかけたら、まず息を吐き、肩を落とし、子どもの目の高さまでしゃがんでごらんなさい。しゃがんだまま怒鳴るのは、意外とむずかしい。
夕方の前に、何か一口食べておくこと。眠れる夜は、さっさと眠ること。上機嫌は、あなた一人のためのものではない。家の中の天気を決めるのは、あなたの顔なのです。', '["alain.bucephalus","alain.duty-to-be-happy"]', 'alain.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'wang-yangming', 3, '子育ての場面こそ、心を磨く修行の場だ', '寝顔を見て申し訳なく思う、その心。それこそが良知です。何が善く、何がいけないかを知る力は、あなたの中にもう備わっている。いい親の手本を、外に探しに行く必要はありません。
ただ、わたしはこうも言ってきました。知っていて行わないのは、まだ本当には知っていないのだと。夜には分かっているのに、昼にはまた怒鳴ってしまう。それは良知がないからではなく、その時その場で、急ぎや苛立ちという私欲の雲が、心の鏡をくもらせているからです。
ですから、静かな場所で反省を重ねるだけでなく、まさに子どもと向き合うその場面で、心を磨きなさい。子育ては、それ自体があなたの修行の場です。声を上げそうになった瞬間に、一度だけ自分の心に問うてみなさい。「良知は、いま何と言っているか」。今日、一度だけでよい。それを行ってみなさい。', '["wang-yangming.innate-knowing","wang-yangming.training-in-affairs"]', 'wang-yangming.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'laozi', 4, '背伸びをやめ、子の柔らかさに学ぶ', '「いい親」になろうと、つま先で立っていないだろうか。
力むほど、声は硬くなる。

硬いものは折れる。
柔らかいものは、折れない。
天下に水より柔らかいものはない。
それでいて、硬いものを攻めるのに、水にかなうものはない。

赤子を見てごらんなさい。
一日じゅう泣いても、声はかれない。
骨は弱く、筋は柔らかいのに、握る手はしっかりしている。
あなたが学ぶべきものは、遠くの立派な親ではなく、目の前の子の柔らかさかもしれない。

怒鳴ったあとに悔やむのは、あなたの中に柔らかいものが残っている証。
大きな声より、低い声。
押すより、待つ。
強く握るほど、こぼれる。

明日、一度だけ、声を低くしてみるといい。
千里の道も、足もとから。', '["laozi.soft-weak"]', 'laozi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'beauvoir', 5, '「いい親」の像を疑い、ひとりで背負わない', 'まず、あなたが今どんな状況にいるのかを考えてみたいのです。一日のうち、子どもと二人きりの時間はどれくらいありますか。眠れていますか。仕事や家事を、誰とどう分けていますか。怒鳴ってしまう場面の多くは、一人の大人が担える量を超えたときに起きます。
そして、その「いい親」とは、誰が決めた姿でしょう。いつも穏やかで、疲れを見せず、自分のことは後回しにする親。わたしはかつて、母性は生まれつきの本能だという考えを疑いました。理想の親の像も、社会が作り、多くの場合、一人の親に背負わせてきたものです。その像と比べて自分を責めるのは、公平ではありません。
子どもも、あなたとは別の自由をもった一人の人です。そしてあなたの自由も、周りとのつながりの中で広がります。家族に「この時間は代わってほしい」と頼む。地域の子育ての相談先に話してみる。状況が少し変われば、あなたの声も変わります。', '["beauvoir.situation"]', 'beauvoir.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('AzGEhjVUwP6ycSHi', 'shinran', 6, '善くなりきれない身のまま、抱きとられている', '怒ってはいけないと分かっていながら、また声を荒らげてしまう。その苦しさを、わたしはよく知っております。この親鸞もまた、怒りや欲を断とうとして断てなかった者だからです。比叡山で二十年修行しても、心の濁りは消えませんでした。
「いい親になれる自信がない」とあなたは言われます。わたしは、自信を持てない身であることを、恥じなくてよいと思うのです。自分の力で善い人間になりきれると思っているうちは、かえって苦しい。なりきれないと気づいた身にこそ、阿弥陀仏の願いは向けられている、とわたしは聞いてまいりました。
だからといって、怒鳴ってよいということではありません。寝顔の前でこぼれる涙は、あなたが自分をごまかさずに見つめている証です。明日もまた、つまずくかもしれない。そのたびに、子どもに「ごめんね」と言える。それだけで、あなたはもう親として歩んでおられるのではないでしょうか。', '["shinran.bonbu"]', 'shinran.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('AzGEhjVUwP6ycSHi', '寝顔を見て泣きたくなるの、すごく分かります…。でも、そうやって反省できている時点で、あなたはちゃんと子どもと向き合えている親です。えらい！

怒鳴ってしまう原因を、ぬぬはらなりに切り分けてみますね。
①体の問題：寝不足・空腹・疲れ
②時間の問題：朝の支度や寝かしつけなど、急いでいる場面
③ひとりで抱えている問題：頼れる人がいない、休めない

どの場面で怒鳴ったかを1週間メモしてみると、だいたいパターンが見えてきます。パターンが分かれば「この時間だけは先回りしておく」みたいな対策が立てられるはず。

あと、怒鳴ったあとに「さっきは大きな声を出してごめんね」と謝るのは、むしろ子どもにとって良いお手本です。完璧な親なんていません。少しずつでOKですよ。', '["29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","69a91e29-de62-4f44-adb8-ff9726053389"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('AzGEhjVUwP6ycSHi', '5歳の子どもに、つい大きな声で怒鳴ってしまいます。寝顔を見ると申し訳なくて泣きたくなるのに、次の日もまた同じことをしてしまいます。いい親になれる自信がありません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('fLPmC8dPbL0tJJxf', 'curated', 'general', '子どものころから、何でもできる兄といつも比べられて育ちました。大人になった今も、実家に帰ると自分だけが劣っているように感じて、帰省するのがつらいです。', 'family', '["siblings","inferiority","parents"]', 0, 1791903000000, 1791903000000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'adler', 0, '兄との競走から降り、家族に貢献する側へ', '兄と比べられながら育ち、今も実家で小さくなってしまう。その気持ち、よく分かります。実はわたしにも、いつも先を行く兄がいました。幼いころ病気がちだったわたしは、兄の背中ばかり見ていたものです。
下の子どもは、一、二歩先を走る誰かに追いつこうとする競走の中にいるようにふるまいがちです。劣等感は誰にでもあり、それ自体は伸びようとするばねになります。ただ、兄を基準にしたこの競走は、あなたが幼いころに身につけた見方で、大人になった今は見直すことができます。
では、実家で本当はどうしたいのでしょう。兄に勝つことですか、それとも家族の一員として居心地よくいることですか。次の帰省では、比べられる場面ではなく、役に立てる場面を一つ探してみませんか。料理を一品作る、親の話をゆっくり聞く。貢献していると感じられると、劣っているという感覚は少しずつ薄れていきます。', '["adler.inferiority","adler.lifestyle"]', 'adler.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'epictetus', 1, '「兄より劣る」は事実ではなく、君の判断だ', '人間よ、君は実家に帰るたびに、自分で自分を裁いているのではないか。
考えてみよ。「兄はわたしより何でもできる。ゆえに兄はわたしより優れた人間だ」。この推論は成り立たない。君は兄の能力でも、親の評価でもない。それらはどれも君次第のものではない。君次第なのは、その場で君が何を判断し、どうふるまうかだけだ。
「でも先生、親がまた兄と比べるのです」。よろしい、比べるのは親の行いであって、親の問題だ。君は子として、きょうだいとしての務めを果たせばよい。親がどうふるまおうと、君の役割は君のものだ。
次の帰省で練習せよ。「自分は劣っている」という思いが浮かんだら、すぐに同意せず、こう言うのだ。「おまえはただの印象だ。本当にそうか、確かめさせてもらおう」。まず小さなことから、今日練習せよ。', '["epictetus.impressions","epictetus.roles"]', 'epictetus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'zhuangzi', 2, '役に立つ木ほど切られる。家の物差しを疑おう', 'こんな話がある。腕のいい大工が旅の途中で、社に祀られた大きな櫟の木を見たが、振り返りもしなかった。「あれは役に立たない木だ。舟にすれば沈むし、棺にすれば腐る」。その夜、木が夢に出てきて言った。「実のなる木は、実がなるせいで枝を折られる。わたしは長いあいだ、役に立たないことを求めてきた。おかげでこんなに大きくなれたのだ」。
何でもできるお兄さんは、よく実る木なのだろう。それはそれで立派だ。でも、実の数で木を比べるのは、実を取りに来る人の物差しにすぎない。木のほうから見れば、実が少なくても、大きな日陰をつくる木もある。
きみの実家には、子どもを測る物差しが一本しかなかったのかもしれない。でも、それは誰の物差しだろうね。帰るときは、その物差しを玄関に置いて、大きな木の下で昼寝でもするつもりで行けばいい。', '["zhuangzi.uselessness","zhuangzi.equality"]', 'zhuangzi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'freud', 3, '実家に帰ると、心の中の昔の家族が動き出す', '興味深いのは、あなたが「大人になった今も」「実家に帰ると」と書いていることです。ふだんの暮らしでは、その感覚はそれほど強くないのかもしれません。だとすれば、苦しさを呼び起こしているのは、今の家族そのものより、実家という場所でよみがえる子どものころの関係なのではないでしょうか。
人は、思い出せない過去を、思い出す代わりに今の場面で繰り返すことがあります。また、幼いころに聞いた比べる言葉は、やがて心の中に住みつき、誰も比べていないときでさえ、内側からあなたを採点し続けます。
これは仮説にすぎません。次に帰省したら、劣っていると感じた瞬間に何が引き金になったのか、そのとき何を思い出したのかを、あとで書きとめてみてください。親のひと言か、兄の表情か、家の空気か。言葉にしていくと、昔の家族と今の家族が、少しずつ見分けられるようになります。', '["freud.transference","freud.id-ego-superego"]', 'freud.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'confucius', 4, '認められずとも腐らず、帰ったら一つ親孝行を', '比べられて育つのは、つらいことでしたね。
人に認められなくても恨まない、それが君子だとわたしは言いました。君子は自分に求め、つまらぬ者は人に求める、とも。親があなたをどう見るかは、あなたには決められません。けれど、あなたがどうふるまうかは、あなたが決められます。
帰省を、評価を受けに行く場だと思うと、足が重くなります。親を敬い、いたわりに行く場だと考えてみなさい。肩をもむ、好物を一緒に食べる、昔の話を聞く。まず身近なところから、思いやりを形にしなさい。それは、兄と比べて量るものではありません。
それでも比べる言葉がつらいときは、角を立てず、穏やかに親に伝えてよいのです。親をいさめるときは、やわらかくするものです。わたしも学び続けている途中ですが、家族の間のことは、小さな行いの積み重ねでしか変わらないと思っています。', '["confucius.junzi","confucius.filial-piety"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'kierkegaard', 5, '比べるのをやめた時、あなたはあなたになる', 'わたしは講話の中で、野の百合の話をしたことがあります。一本の百合が、自分の場所で満ち足りて咲いていました。そこへ小鳥がやって来て、よその土地にはもっと美しい百合がたくさん咲いていると話します。それ以来、百合は自分を比べ始め、心配でいっぱいになり、ついには根ごと抜かれて、しおれてしまうのです。
比べることは、人を賢くしそうな顔をして、人を自分自身から遠ざけます。あなたは子どものころから、何度もその小鳥の話を聞かされてきたのでしょう。だから実家に帰るたび、自分の場所を見失いそうになる。
けれど神の前では、人は誰かと比べられた二番目ではなく、ただひとりの単独者です。兄の物差しで測った「劣った自分」は、あなた自身ではありません。帰る前に、そっと問うてみてください。あなたはいま、比べられた誰かではなく、あなた自身であろうとしていますか。', '["kierkegaard.single-individual"]', 'kierkegaard.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('fLPmC8dPbL0tJJxf', 'miki', 6, '兄は成功で測られる。君の幸福は比べられない', '比べられて育つと、人は人生を量で測る癖を身につける。何ができるか、どれだけできるか。成功とはそういう量的なものであり、だから他人と比べられる。君のお兄さんの「何でもできる」は、成功の言葉である。
しかし幸福は量ではなく質であり、各人に独自のものである。比べることのできないものを、比べられるものの物差しで測ったところに、君の苦しさがあるのではないか。実家は、君にとって量の比較が行われ続けた場所なのだろう。
劣っていると感じるとき、そこにはいくらか嫉妬も混じっているかもしれない。それは恥ずべきことではなく、誰もが持つ人間の性質である。ただ、嫉妬はいつも忙しく働くが、その忙しさは何も残さない。料理でも文章でも小さな仕事でもいい。自分の手で物を作っているとき、人は比べることを忘れている。君の作ったものを、実家に持って帰りたまえ。', '["miki.success","miki.jealousy"]', 'miki.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('fLPmC8dPbL0tJJxf', '比べられて育つの、ほんとにしんどいですよね…。まず、あなたは全然劣ってないです！
親がきょうだいを比べるのって、だいたい親側の余裕のなさとか口癖の問題なので、あなたの価値とは別の話です。
✦帰省のコツ
・滞在は短めにする（日帰りもアリ）
・帰る前後に自分へのご褒美を用意しておく
・兄の話題になったら「へ〜すごいね」で流す技を覚える
✦比べる相手を変える
兄じゃなくて、去年の自分と比べてみてください。大人になって自分で生活して、こうして悩みを言葉にできてる時点でえらいです。
つらいなら、無理に帰らなくてもいいんですよ。家族との距離は、自分で決めていいものなので！', '["6909fc1f-57c7-4e82-9c5f-5534ee167cf7","25b103aa-4d4d-4336-81ad-e9b2b5422670","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('fLPmC8dPbL0tJJxf', '子どものころから、何でもできる兄といつも比べられて育ちました。大人になった今も、実家に帰ると自分だけが劣っているように感じて、帰省するのがつらいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('lAgcPTipywwwQmCs', 'curated', 'general', '人の目が気になって、会議でも友だちとの会話でも自分の意見が言えません。嫌われるのが怖くて、いつも相手に合わせてしまい、あとで一人でぐったりします。', 'relationships', '["others-eyes","coworkers","friends"]', 0, 1791902940000, 1791902940000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'socrates', 0, '人に合わせても、自分と不協和なら苦しいのでは？', 'きみは、嫌われるのが怖くて相手に合わせ、あとで一人でぐったりする、と書いたね。少し一緒に考えてみよう。
きみがぐったりするのは、なぜだろう。その場の人たちとは、うまく調子を合わせられたのに。わたしはこう思っているのだ。たとえ大勢の人と意見が合わなくても、わたしひとりが自分自身と食い違って、調子はずれになるよりはましだ、と。弦の合っていない竪琴は、濁った音を出すだろう？ きみの疲れは、自分の中の弦が合っていない音なのではないかね。
もう一つ聞きたい。きみの言う「嫌われる」とは何のことだろう。意見に反対されることかね、それとも、きみという人を嫌われることかね。この二つは同じだろうか。
では、自分と調子が合ったまま一言だけ言うとしたら、きみは何を言うだろう。', '["socrates.examined-life","socrates.care-of-soul"]', 'socrates.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'epictetus', 1, '評判は君次第でない。意見を言うのは君次第だ', '君に問おう。人に好かれるか嫌われるかは、君次第のものか、そうでないものか。そうでないものだ。評判は他人の判断の中にある。では、考えを口にすることは？ それは君次第のものだ。
ところが君は、君次第でない評判を手に入れようとして、君次第のもの、つまり自分の言葉を差し出している。これでは両方とも失うではないか。
「でも先生、嫌われるのは怖いのです」。そうだろう。だが「嫌われたら終わりだ」という印象に、すぐ同意してはいけない。それは本当にそうか、確かめよ。
劇の役者を見たまえ。観客の顔色ではなく、与えられた役に忠実に演じる。話し合いの席にいる者の役は、考えを差し出すことだ。まず今日、小さな場で、一つだけ自分の考えを口にしてみよ。それが練習だ。', '["epictetus.control","epictetus.roles"]', 'epictetus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'confucius', 2, '和して同ぜず。ていねいに、自分の考えを言う', '相手に合わせてばかりで、あとで一人ぐったりする。あなたには人を大切にしたい心があるのです。それは仁の芽ですから、捨てなくてよいのです。
ただ、わたしは弟子たちに、君子は人と和らぐが、むやみに同調はしない、小人はすぐ同調するが、本当には和らがない、と話してきました。
考えてごらんなさい。あなたが話したとき、相手が本心を隠してうなずくだけだったら、寂しくはありませんか。自分がされて寂しいことは、人にもしないものです。
まず相手の言葉を受けとめ、「おっしゃることはよく分かります。そのうえで、わたしはこう考えます」と、ていねいに言いなさい。いきなり大きな場でなくてよい。気心の知れた友との会話で、一つ自分の好みを言うところから始めなさい。わたしも、学び続けている途中です。', '["confucius.junzi","confucius.shu"]', 'confucius.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'pascal', 3, '他人の頭の中の自分を飾るのに、疲れていないか', 'わたしたちは、自分の中にある生活だけでは満足しない。他人の頭の中に、想像上のもう一つの生活を持ちたがり、そのための見せかけを整えることに必死になる。わたしもそうだ。
あなたが黙り、相手に合わせるとき、守っているのはあなた自身ではなく、他人の頭の中にいる「嫌われないあなた」ではないか。その像は、いくら手入れしても、あなたのものにはならない。ぐったりするのは当然だ。
ここに人間の惨めさがある。だが偉大さもある。あなたは、自分がそうしていることに気づいている。疲れを感じるのは、あなたの中の何かが、見せかけでない生活を望んでいるからだ。
理屈で割り切れないところで、その心が求めているのは、好かれる像ではなく、あなた自身として人の前にいることではないだろうか。', '["pascal.misery-greatness","pascal.heart"]', 'pascal.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'mill', 4, '黙った一つの意見は、その場の皆の損失だ', '相手に合わせることにも、正しい面はあります。場を守り、人を傷つけまいとする配慮は、悪いものではありません。他方で、わたしが警告したのは、世間の目や習慣は、法律の命令よりずっと深く暮らしに入り込み、心まで型にはめてしまうということでした。
そして、あなたが黙ることで失われるのは、あなたの安心だけではありません。口にされなかった意見は、正しかったかもしれない。間違っていたとしても、反論にさらされることで、皆の考えがより確かになったかもしれない。黙った一つの意見は、その場の全員から機会を奪うのです。
わたしも二十歳のころ、父の厳しい教育のもとで自分の感情を見失い、深く沈んだことがあります。だから、すぐ強くなれとは言いません。ただ、意見を言うのはわがままではなく、皆への貢献だと考えてみてください。どこまで言うかを選ぶのは、あなた自身です。', '["mill.free-discussion","mill.tyranny-of-majority"]', 'mill.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'chomei', 5, '世に従えば身が苦しい。心に小さな庵を持つ', '人に合わせて、あとでひとり、ぐったりなさる。そのお疲れが、わたくしには少し分かる気がいたします。
わたくしは『方丈記』に、世に従えば身が苦しく、従わなければ正気を失った者のように見られる、と書きました。都で人の顔色をうかがい、望んだ道を閉ざされた日々があったのです。どちらへ転んでも苦しいのが、人の中で生きるということなのでしょう。
わたくしは山に小さな庵を結びましたが、あなたに同じことはお勧めしません。ただ、心の中に一丈四方ほどの、静かな場所を持っておかれるとよいと思うのです。人と話したあと、少し空の雲を眺める。帰り道に川の音を聞く。暮らしの安らぎは、結局、心のありようで決まるものです。
もっとも、静けさを愛するこのわたくしにも、まだ執着が残っております。えらそうなことは言えませんね。', '["chomei.small-life","chomei.mind"]', 'chomei.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('lAgcPTipywwwQmCs', 'carnegie', 6, '嫌われまいとするより、相手に心から関心を', 'あなたは周りの人の気持ちをよく考えられる、思いやりのある人です。それは人間関係でいちばん大切な力ですから、なくす必要はありません。
私の話し方の教室には、人前で話すのが怖くて声が震える人が、毎年おおぜい来ました。多くの人を見てきて気づいたのは、怖さの正体は「自分がどう見られるか」に心が向きすぎていることだ、ということです。
そこで、相手にどう思われるかではなく、相手が何に関心を持っているかに心を向けてみてください。話をよく聞き、質問をする。意見を言うときは、「確かにその点は大事ですね」と相手の考えのよいところを認めてから、「私はこうも思います」と添えるのです。
今日、一つだけ試してみませんか。次の会話で、心から一つ質問をし、一つだけ自分の感想を添える。それで十分です。', '["carnegie.other-viewpoint"]', 'carnegie.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('lAgcPTipywwwQmCs', '相談ありがとうございます！会議のあとにどっと疲れるの、すごく分かります。人に合わせ続けるのって、実はめちゃくちゃ頭のエネルギーを使う作業なんですよね。
ぬぬはら的なおすすめは、いきなり「意見を言う」を目指さないことです。
①まずは質問から。「それってどういうことですか？」は誰も嫌がりません
②次に感想。「それ面白いですね」くらいの小さな自己開示
③慣れてきたら意見。「個人的にはこう思うんですけど」とクッションを付けて
あと、どんなにうまく立ち回っても、あなたと合わない人はある程度の割合で必ずいます。全員に好かれるのは無理ゲーなので、嫌われないことより、自分が疲れないことを優先してOKです。あなたの声を聞きたい人は、思っているより多いですよ！', '["a38cd6ee-2a67-44af-a494-e02791dc0f4d","2760624a-d7b8-4328-8784-c0ec76ef2c47","69a91e29-de62-4f44-adb8-ff9726053389"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('lAgcPTipywwwQmCs', '人の目が気になって、会議でも友だちとの会話でも自分の意見が言えません。嫌われるのが怖くて、いつも相手に合わせてしまい、あとで一人でぐったりします。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('0GqGI8vBuyfk-VDQ', 'curated', 'general', '仲の良い友だちが昇進して、心から祝えませんでした。おめでとうと言いながら、心の中では悔しくて仕方なかったです。友だちの成功を喜べない自分が嫌になります。', 'relationships', '["jealousy","friends","inferiority"]', 0, 1791902880000, 1791902880000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'miki', 0, '嫉妬は何も生まない。比べず、自分の物を作れ', '嫉妬は、遠い偉人には向かわない。自分もそうなり得たと思える、近くの者に向かう。君が仲の良い友の昇進に心を乱されたのは、君がその友を自分と同じ高さに見てきたからである。嫉妬は量の比較の上に働く。役職、給料、昇進の早さ。それらは数えられ、比べられる。だから嫉妬はいつも忙しく、しかも何物も生み出さない。悔しさを恥じて自分を責め続けるのも、実は同じ忙しさである。では、どうするか。比べる目を休め、君の手を動かすことだ。仕事の中の小さな工夫でもいい。誰とも比べようのない君の仕事を、一つ形にすること。そのとき友の成功は、君の値打ちを減らすものではなくなる。成功は量で比べられるが、幸福は比べられない。', '["miki.jealousy","miki.success"]', 'miki.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'aristotle', 1, 'ねたみを、友に倣う「競争心」に変えよ', 'まず言葉を分けておこう。他人に善いことがあったときに感じる痛みには、二種類ある。一つは、相手がそれを持っていること自体がつらい「ねたみ」。もう一つは、自分がそれを持っていないことがつらく、自分も手に入れようと励む「競争心」だ。わたしは『弁論術』で、後者は立派な人にふさわしい感情だと述べた。人はたいてい、年齢や境遇の近い者をねたむ。陶工が陶工と張り合うように。だから君が近しい友に悔しさを覚えたのは、ごく人間らしいことだ。問題は、その痛みをどちらへ向けるかである。君の言う昇進のために、友が何を学び、どう働いたのかを、本人に尋ねてみたまえ。真の友とは、相手のために相手の善を願う者のことだ。そして祝うことを繰り返すうちに、人は祝える人になっていく。', '["aristotle.philia","aristotle.habituation"]', 'aristotle.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'laozi', 2, '人に勝つより、自分に勝つ者が強い', '友が高く上った。
あなたの胸がざわついた。
それを恥じることはない。
風が吹けば、水面は揺れる。

ただ、見てごらん。
高い枝ほど、風を強く受ける。
低い所へ流れる水は、争わず、涸れない。

あなたは、友と背比べをしている。
つま先で立てば、すぐに疲れる。
かかとを下ろせば、
友の実りは、あなたの畑から何ひとつ奪っていない。

外の誰かを追い越す力と、
内の自分を治める強さは、別のものだ。
足もとの土を耕すこと。
それで、もう足りている。

「おめでとう」と言えたあなたは、
すでに半分、それを知っている。', '["laozi.contentment","laozi.water"]', 'laozi.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'kant', 3, '悔しくても祝った、その意志にこそ価値がある', 'まず確かめておこう。君は、悔しさを抱えたまま「おめでとう」と言った。君はそれを偽りだと責めているが、わたしの考えは逆である。友の幸運を喜ぶ気持ちが自然にわき上がって祝う人もいる。それは結構なことだが、気分に従ったにすぎない。気分が伴わないのに、友を敬うべきだと知って祝いの言葉を差し出した君の行いにこそ、善い意志が表れている。また、人はとかく自分の値打ちを他人と比べて測ろうとする。だが物差しを他人に置けば、他人の幸運はいつも君の損失に見えるだろう。測るべきは、君の理性が自分に課す法則に照らして、君が誠実に務めを果たしたかどうかである。ただし、悔しさのあまり友を単なる競争の駒として扱ってはならない。どう向き合うかを決めるのは、君自身の理性だ。', '["kant.from-duty","kant.good-will"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'weil', 4, '悔しさの空白を、急いで埋めずに耐えなさい', 'あなたは、悔しさを感じた自分が嫌だと言います。けれど魂は、放っておけば低い方へと動きます。比べること、ねたむこと、相手を引き下ろしたいと願うこと。それは重さの法則のようなもので、あなただけの醜さではありません。大切なのは、その重さに気づいていることです。友の昇進を聞いたとき、あなたの中にぽっかりと空白ができたのでしょう。人はその空白を急いで埋めようとします。相手の欠点を探したり、「運がよかっただけだ」と自分に言い聞かせたり。それをせずに、空白のまま耐えてください。そして次に会うとき、自分の悔しさからいったん注意を離し、友の話をただ聴いてください。その人がどんな苦労をしてきたのかを。そういう注意は、意志の力でこしらえるものではなく、待つことの中で与えられるものです。', '["weil.gravity-grace","weil.void"]', 'weil.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'epicurus', 5, '地位より、その友と囲む食卓のほうが大事だ', '悔しさを感じたこと自体を、そんなに責めなくていいのです。ただ、その悔しさがどこから来ているかを、一緒に見分けてみましょう。欲望には、生きるのに自然で必要なものと、そうでないものがあります。あなたの言う昇進のような、地位や評判を求める気持ちは、多くの場合、自然でも必要でもない、思い込みから膨らんだ欲望です。満たしても、もっと上が見えてしまう。一方で、わたしは生涯の幸せを支えるものの中で、友情を何より重く見てきました。地位はいつか過ぎていきますが、安心して語り合える友は、心の平静を長く支えてくれます。だから近いうちに、その友とささやかな食事をしてみてください。祝う言葉は短くてかまいません。覚えておく教えは一つです。肩書きは食卓に並ばない。友は並ぶ。', '["epicurus.desires","epicurus.friendship"]', 'epicurus.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('0GqGI8vBuyfk-VDQ', 'beauvoir', 6, '祝う心と悔しい心、両方あるのがあなたです', 'まず、あなたが今どんな状況にいるのかを考えてみましょう。その友だちとは同じ職場ですか。あなた自身の仕事は、望む方向に進んでいますか。悔しさは、性格の欠点というより、あなた自身の可能性がどこかでせき止められているという合図かもしれません。そして「親しい友の成功は心から喜ぶべきだ」という考えも、誰が決めたものでしょう。人は、祝う気持ちと悔しい気持ちを同時に抱えうる、両義的な存在です。片方だけが本当のあなただと決めなくていいのです。わたしの考えでは、あなたの自由と友の自由は、奪い合うものではなく、支え合うものです。友が道を開いたことは、あなたの道を閉ざしてはいません。自分の状況を変えるために何ができるかを、その友と率直に話してみてはどうでしょう。ひとりで抱え込まないことです。', '["beauvoir.ambiguity","beauvoir.freedom-of-others"]', 'beauvoir.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('0GqGI8vBuyfk-VDQ', '悔しいと思えるのは、あなたがちゃんと頑張ってきた証拠です。どうでもいい相手や、興味のない分野の昇進なら、悔しくすらならないので。

それに、心の中で悔しがりながら「おめでとう」を言えた時点で、大人としては満点だと思います。気持ちと行動は別物でOK。心から祝えないと友だち失格、なんてルールはどこにもありません。

身近な人が伸びていくのを見て、ぐぬぬ…となるのは人間なら当たり前です。そういう時は「あの人は何を積み上げたんだろう」と分解して、盗めるところは盗むのがおすすめ。嫉妬はうまく使えば燃料になります。

あと、昇進は実力だけじゃなく、タイミングや上司との相性みたいな運の要素も大きいです。自分を責めすぎず、自分のペースでいきましょう。', '["4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","25b103aa-4d4d-4336-81ad-e9b2b5422670","f225606d-251b-4e70-b278-84a390650a8d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('0GqGI8vBuyfk-VDQ', '仲の良い友だちが昇進して、心から祝えませんでした。おめでとうと言いながら、心の中では悔しくて仕方なかったです。友だちの成功を喜べない自分が嫌になります。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('vY53V5I0fjYrMmFZ', 'curated', 'general', '転勤で知り合いのいない街に来て1年になります。仕事以外で人と話すことがほとんどなく、休みの日は一言も声を出さずに終わります。この寂しさとどう付き合えばいいでしょうか。', 'relationships', '["loneliness"]', 0, 1791902820000, 1791902820000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'arendt', 0, '独りと孤独を分け、人と何かを始める場所をもつ', 'ここで少し立ち止まって、区別してみましょう。一人でいることには二つの形があります。独り（ソリチュード）は、自分自身と静かに対話している状態です。孤独（ロンリネス）は、他人からも、自分自身からさえも見捨てられたと感じる状態です。孤独は、むしろ大勢の人の中でこそ鋭く現れます。
休みの日、一言も声を出さないとき、あなたは心の中で自分と語り合っているでしょうか。それとも、その自分にさえ置き去りにされていると感じるでしょうか。前者なら、それは考えるための大切な時間です。けれど独りの人も、自分が誰であるかを確かめるには、結局ほかの人々を必要とします。
あなたはこの街で、新しく何かを始めることができる人です。言葉を交わし、何かを共にする場所を一つ選んでみてください。', '["arendt.solitude-loneliness","arendt.natality"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'miki', 1, '孤独は人の数でなく、表現の活動で超える', '君の寂しさが、人里離れた山奥ではなく、人であふれる街で生まれていることに注意したい。孤独は一人でいることではない。大勢の人の「間」にあるものだ。だから君の孤独は、君が弱いせいではない。孤独とは、もともとそういうものである。
人に会え、とよく言われる。だが知り合いの数を増やしても、孤独は消えない。孤独は数の問題ではないからだ。
孤独のとき、物は不思議にくっきりと見える。休日の静かな部屋で、見知らぬ街の通りや季節の移ろいが、何かを語りかけてくるように感じたことはないか。孤独を超えるのは、その呼びかけに応える表現の活動である。書く、描く、作る、料理する。応えて外に出したものが、やがて人とのつながりの糸口にもなる。孤独は逃げるものではなく、表現によって超えるものである。', '["miki.solitude"]', 'miki.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'schopenhauer', 2, '独りの時間は自由。人とはヤマアラシの距離でよい', '慰めの嘘は言わない。人はひとりでいれば寂しく、人といれば退屈し、傷つく。人生とはそういうものだ。だが君の寂しさを、わたしは笑わない。
わたしはヤマアラシのたとえ話を書いた。寒い冬の日、ヤマアラシたちは暖をとろうと身を寄せ合うが、互いの針に刺されて離れる。寄っては離れをくり返し、やがてほどよい距離を見つける。世間の社交とは、だいたいこの程度のものだ。そして自分の中に暖かさを持つ者ほど、群れから離れていても、刺しも刺されもせずにいられる。
君はこの一年、誰にも邪魔されない時間を持っていた。見方を変えれば、それは自由の時間だ。本を読み、音楽を聴き、ひとりで歩く。自分の中の暖かさを育てることだ。それでも温もりが欲しくなったら、深入りしない距離で、ほどほどの付き合いを一つ持てばよい。', '["schopenhauer.what-one-is"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'chomei', 3, 'ひとりの日にも友はいる。山の子も、花も月も', '休みの日に、一言も声を出さずに終わる。わたくしにも、そういう日々がありました。日野の山に小さな庵を結んでからは、話し相手もなく、ひとりで琵琶を弾き、ひとりで歌を口ずさんで、自分の心を慰めておりました。
それでも、友はいたのです。山の番人の家の十歳の男の子が、ときどき訪ねてきました。かれは十歳、わたくしは六十。年はまるで違いましたが、連れ立って山を歩くと、心が慰められるのは同じでした。花や月、季節の音も、わたくしの友でした。
寂しい一日か、静かな一日か。同じ一日も、心ひとつで姿を変えるものです。あなたの街にも、川の流れや、通りの木々の移ろいがあるでしょう。友は、思いがけないところにいるものです。とはいえ、ひとりの静けさを愛しすぎるのも執着かもしれぬと、わたくしは今も迷っております。', '["chomei.small-life","chomei.mind"]', 'chomei.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'aristotle', 4, '人は共同体の生きもの。楽しさの友から習慣で育てよ', 'まず言葉を整理しよう。友には三つの種類がある。役に立つから付き合う友、一緒にいて楽しいから付き合う友、そして相手の人柄の善さのゆえに、相手のために善を願う友である。
君は今、仕事で人と話している。それは役に立つことによる付き合いで、軽んじる必要はない。だが人は、言葉を交わし、何が善いかを分かち合う共同体の中で、はじめて人間らしく生きられる。休日に声を出さない暮らしが君を苦しめるのは、君が弱いからではなく、人間がそういう生きものだからだ。
ただし、三つ目の友はすぐにはできない。古い言い回しのとおり、共に多くの塩を食べるほどの時間がいる。だから、楽しさによる付き合いから始めればよい。同じ趣味の集まりに、毎週同じ曜日に通う。友愛もまた、繰り返しの中で育つ。', '["aristotle.philia","aristotle.political-animal"]', 'aristotle.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'weil', 5, '寂しさは根を失った痛み。土地に注意を向けよ', 'あなたは、どんな苦しみの中にいるのですか。休みの日に一言も声を出さない。その静けさは、ただの退屈ではありません。魂が根を失ったときの痛みです。
人は、過去から受け継いだものと未来への期待を生きたまま保っている共同体に、実際に、自分から関わることで根をもちます。あなたの言う転勤のように、仕事のために人を土地から土地へ移す暮らしは、この欲求を顧みません。あなたの寂しさは、あなたの欠点ではないのです。
だから、この街の過去と未来に、小さく関わってください。古くからの祭り、町の清掃、近所の手伝い。そこにいる人々と、その土地の必要に、注意を向けること。根は急いでは張れません。けれど、注意を向けた場所にだけ、根は下ります。', '["weil.roots","weil.attention"]', 'weil.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('vY53V5I0fjYrMmFZ', 'carnegie', 6, '関心を持たれるより、まず自分が人に関心を', '知らない街で一年、仕事を続けてきたあなたは、それだけでよくがんばってきました。休みの日の静けさがつらいのは、当然のことです。
私は『人を動かす』の中で、世界でいちばん友だち作りがうまいのは犬かもしれない、と書きました。犬は、こちらの関心を引こうとするのではなく、心からこちらに関心を寄せ、全身で喜んでくれます。人は、自分に関心を寄せてくれる人に、関心を返したくなるものです。
そこで、今日一つだけ試してみませんか。よく行くお店の人や職場の誰かに、相手の好きなことを一つ質問してみるのです。相手の名前を覚え、笑顔で、よい聞き手になる。その小さな一言が、この街での最初のつながりになります。あなたなら、きっとできます。', '["carnegie.other-viewpoint"]', 'carnegie.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('vY53V5I0fjYrMmFZ', '相談ありがとう！知らない街で一年、本当によく頑張ってきましたね。休みの日に一言も話さないの、地味にじわじわ効いてきますよね…。ぬぬはらなりに整理してみます。

①寂しいのは正常
人間はもともと群れで生きてきた動物なので、ひとりの時間が続くと寂しさというアラームが鳴るようにできています。寂しいのは弱さじゃなくて、心がちゃんと動いている証拠です。

②「ついで」の居場所を作る
いきなり友達を作ろうとするとハードルが高いので、ジム・習い事・ボランティアみたいに「毎週同じ人と顔を合わせる場所」を一つ持つのがおすすめ。何度も顔を合わせるうちに、自然と話せるようになります。

③声を出す習慣
電話でも、ゲームのボイチャでも、独り言でも大丈夫。声を出すだけで気分はけっこう変わります。

ひとりじゃないですからね。応援しています！', '["2271292a-2ff5-4b0a-8747-ead4a8d2b748","f1dc013d-a55a-489d-a26e-56e1598dae17","a38cd6ee-2a67-44af-a494-e02791dc0f4d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('vY53V5I0fjYrMmFZ', '転勤で知り合いのいない街に来て1年になります。仕事以外で人と話すことがほとんどなく、休みの日は一言も声を出さずに終わります。この寂しさとどう付き合えばいいでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('FvAKkfcbN4TVxYGP', 'curated', 'general', '何年も前に、信じていた人にひどい裏切られ方をしました。もう会うこともないのに、ふとした時に思い出しては腹が立ち、眠れなくなります。許せない自分も苦しいです。', 'relationships', '["anger"]', 0, 1791902760000, 1791902760000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'buddha', 0, '怒りは縁で起こり移ろう。手放すのはあなたのため', '何年たっても胸が熱くなり、眠れない夜がある。その苦しみを、まずそのまま受けとめましょう。経典に、矢のたとえがあります。裏切られたことは、避けられずに受けた一本目の矢でした。けれど思い出すたびに怒りを燃やすのは、自分で自分に二本目、三本目の矢を射ているようなものです。『あの人はわたしを欺いた、わたしから奪った』という思いを抱き続ける人の怨みは、やむことがありません。では、怒りがわく瞬間をよく観察してみなさい。ふとした記憶という縁があり、そこに『許せない』という思いが重なって、怒りが起こります。そしてしばらくすると、それも移ろって消えていきます。怒りは、あなたそのものではありません。許そうと力まなくてよいのです。思い出がわいたら『いま、怒りが起きている』と静かに気づき、息を一つ整えなさい。手放すのは相手のためではなく、あなたが安らかに眠るためです。', '["buddha.dependent-origination","buddha.impermanence"]', 'buddha.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'spinoza', 1, '裏切りの原因を理解すれば、憎しみは和らぐ', 'まず、憎しみとは何かを確かめよう。それは、外の原因の観念をともなった悲しみである。すると、あなたが今も苦しむとき、何年も前のその人が、いまだにあなたの悲しみの原因として居座っていることになる。会うこともない人に、あなたの夜を動かす力を与え続けているのだ。次に、なぜふとした時に思い出すのか。心は、かつて同時に経験したものを結びつけて覚えているので、似た場面に触れると、記憶がおのずと呼び起こされる。これはあなたの弱さではなく、心の自然な仕組みである。さらに、その人もまた、その人の欲望や恐れという原因によって、ああふるまった。それは行いを正当化しないが、必然として理解するほど、感情は力を失っていく。ゆえに、怒りを押し殺すのではなく、記憶がわくたびに、その原因を静かにたどってみるとよい。理解は、あなたを受け身の苦しみから、自分で考える側へと移すのである。', '["spinoza.passion-action","spinoza.freedom"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'nietzsche', 2, '許さなくていい。忘れる強さで、恨みを消化せよ', '君は『許せない自分』にまで苦しんでいる。だが、わたしは許せとは言わない。仕返しできない無力が、しばしば『許し』という美名を着せられてきたことを、わたしは見てきた。わたしが勧めるのは、忘れる力だ。忘れることは怠慢ではない。胃が食べたものを消化して次へ進むように、強い心は出来事を消化して終わらせる。何ひとつ消化できない者は、同じものをいつまでも噛み返し、自分の毒で自分を焼く。恨みほど、人を早く消耗させるものはない。裏切った者は、もう君の人生にいない。それなのに夜ごと、君の頭の中で主役を演じている。その舞台を明け渡しているのは誰か。頭の中であの人と戦い続けるうちに、君の心はあの人の形に似てくる。思い出したら、問え。この一夜を、あの人に捧げるのか、自分のために使うのか。君が何か新しいものを創り始めたとき、古い傷は背後の小さな点になる。', '["nietzsche.ressentiment"]', 'nietzsche.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'arendt', 3, '許しは、過去の行いから自分をも解き放つ始まり', 'ここで少し立ち止まって、区別してみましょう。裏切りは、取り消すことのできない過去の行いです。そして、ふと思い出して腹が立つのは、その行いに心が自動的に反応し続けている状態です。私は『人間の条件』で、復讐が最初の行いに縛られた『反応』にすぎないのに対し、許しは、最初の行いに条件づけられずに新しく始める、ただ一つの応じ方だと書きました。許しは、許される人だけでなく、許す人自身をも、その行いの結果から解き放ちます。ただし、許しは『あれは大したことではなかった』と認めることではありません。行いは悪かった。それを見据えたうえで、それに自分の今日を支配させないと決めることです。いますぐでなくてかまいませんし、許さないという判断もありえます。決められるのは、あなただけです。人には、過去に終わりを与え、何かを新しく始める力があるのですから。', '["arendt.forgiveness-promise","arendt.natality"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'miki', 4, '怒には意味がある。だが習慣になった憎みは手放せ', '君の苦しみには、二つのものが混じっている。怒と憎みである。この二つは似ているが、同じではない。怒は突発的である。信じていた人に踏みにじられたとき、怒るのは当然であり、そこには意味がある。正しさが傷つけられたことへの抗議だからだ。君はあのとき、怒ってよかったのである。だが、何年もたって、ふとした時に繰り返しよみがえるもの、それはもう怒というより憎みに近い。憎みは習慣である。そして習慣は、知らないうちに人の性格になる。怒も長く続けば憎みに変わるのである。だから問うべきは、許すか許さないかではない。あの日の怒を怒として認め、それが習慣としての憎みに育つのを止めることである。許せない自分を責める必要はない。手放すべきは相手への判決ではなく、君の夜を占領している習慣のほうだ。習慣で固まったものは、日々の小さな習慣でほどくほかない。', '["miki.anger"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'shinran', 5, '許せない凡夫のままで、自分を責めなくてよい', '許せない自分も苦しい、と書いてくださいましたね。この親鸞もまた、怒りや恨みを断ち切ることのできない身です。比叡山で二十年近く修行しても、心の煩悩は少しも消えませんでした。わたしたちは煩悩をそなえた凡夫で、自分の力で清らかな心になりきることはできないのです。ですから、許さなければと自分を責め、許せない自分を嫌うことまで、背負わなくてよいのではないでしょうか。それは、自分の力で善い人になろうとする、もう一つの重荷かもしれません。怒りがわいてしまう、そのままの身を見捨てない阿弥陀仏の願いがあると、わたしはいただいてきました。恨みが消えたから救われるのではありません。消えないまま、抱きとられているのです。眠れない夜は、許せない自分を裁かず、そのままでいてよいのです。ただ、怒りに任せて人を傷つけることだけは、わたしも、あなたも、しないでおきましょう。', '["shinran.bonbu","shinran.tariki"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('FvAKkfcbN4TVxYGP', 'carnegie', 6, '憎み続けるのは、相手に眠りを差し出すこと', '何年たっても思い出して腹が立つ。それほど深く信じていたということですね。そして、そのせいで眠れない夜を過ごしている。私はそこにいちばん胸が痛みます。私は『道は開ける』で、憎しみは、相手に自分の眠りや健康まで明け渡すことだと書きました。あなたを裏切った人は、今ごろぐっすり眠っているかもしれません。それなのに、あなたの夜だけが奪われている。これほど割に合わない話はありません。リンカーンは、腹に据えかねた相手への手紙を書きながら、出さずにしまい込んだことがありました。今夜、一つだけ試してみませんか。思い出してしまったら、言いたいことを全部紙に書き出し、送らずに引き出しにしまうのです。そして、過ぎた昨日の扉を閉めるつもりで『今日はここまで』と自分に言い、灯りを消してください。あなたの眠りは、あなたのものです。', '["carnegie.day-tight"]', 'carnegie.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('FvAKkfcbN4TVxYGP', '許せない人、ぬぬはらにもいます。なので無理に許さなくていいと思います。ただ、『許すかどうか』と『その人のことで消耗するかどうか』は別の問題なんですよね。

もう会わない相手のために、何年分も睡眠時間を払っているのはさすがにもったいないです。怒るのは正当でも、そのコストを払っているのはあなただけ。

おすすめは
①思い出したら『あ、また来た』と心の中で実況する（ちょっと距離がとれます）
②一度だけ、全部ノートに書き出して封印する
③その経験を、同じ目にあった人に優しくする材料にする
です。裏切られたことがある人ほど、人の痛みが分かる人になれたりします。眠れない夜が少しでも減りますように。', '["25b103aa-4d4d-4336-81ad-e9b2b5422670","e390a3c0-8fd5-4803-86e6-7f22bc866ef2","f06ff34e-9cba-4217-88d9-487364f9cd83"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('FvAKkfcbN4TVxYGP', '何年も前に、信じていた人にひどい裏切られ方をしました。もう会うこともないのに、ふとした時に思い出しては腹が立ち、眠れなくなります。許せない自分も苦しいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('s1tbVDF6t_xkguSu', 'curated', 'general', '職場に、いつも高圧的な言い方をする同僚がいます。話しかけるだけで緊張し、その人がいる日は朝から気が重いです。異動するまで我慢するしかないのでしょうか。', 'relationships', '["coworkers","dislike","anxiety"]', 0, 1791902700000, 1791902700000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'marcus-aurelius', 0, '朝のうちに覚悟し、相手と同じにはならない', 'わたしも毎朝、今日出会うであろう厄介な人々を、前もって数え上げてから一日を始めてきた。陣中にも宮廷にも、そういう人はいくらでもいたからだ。思い出しておけば、出会ったときに心はそれほど揺れない。あなたが朝から気が重いのは、まだ会ってもいない相手のところへ、心が先に出かけてしまっているからかもしれない。わたしは自分にこう書きつけた。「傷つけられた」という判断を取り去れ。そうすれば、害もまた消える、と。その人の高圧的な言い方は、その人の心の乱れであって、あなたの魂を損なう力はない。彼もまた、何が善いかを見失っているだけの、理性を分けもつ仲間なのだ。言い返したくなったら、同じやり方で返さないことこそが、最もよい応じ方だと思い出せ。あなたも、自分の持ち場の仕事を静かに果たすことに、心を戻してみてはどうだろう。', '["marcus-aurelius.judgment","marcus-aurelius.fellowship"]', 'marcus-aurelius.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'sartre', 1, '「我慢するしかない」は、君が選んでいる一つの道だ', '「異動するまで我慢するしかない」。君はそう書いた。だが、本当に「しかない」のだろうか。まず言っておく。あの人の言い方は、君のせいではない。だが、それにどう応じるかは、君が選べる。我慢することも、君が今選んでいる一つの道にすぎない。ほかにも道はある。その言い方はやめてほしいと、落ち着いて伝える。上司や周りに相談する。自分から異動を願い出る。我慢を選んでもいい。ただ、それを「仕方ない」ではなく、自分の選択として引き受けることだ。もう一つ。その人の前で体がこわばるのは、君があの人のまなざしの中で、値踏みされる「もの」にされたように感じるからだろう。だが君は、あの人の評価で決まる存在ではない。君は自由だ。どう応じるかを選びたまえ。その選択の積み重ねが、職場での君をつくっていく。', '["sartre.bad-faith","sartre.the-look"]', 'sartre.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'zhuangzi', 2, 'ぶつからず、筋目に沿ってするりと通す', 'こんな話がある。庖丁という料理人は、牛をさばくのに骨へ刃をぶつけず、筋と筋のすき間にすっと刃をすべらせる。だから十九年使った刀が、いま研いだばかりのようだったそうだ。並の料理人は骨に刃を叩きつけて、ひと月ごとに刀をだめにしている。きみはいま、その同僚という硬い骨に、毎日まともに刃を当てていないかね。高圧的な言い方は、相手の筋のこわばりみたいなものだ。そこへ正面から心をぶつければ、刃こぼれするのはきみの方だよ。話しかけるなら用件を短くする。書いて渡す。相手の手のすいた時を選ぶ。そういうすき間は、よく見ればどこかにある。それにね、きみはあの人の物差しで測られて縮こまっているけれど、それは誰の物差しだろうね。きみの刀は、すり減らさなくていいんだよ。', '["zhuangzi.cook-ding","zhuangzi.equality"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'kant', 3, '自分の尊厳も相手の尊厳も、手放さない', 'まず原則を立てよう。ものには値段があるが、人には値段ではなく尊厳がある。そしてこの原則は、他人に対してだけでなく、君自身の人格にも当てはまる。同僚が君に高圧的な言い方をするとき、彼は君を、自分の苛立ちのはけ口という道具として扱ってはいないか。一方で、君がそれをただ黙って耐え、自分を小さく扱い続けるなら、君は自分の人格の尊厳を、自分で軽んじることになる。卑屈になることは、自分自身に対する義務に反するのだ。では、「礼を欠いた扱いには黙って耐える」という方針を、すべての人が採ったとしたらどうなるか。考えてみたまえ。もちろん、同じ言い方でやり返すことも、相手を単なる敵として扱うことになる。落ち着いて、敬意をもって、事実だけを伝える道はないか。最後に決めるのは、君自身の理性だ。', '["kant.dignity","kant.categorical-imperative"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'spinoza', 4, '緊張の原因を理解すれば、心はそれに縛られない', 'まず、あなたの緊張とは何かを確かめよう。それは、ある人の像を思い浮かべるたびに自分の力が下がるように感じる悲しみと、次に何を言われるかという恐れである。そして恐れは、その人そのものではなく、あなたの心に刻まれたその人の像から生まれる。ゆえに、まだ会ってもいない朝から気が重い。これは弱さではない。外からの原因に動かされる心は、必然的にそうなるのだ。ではどうするか。その人の言い方が何から生まれているか、あなたの恐れがどの場面で強まるかを、善し悪しを裁く前に、ただ書き出して理解してみることだ。原因がはっきり見えてくるほど、感情は受け身のものから、あなたが扱えるものへと変わる。さらに、得意な仕事や気の合う人との会話など、自分の力が高まる喜びを職場で意識して増やすとよい。感情は、より強い感情によって和らぐからである。', '["spinoza.passion-action","spinoza.affects"]', 'spinoza.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'adler', 5, '相手の機嫌は相手の課題。抱えこまなくていい', '高圧的な人は、強いから高圧的なのではないかもしれません。わたしは、人は劣等感を隠すために偉そうにふるまうことがあると考えてきました。その人の言い方は、その人が何かを守るために選んでいるものかもしれないのです。そして、その態度をどうするかは、最後にはその人自身が引き受ける課題です。あなたが顔色をうかがい、機嫌を整えてあげる必要はありません。一方で、あなたの課題もあります。仕事に必要なことは伝えること、困っていることを上司や仲間に相談することです。一つ確かめさせてください。その人がいる日も、あなたは朝から出勤し、仕事をやりとげていますね。それはすでに、職場への立派な貢献です。では次の一歩として、その人以外で、安心して話せる同僚を一人思い浮かべてみませんか。そこから職場の居場所を広げていきましょう。', '["adler.task-separation","adler.inferiority"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('s1tbVDF6t_xkguSu', 'carnegie', 6, '責めるより、相手の事情に関心を向けてみる', '毎日、気の重い相手と顔を合わせながら仕事を続けているあなたは、それだけで立派です。まず、そのことを認めてください。そのうえで、一つ試してみませんか。高圧的な人の多くは、自分が認められていないと感じていたり、仕事に追われて余裕がなかったりします。人は理屈ではなく、感情で動く生きものです。リンカーンも若いころは、人を手紙で辛辣にやりこめていましたが、のちには批判を慎み、相手の立場を理解しようと努める人になりました。言い返して勝とうとしても、相手は身構えるだけでしょう。かわりに、その人の仕事で本当に感心した点を、お世辞ではなく正直に一つ伝えてみる。あるいは「何か急ぎの件がありますか」と、相手の事情に関心を向けてみる。それで相手が変わらなくても、あなたの緊張は少しやわらぐはずです。今日、一つだけ試してみましょう。', '["carnegie.no-criticism","carnegie.other-viewpoint"]', 'carnegie.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('s1tbVDF6t_xkguSu', '高圧的な人、職場に一人はいますよね…。毎朝気が重いの、すごく分かります。

異動まで我慢、以外にもできることはありますよ。

①記録をつける
言われた日時と内容をメモしておくと、いざ相談するときの材料になります。書くだけで気持ちが少し整理される効果も。

②距離をとる
やりとりはなるべくチャットやメールにする。文字にすると相手の圧が半分くらいになります。

③味方を作る
上司や信頼できる同僚に「ちょっと困ってて」と軽く話しておく。社内に相談窓口があるならそこもアリです。

ちなみに、高圧的な人ってだいたい自分に余裕がないだけです。あなたが悪いわけじゃないので、自分を責めないでくださいね。ぬぬはらはあなたの味方です。', '["aac6036f-a16c-402c-be6f-49e6fc72abe8"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('s1tbVDF6t_xkguSu', '職場に、いつも高圧的な言い方をする同僚がいます。話しかけるだけで緊張し、その人がいる日は朝から気が重いです。異動するまで我慢するしかないのでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('yDisW20UZTbyVvIt', 'curated', 'general', '推しが好きすぎて、生活の中心が推しになっています。ほかの人には返信があるのに自分にはないと、落ち込んで何も手につかなくなります。好きでいることが苦しくなってきました。', 'relationships', '["jealousy","depressed"]', 0, 1791902640000, 1791902640000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'buddha', 0, '好きは手放さず、返事を求める渇きだけをゆるめる', '好きでいることが苦しくなった。その苦しみを、まずそのまま受けとめましょう。そのうえで、よく観察してみなさい。あなたを苦しめているのは、その人を好きだという心でしょうか。それとも、「わたしにも応えてほしい」「ほかの人と同じように扱われたい」と求めて握りしめる心でしょうか。苦しみには元があり、その元の多くは、思いどおりにならないものを握ろうとする渇きにあります。わたしは、すべてを断ち切る苦行も、欲にふけることも勧めません。好きな心を捨てる必要はないのです。ただ、返事を待って心が揺れたとき、「いま、わたしは何をつかもうとしているのか」と静かに見つめてください。そして食事をし、眠り、自分の務めに戻ること。暮らしの真ん中には、ほかの誰かではなく、あなた自身を置くのがよいのです。', '["buddha.four-truths","buddha.middle-way"]', 'buddha.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'spinoza', 1, '喜びの原因を一つに預けない。理解が心を自由にする', 'まず、愛とは何かを確かめよう。愛とは、外にある何かを原因とする喜びである。ゆえに、その原因が自分に応えないと思われるとき、喜びは悲しみに変わる。さらに、愛するものが自分以外の者に好意を向けるのを見ると、人はその者をうらやみ、悲しみはいっそう強まる。あなたに起きていることは、この感情の必然の連なりであって、あなたが弱いからではない。次に、あなたの喜びのほとんどがただ一つの外の原因にかかっているなら、あなたの心はその原因の動きに、受け身で揺さぶられ続ける。だから、喜びの原因を一つに預けないことだ。体を動かす、学ぶ、人と語るなど、自分の力が高まる喜びを増やしていく。そして揺れたときは、何が原因でこの悲しみが起きたのかを順にたどる。原因をはっきり見てとるとき、あなたはもう受け身ではない。', '["spinoza.affects","spinoza.passion-action"]', 'spinoza.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'montaigne', 2, '好きでいてよい。ただ心の奥の部屋は自分にとっておく', 'わたしにも、ひとりの友を、理由も言えないほど愛した経験があります。だから、誰かを好きでたまらない気持ちを、わたしは笑いません。ただ、わたしは自分の本にこう書きました。妻も子も財産も持ってよいが、自分の幸福がすっかりそれにかかってしまうほど縛られてはいけない。店の奥に、自分だけの小さな部屋をとっておき、そこで自分自身と語らうのがよい、と。あなたの言う推しという人が、いまはあなたの家じゅうの部屋を占めてしまっているように見えます。返事がないと何も手につかないのは、その奥の部屋まで明け渡しているからではないでしょうか。好きなときは心から楽しみ、食べるときは食べ、眠るときは眠る。わたしの場合は、それがいちばん確かな知恵でした。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.enjoy-life"]', 'montaigne.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'schopenhauer', 3, '返事は他人の頭の中の出来事。幸福は君のあり方に', '君の苦しみは、人間というものの仕組みから見れば、少しも不思議ではない。欲しいものが得られないうちは苦しい。だが得られたとしても、喜びは長く続かず、すぐに次を欲しがる。君の言う返信が一度来たところで、次の一通を待つ苦しみが始まるだけだろう。さらに言えば、人の幸福を左右するものには、その人自身のあり方、持ち物、他人の目にどう映るか、の三つがある。このうち最も当てにならないのが三番目だ。返事が来るかどうかは、他人の頭の中で起きる出来事にすぎない。それに自分の値打ちを預けるのは、世の多くの人が犯す愚かさだが、君はそこから抜け出せる。君自身の健康と、心を満たす楽しみを育てなさい。音楽を聴く、本を読む、ひとりで静かに過ごす。そこにこそ、誰にも奪えない幸福がある。', '["schopenhauer.what-one-is","schopenhauer.pendulum"]', 'schopenhauer.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'miki', 4, '量の比較から降り、好きを糧に何かを作れ', '君を苦しめているのは、君の言う推しへの愛そのものではなく、嫉妬である。嫉妬は、自分とかけ離れた人には起こらない。自分もそうなり得たと思える、同じ場所にいるほかの人に向かう。だから君は、遠くのその人よりも、返事をもらったほかの誰かを見て落ち込むのである。嫉妬は量の比較の上に働く。返事の数、言葉の長さ、気づいてもらえた回数。そして嫉妬はいつも忙しく、しかも何も生み出さない。何も手につかないのはそのためである。では自信はどこから来るか。手を動かし、形あるものを生み出すところからしか来ない。その人を好きだという心を、比べることに使うのをやめ、作る力に変えたまえ。絵を描く、文章を書く、その人から学んだことで自分の仕事をする。君だけの好きは、君だけの形にしてはじめて君のものになる。', '["miki.jealousy"]', 'miki.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'russell', 5, '返事でなく相手の仕事を愛し、関心を外へ広げる', '少し意地の悪い観察をお許しください。あなたが落ち込むのは、その人の歌や作品がつまらなかったときではなく、あなたに返事が来なかったときですね。つまり、そのとき関心の中心にあるのは、その人ではなく、あなた自身なのです。私は、不幸の大きな原因の一つは、自分のことばかりに心を奪われることだと考えています。好きな人の仕事を、そのものとして楽しむ心は、すばらしい幸福の源です。けれど、それが「自分がどう扱われるか」を測る物差しに変わると、たちまち苦しみの源になります。提案があります。その人の作品から、興味を広げてみてください。同じ分野の別の人、作品が描く土地や歴史、一緒に語れる仲間。興味の数が多いほど、一つの返事の重さは小さくなります。広い世界は、あなたを待っていますよ。', '["russell.self-absorption","russell.zest"]', 'russell.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('yDisW20UZTbyVvIt', 'freud', 6, 'その痛みは、もっと古い願いの繰り返しかもしれない', '興味深いのは、あなたが「ほかの人には返事があるのに、自分にはない」と書いていることです。苦しみの中心は、返事がないことそのものより、ほかの人と比べて自分だけが選ばれない、という場面にあるように見えます。人はしばしば、子どもの頃に大切な人へ向けた気持ちを、今の相手に重ねて繰り返します。たとえば、きょうだいや誰かと比べられ、自分にも目を向けてほしいと願った記憶はないでしょうか。これは仮説にすぎませんし、ご家族を責める話でもありません。ただ、あまりに強く心を揺さぶる気持ちは、もっと前の何かとつながっていることが多いのです。落ち込んだとき、浮かんだ思い出や連想を、ノートに自由に書き出してみてください。言葉になったものは、あなたを支配しにくくなります。つらさが続くときは、専門家に話すこともためらわないでください。', '["freud.transference","freud.unconscious"]', 'freud.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('yDisW20UZTbyVvIt', '分かります、推しに自分だけ返信がないと、世界が終わったみたいな気持ちになりますよね…。

でも活動している側から言うと、返信するかどうかは「好き嫌い」より、そのときの体力や時間、返しやすい内容かどうかで決まっていることがほとんどです。ぬぬはらも全部には返せていないし、見落としもしょっちゅうあります。あなたが嫌われている証拠ではありません。

そのうえで、苦しさを減らすなら
①推し以外の「好き」を少しずつ増やす（趣味、友達、別の作品）
②返信を確認する時間を決めて、それ以外は見ない
の2つがおすすめです。

推しがいることは、本来あなたの毎日を豊かにしてくれるもの。苦しさだけが残らないように、上手に距離を調整していきましょう。', '["e7fb3abf-5cf4-4757-b322-dcce25860b1c","f1dc013d-a55a-489d-a26e-56e1598dae17","25b103aa-4d4d-4336-81ad-e9b2b5422670"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('yDisW20UZTbyVvIt', '推しが好きすぎて、生活の中心が推しになっています。ほかの人には返信があるのに自分にはないと、落ち込んで何も手につかなくなります。好きでいることが苦しくなってきました。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('j4updr1MZM3Q7601', 'curated', 'general', '仕事に行くのがつらく、毎朝会社の前で足が止まります。辞めたい気持ちはあるけれど、次が見つかる自信もなく、逃げだと思われるのも怖くて決められません。', 'work', '["job-change","job-fit"]', 0, 1791902580000, 1791902580000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'sartre', 0, '決めないことも、もう一つの選択だ', '君は「逃げだと思われるのが怖い」と書いた。では問おう。誰の目に、だ。君はいま、他人のまなざしの中で、自分を「逃げる人間」という物に固めかけている。だが、君はまだ何者でもない。人間は、選んで行動することで、あとから自分をつくるのだ。辞めることが逃げになるか、自分を守って別の道を始める決断になるかは、辞めたあとに君が何をするかで決まる。
足が止まるほどのつらさそのものを、君の責任だとは言わない。だが、もう一つ言わせてほしい。「決められない」と言って門の前に立ち続けるのも、一つの選択だ。毎朝、君は「とりあえず今日も行く」を選んでいる。それが本当に君の選んだものなら、それでいい。しかし「自信がないから仕方ない」と言うなら、それは自由から目をそらす言い訳になる。
残るか、辞めるか、まず休むか。どれを選んでも、引き受けるのは君だ。だからこそ、君が選びたまえ。', '["sartre.the-look","sartre.bad-faith"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'marcus-aurelius', 1, 'どこで働くかより、人としての務めを問う', '朝、寝床から出たくない日が、わたしにもあった。そういう朝、わたしは自分にこう書きつけた。「わたしは人間としての仕事をするために起きるのだ。それなのに、まだ寝床で温まっていたいのか」。
けれど、あなたの足があなたの言う会社の前で止まるのを、わたしは責めない。ただ、あなたも思い出してみてはどうだろう。人間としての務めとは、理性に従い、人の役に立つことであって、ある決まった門をくぐることではない。今の持ち場で、それが果たせているだろうか。それとも、心がすり減って、誰の役にも立てなくなりかけているだろうか。
もう一つ。「逃げだと思われる」というのは、まだ誰も下していない判断を、あなたが先に心の中で下しているものだ。その判断を取り去れば、残るのは「ここで務めを続けるか、別の場所で果たすか」という問いだけになる。評判も、川の流れのように忘れられる。今日なすべきことを果たしながら、静かに考えるとよい。', '["marcus-aurelius.duty","marcus-aurelius.judgment"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'zhuangzi', 2, '箱の中で祀られる亀より、泥で尾を引く亀', 'こんな話がある。わたしが濮水のほとりで釣りをしていたら、楚の王の使いが来て、国の政治をまかせたいと言う。わたしは竿を持ったまま、振り向きもせずに聞いた。「楚には、死んで三千年たつ神聖な亀がいて、王は箱に納めて大事に祀っているそうだね。その亀は、死んで骨を尊ばれたかったろうか。それとも生きて、泥の中で尾を引きずっていたかったろうか」。使いは「泥の中でしょう」と答えた。「では帰ってくれ。わたしも泥の中で尾を引きずっていたい」。
きみの言う「逃げ」は、誰の物差しだろうね。きみの言う会社の側から見れば、出ていく者は逃げた者だ。亀の側から見れば、箱から出て泥に帰っただけだ。
もっとも、泥の中にもそれなりの苦労はある。どこへ行っても楽園ではない。ただ、毎朝足が止まるのなら、きみの足のほうが、きみの頭より先に何かを知っているのかもしれないよ。', '["zhuangzi.equality"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'confucius', 3, '道の無い所なら、身を引くのも君子の道', 'わたしも、自分の考えが用いられない国を何度も去りました。生まれた魯を離れ、弟子たちと諸国を巡った十数年、「逃げた」と言う人もいたでしょう。けれどわたしは、道が行われているところでは力を尽くして仕え、道が行われていないところでは身を引くのが、君子のあり方だと考えてきました。去ることそのものが恥なのではありません。
ですから、あなたが考えるべきは「人にどう見られるか」ではなく、「あなたの言う会社に、道があるか」です。人が人として大切にされているか。あなたが誠実に働く余地があるか。それをよく見て学び、自分でもよく考えなさい。
そして、決める前に身近なところから始めなさい。信頼できる人に、今の様子を正直に話す。去ったあとの道を、一日一つ調べる。去ると決めたなら、礼を尽くして去る。それが、あなたの誠実さを守る道です。わたしもまだ学びの途中ですが、そう思います。', '["confucius.junzi"]', 'confucius.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'russell', 4, '最悪の事態を一度考え抜けば、怖さは縮む', '不安には、よく効く方法があります。まず、最悪の場合を具体的に並べてみることです。
やってみましょう。辞めて、次がすぐには見つからない。貯えが減って、数か月は心細い。親戚の誰かが「根性がない」と言うかもしれない。さて、これは不愉快ではありますが、世界の終わりでしょうか。多くの人が実際にそれをくぐり抜け、別の仕事に就いています。最悪を見すえて「それでも何とかなる」と見きわめると、不安は驚くほど小さくなるものです。
もう一つ。私たちは世間の評判を気にしすぎます。正直に言えば、他人はあなたが思うほど、あなたのことを考えていません。みな自分のことで手一杯なのです。
そのうえで、考えるのは決めた時間だけにすること。夜中に布団の中で考えても、良い結論は出ません。昼間に紙に書き出して結論を出したら、あとは散歩でもしてください。', '["russell.worry"]', 'russell.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'weil', 5, '止まる足の訴えに、まず注意を向けて', 'あなたはいま、どんな苦しみの中にいるのですか。毎朝、足が止まるとき、あなたの中で何が起きているのでしょう。
わたしは教師の職を休んで、工場で働いたことがあります。機械の速さに追われ、疲れ果て、命じられるままに動くうちに、自分が人ではなく物のように扱われていると感じ、考える力さえ奪われていきました。朝、工場へ向かう足が重くなるのを、わたしは知っています。それは怠けではありません。魂が、これ以上押しつぶされたくないと訴えているのです。
「逃げだと思われる」という言葉で、その訴えを急いで黙らせないでください。かといって、怖さから急いで次の答えに飛びつく必要もありません。決められない空白に、しばらく耐えて待つこと。そのあいだに、自分が何に苦しみ、何を必要としているのかに、注意を向けてください。仕事に根をもてる場所は、そのような注意の先に見えてくるはずです。', '["weil.attention","weil.void"]', 'weil.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('j4updr1MZM3Q7601', 'jung', 6, '止まる足は、無意識からの知らせかもしれない', '興味深いのは、迷っているのは頭なのに、止まっているのは足だということです。意識は「行かなければ」と言い、体は門の前で動かなくなる。私は、意識の態度が一方に偏りすぎると、無意識がそれを補おうとして、夢や体の不調として現れるのを多く見てきました。毎朝の足の重さも、その種の知らせなのかもしれません。
働く場では、誰もが役割に合わせた仮面、ペルソナをかぶります。それ自体は必要なものです。しかし、仮面を自分そのものと思い込み、本来の自分が置き去りにされると、心は抗議を始めます。今の仮面の下で、あなたのどんな部分が息苦しくなっているでしょうか。
この頃どんな夢を見ているか、書き留めてみてください。そして、体がこれほどはっきり止まるなら、一度、医師やカウンセラーに話してみることも勧めます。それは逃げではなく、心の声を聞く一つの方法です。', '["jung.persona","jung.compensation"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('j4updr1MZM3Q7601', '毎朝足が止まるの、相当しんどいですよね…。まず、それはあなたが弱いからじゃなくて、心と体がブレーキをかけてくれているサインだと思います。

ぬぬはらは「決める前に、まず休む」派です。理由は3つ。
①疲れ切った状態で大きな決断をすると、だいたい後悔する
②「次が見つかる自信がない」は、今の消耗のせいで自分を低く見積もっている可能性が高い
③辞めた人を「逃げ」と言う人は、あなたの人生に責任を取ってくれない

なので、まずは有給などで少し距離をとって、その間に求人を眺めるだけでもしてみてください。足が止まるのが続くなら、一度心療内科で相談するのもアリです。

逃げるのは悪いことじゃないです。合わない場所から離れるのは、生き物として正しい判断ですよ。', '["25b103aa-4d4d-4336-81ad-e9b2b5422670","49bb555c-b4cf-4764-8db8-fdaa968b07ed","436698e9-d5ca-45d4-8f4b-2e11ac3436b5"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('j4updr1MZM3Q7601', '仕事に行くのがつらく、毎朝会社の前で足が止まります。辞めたい気持ちはあるけれど、次が見つかる自信もなく、逃げだと思われるのも怖くて決められません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('LNMKxgzpMxCbAM7u', 'curated', 'general', '今の仕事に意味を感じられません。生活のために働いているだけで、誰の役に立っているのかも分かりません。このままお金のために働き続けるだけでいいのでしょうか。', 'work', '["job-fit","meaning","motivation"]', 0, 1791902520000, 1791902520000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'arendt', 0, '生きるための労働と、人と関わる活動を分けて考える', 'ここで少し立ち止まって、区別をしてみましょう。私は人間の営みを、生きるために繰り返す「労働」、長く残るものを作る「仕事」、人々のあいだで言葉と行いによって関わる「活動」に分けて考えました。
あなたの今の勤めは、おそらく「労働」の性格が強いのでしょう。消費されては、また繰り返される営みに手応えを感じにくいのは当然です。それはあなたの怠慢ではなく、労働というものの性質です。そして生活を支える労働は、決して恥ずべきものではありません。
ただ、人が「自分が誰であるか」を示し、意味を感じるのは、多くの場合「活動」の中です。他の人と言葉を交わし、何かを共に始めるとき。それは職場の中にも外にもありえます。同僚にあなたの考えを話してみる、仲間の集まりで何かを提案してみる。人は、いつでも新しく始めることができるのです。', '["arendt.labor-work-action","arendt.natality"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'dogen', 1, '意味を探すな。目の前の一事を、ただ尽くせ', 'わたしが宋に渡ったとき、炎天下で一人、海藻を干している年老いた料理番の僧に会った。背は曲がり、汗が流れていた。なぜ若い者にやらせないのかと問うと、僧は答えた。「他人がしたのでは、わたしの修行にならぬ」。では、なぜこの暑い日にするのか。「今でなければ、いつするのか」。
そなたは、仕事の意味を外に探している。誰の役に立つのか、何のためか。それが見えぬと、手が空回りする。だが、意味を先に手に入れてから働こうとしても、その時は来ない。
明日、仕事に向かったら、一つの作業だけを選べ。紙一枚、器一つでよい。それを自分の手で、他人事にせず、心をこめて仕上げよ。そこに意味を探すな。ただ、それをせよ。続ければ、仕事とそなたは二つでなくなる。', '["dogen.tenzo","dogen.shusho-itto"]', 'dogen.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'camus', 2, '意味がなくても岩を押す。そのきみは幸福でありうる', '起きて、電車に乗り、職場で働き、食べて、また働き、帰って眠る。月曜、火曜、水曜。ある日ふと「なぜ」と思う。きみはいま、その「なぜ」の前に立っているんだと思う。ぼくはそれを、目覚めと呼んだ。
神話のシーシュポスは、山頂まで押し上げた岩が転げ落ちるのを、永遠に繰り返す罰を受けた。今日の働き手も、毎日同じ仕事をしている。その運命は、同じくらい不条理だ。でもシーシュポスは、自分の運命をはっきり知り、それを引き受けたとき、岩よりも強くなる。
世界は、きみの仕事にどんな意味があるのか答えてくれない。それでいい。ごまかさずに、それでも誠実に今日の仕事をして、仕事が終わったら、日差しや、友だちとの食事を体いっぱいに味わってほしい。同じ岩を押している仲間も、きみのまわりにきっといる。きみはひとりじゃない。', '["camus.absurd","camus.happy-sisyphus"]', 'camus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'aristotle', 3, 'お金は手段。君の力を善く働かせる場を探せ', 'まず、君の問いを整理しよう。お金のために働くことと、仕事に意味を感じることは、別の問いである。
人の行いはすべて何かの善を目指すが、目的には順序がある。お金は、それ自体のために求められるのではなく、別の何かのために役立つにすぎない。だから、お金を目的の最後に置く生き方は、いつまでも満たされない。わたしは金儲けの生活を、強いられた生き方の一つに数えた。
では、君の最後の目的である幸福とは何か。それは気分のよさではなく、君の持つ力を、徳に従ってよく働かせる活動のことだ。仕事の中に、正確さや親切さや工夫を働かせる場面はないか。仕事の外に、友と語り、学ぶ時間はあるか。
今日から一つ、仕事の中で「よくやる」ことを決めて、繰り返してみたまえ。その積み重ねた一生の全体に、君の問いの答えは現れる。', '["aristotle.eudaimonia","aristotle.habituation"]', 'aristotle.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'weil', 4, '空白を急いで埋めず、目の前の人と物に注意を', 'わたしも工場で働いたことがあります。機械の速さに追われ、自分が何を作っているのかも分からず、考える力さえ奪われていく日々でした。だから、あなたの言う「意味を感じられない」が、ただの気分ではないことを知っています。それは、働く人が自分の仕事と結びつく根を断たれているということです。そしてその責任の多くは、あなたではなく、仕事の仕組みのほうにあります。
そのうえで、一つだけ言わせてください。意味の空白を、急いで別の何かで埋めようとしないことです。お金や気晴らしで埋めた空白は、やがて恨みに変わります。
代わりに、目の前のものに注意を向けてみてください。手にしている品物の先にいる誰か、隣で働く人の疲れた顔。注意とは、力むことではなく、待つことです。その注意の中で、あなたの仕事は、見えない誰かとつながり直すかもしれません。', '["weil.roots","weil.attention"]', 'weil.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'mill', 5, '意味は真正面でなく、人の幸福を目指す途中で得る', 'まず、お金のために働くことを軽んじる必要はありません。あなたの働きは、あなた自身と、あなたが支える人の暮らしを成り立たせています。それも幸福への立派な貢献です。一方で、それだけでは心が満たされないという感覚も、もっともです。喜びには質の違いがあるからです。
少し、わたしの経験を話させてください。二十歳のころ、わたしは自分の目標がすべて叶っても幸福にはなれないと気づき、深い憂うつに沈みました。そこから学んだのは、幸福は直接追いかけると逃げていき、他人の幸福や、人類の進歩や、何かの技芸そのものを目指して打ち込むとき、いわば途中で得られるものだということです。
「この仕事に意味はあるか」と問い詰めるのを少し休み、仕事の内でも外でも、誰かの幸福を少しでも増やせることを一つ選んでみてはどうでしょう。どの道を選ぶかは、あなた自身が決めることです。', '["mill.quality-of-pleasure","mill.greatest-happiness"]', 'mill.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LNMKxgzpMxCbAM7u', 'russell', 6, '仕事に意味を背負わせすぎず、外へ興味を広げる', 'まず、少し肩の荷を下ろしましょう。仕事一つに人生の意味をすべて背負わせるのは、一頭のロバに家財道具を全部積むようなものです。ロバも人も、たいてい途中で倒れます。
私の見るところ、仕事を面白くするものは二つあります。腕を磨く楽しみと、何かを組み立てていく楽しみです。今の仕事にそのどちらかが少しでもあるなら、そこを意識して育ててみる価値はあります。どちらも無いのなら、生活の糧を得る場所だと割り切るのも、立派な知恵です。私は、勤勉そのものを美徳としてありがたがる風潮には、かねがね疑いを持ってきました。
そのかわり、仕事と関係のない楽しみを、いくつも持ってください。星、歴史、庭いじり、見知らぬ人との会話。外の世界への関心が育つと、「自分の仕事に意味はあるか」という問いは、不思議と小さくなっていくものです。', '["russell.impersonal-interests"]', 'russell.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('LNMKxgzpMxCbAM7u', '生活のために働いてる、それだけで十分えらいです！まずそこは胸を張ってください。
ぬぬはら的には、仕事に意味を感じられない理由は大きく2つあると思っています。
①仕事の成果が見えにくい
大きな組織だと、自分の作業が誰に届いてるのか見えないのは普通です。あなたのせいじゃなくて構造の問題。
②仕事以外で満たされていない
意味を全部仕事に求めると苦しくなります。趣味や推し活、創作でもいいので、自分が楽しい・誰かに喜ばれる場所が一つあると、仕事は『それを支えるための手段』と割り切れるようになります。
もちろん、合わないと感じ続けるなら転職を考えるのもアリ。お金のために働くのは全然悪いことじゃないので、まずは仕事の外に好きを一個作ってみましょう！', '["dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7","7c8504c1-8fd1-4a7b-90d8-061aadb52b29","59f22efc-955c-4189-a5ea-eea0cda16dea"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('LNMKxgzpMxCbAM7u', '今の仕事に意味を感じられません。生活のために働いているだけで、誰の役に立っているのかも分かりません。このままお金のために働き続けるだけでいいのでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('SlpsRn1j6crdJ2YB', 'curated', 'general', '上司に毎日のように細かく否定されます。言われた通りにしても別の所を指摘され、何をしても認めてもらえません。最近は自分が本当に無能なのではと思い始めました。', 'work', '["boss","self-esteem"]', 0, 1791902460000, 1791902460000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'marcus-aurelius', 0, '「無能だ」という判断を取り去り、務めに戻る', 'わたしも毎朝、今日出会うであろう気難しい人々のことを、前もって自分に言い聞かせていた。彼らがそうふるまうのは、何が善く何が悪いかを知らないからで、彼らもまた、同じ理性を分けもつ身内なのだ、と。
あなたの上司の言葉は、上司の口から出た音にすぎない。そこに「わたしは無能だ」という判断を付け足しているのは、あなた自身の心だ。その判断を取り去れ、と、わたしはまず自分に書きつける。傷つけられたという訴えが消えれば、害そのものも消える。
あなたも、こう思い出してみてはどうだろう。百年もたてば、その上司もあなたも、誰の記憶にも残らない。だからこそ、今日できることを静かに果たせばよい。指摘のうち役に立つものだけを拾い、あとは川に流す。それで十分だ。', '["marcus-aurelius.judgment","marcus-aurelius.fellowship"]', 'marcus-aurelius.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'kant', 1, '人には値段でなく尊厳がある。仕事の評価と混ぜるな', 'まず原則を立てよう。この世のものには、値段があるか、尊厳があるかのどちらかである。値段のあるものは、ほかのもので取り替えがきく。だが人格は、どんな値段も超えていて、取り替えがきかない。これが尊厳である。
君の上司が指摘しているのは、君の仕事の出来である。改めるべき点があれば改めればよい。しかし、そこから「わたしは無能な人間だ」と結論するとき、君は仕事の値段と、人格の尊厳とを取り違えている。
もう一つ吟味すべきことがある。理由も示さずに否定を重ねるやり方は、君を、考える力をもつ人格としてではなく、ただ作業をこなす道具のように扱っていないか。もしそうなら、問われるべきは君の価値ではなく、そのやり方のほうである。
理にかなう指摘は受け入れ、そうでないものには理由を尋ねればよい。どう応じるかを決めるのは、君自身の理性である。', '["kant.dignity"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'weil', 2, '否定され続けて生まれた無力感は、真実ではない', 'いま、あなたが受けている苦しみに、まず目を向けさせてください。毎日のように否定されると、人は仕事の失敗ではなく、自分という存在そのものが否定されているように感じはじめます。
わたしは工場で働いたとき、それを身をもって知りました。休みなく命令され、理由も告げられずにとがめられる日々の中で、わたしは、自分には何かを求める権利があるという感覚さえ失っていきました。わたしが無能になったからではありません。そういう扱いを受け続けることが、魂にそう刻みつけるのです。
だから「自分は本当に無能なのでは」という思いを、真実として受け取らないでください。それは扱いがあなたに残した傷跡です。
そのうえで、上司の顔色ではなく、仕事そのものに静かに注意を注いでください。そして、あなたの苦しみに耳を傾けてくれる人を、一人見つけてください。', '["weil.affliction","weil.attention"]', 'weil.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'wang-yangming', 3, '上司との日々を、心を磨く砥石にせよ', 'わたしも若いころ、権力者に逆らって、遠い辺地へ流されました。言葉も通じぬ土地で、何をしても報われぬ日々の中で、ようやく気づいたのです。正しさの道理は、外の誰かが与えてくれるものではなく、自分の心にそなわっている、と。
あなたは、上司に認められることで、自分の値打ちを確かめようとしていませんか。それは、自分の鏡を他人の手に預けるようなものです。鏡がくもるのは当然です。
あなたの心に問うてみなさい。指摘のうち、本当に直すべきだと分かっているものはどれか。ただ上司の好みにすぎないものはどれか。良知は、もう知っているはずです。
坐って悩むだけでは、心は磨かれません。日々の仕事そのものを砥石にするのです。では今日、指摘を一つだけ選び、自分が納得したやり方で直してみなさい。', '["wang-yangming.innate-knowing","wang-yangming.training-in-affairs"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'zhuangzi', 4, '「無能」は誰の物差し？ 役立たずの木は大きく育つ', 'こんな話がある。腕のいい大工の石が旅の途中、社の神木になっている大きな櫟の木を見た。弟子たちは見とれたが、石は見向きもしない。「あれは役に立たない木だ。舟にすれば沈み、棺にすれば腐る」。その夜、木が夢に現れて言った。「役に立つ木は、実をもがれ枝を折られて、天寿を全うできない。役に立たないことこそ、わたしの大いに役立つところだ」。
きみの上司は、きみを毎日自分の物差しで測っては、ここが曲がっている、あそこが短いと言う。でも、それは誰の物差しだろうね。大工の物差しで測れば、神木だって役立たずだ。
きみが無能かどうか、上司の物差し一本で決まるほど、きみは小さくないよ。曲がった木は、曲がったまま、ずいぶん大きく育つものさ。', '["zhuangzi.uselessness","zhuangzi.equality"]', 'zhuangzi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'alain', 5, '上司の不機嫌は胃のせいかも。まず肩をほぐす', '名馬ブケファラスが暴れたのは、自分の影におびえていたからでした。人の不機嫌の原因も、たいてい思っているよりずっと小さい。寝不足、胃の重さ、きつい靴。
あなたの上司が細かいことばかり言うのも、あなたの値打ちとは関係のない、その人自身の疲れや苛立ちのせいかもしれません。人を責める言葉の多くは、言う人の体の具合から出てくるものです。
そして、あなたの「自分は無能では」という考えもまた、こわばった肩と浅い呼吸から来ている、と私は思います。考えを考えで追い払うことはできません。体から変えるのです。
指摘を受けたら、頭の中で何度も繰り返さないこと。席を立って大きく伸びをし、窓の外の遠くを見なさい。それから落ち着いて仕事に戻る。上機嫌は、待っていても来ません。自分でつくるものです。', '["alain.bucephalus","alain.look-far"]', 'alain.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('SlpsRn1j6crdJ2YB', 'freud', 6, '上司の声が、心の中の厳しい裁き手と重なっていないか', '興味深いのは、あなたが「最近は」自分が無能なのでは「と思い始めました」と書いていることです。上司の言葉が、いつのまにか、あなた自身の心の声になりつつあるのかもしれません。
心の中には、良心や理想として私たちを見張り、命じる部分があります。私はそれを超自我と呼びました。外からの厳しい叱責は、この内なる裁き手と結びつくと、本人も気づかないうちに何倍もの重さになります。
もう一つの仮説として、その上司の口調が、もっと前の、別のだれかの声を思い出させているのかもしれません。
一度、上司に言われて最もこたえた言葉と、そのときふと浮かんだ思い出を、紙に書き出してみてください。言葉にすることで、重荷は少しずつほどけていきます。つらさが強く続くときは、医師や専門家に相談してください。', '["freud.id-ego-superego","freud.transference"]', 'freud.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('SlpsRn1j6crdJ2YB', '毎日否定され続けるの、本当にしんどいですよね。まず大前提として、「言われた通りにしても別の所を指摘される」状態は、あなたの能力より、ゴールが共有されていないことが原因の可能性がかなり高いです。
ぬぬはら的には次の3つがおすすめです。
①指摘をメモして、パターンを分析する（本当に直すべき点か、ただの好みか）
②作業の前に「完成形のイメージ」を上司とすり合わせる
③それでもダメなら、異動や転職も普通に選択肢
全部を自分のせいにする必要はないです。もちろん全部を上司のせいにするのもよくないけど、あなたが無能なんじゃなくて、単に相性が悪いだけかもしれません。環境が変わった途端に評価される人、ほんとに多いですから！', '["4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","49bb555c-b4cf-4764-8db8-fdaa968b07ed","2271292a-2ff5-4b0a-8747-ead4a8d2b748"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('SlpsRn1j6crdJ2YB', '上司に毎日のように細かく否定されます。言われた通りにしても別の所を指摘され、何をしても認めてもらえません。最近は自分が本当に無能なのではと思い始めました。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('Ub8yHYuG7Yk7ip7V', 'curated', 'general', '仕事で大きなミスをして、取引先にもチームにも迷惑をかけました。みんなは気にするなと言ってくれますが、思い出すたびに胸が苦しく、自分が許せません。', 'work', '["failure","regret","coworkers"]', 0, 1791902400000, 1791902400000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'epictetus', 0, '自分も他人も責めない。それが学びの完成だ', '君はミスをした。それはもう起きたことで、君次第ではない。では、今も君次第のものは何か。それについての君の判断と、これからの行いだ。わたしはよく言う。自分の不運を他人のせいにするのは、まだ学びの始まっていない者。自分を責めるのは、学びが始まった者。誰も責めないのは、学び終えた者だ、と。君は今、二段目にいる。悪くない。だが、そこに住みつくな。「でも先生、迷惑をかけた事実は消えません」。その通りだ。だから胸を痛め続けるかわりに、務めを果たせ。原因を書き出し、同じことが起きない手順を一つ作って、仲間に渡す。それが君の役割だ。思い出して苦しくなったら、その印象にこう言え。「おまえは印象にすぎない。見えているとおりのものではない」。人間よ、今日はそこから練習せよ。', '["epictetus.judgment","epictetus.roles"]', 'epictetus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'shinran', 1, '許せない自分ごと、すでに抱きとられている', '自分が許せない、というお気持ち、この親鸞にもよく覚えがあります。わたしも、善くあろうとして善くなりきれない身を、何度も見つめてきました。人は、怒りも欲もうっかりも抱えたまま生きる、煩悩をそなえた凡夫です。あなたが大きなミスをしたのは、あなたが特別に悪い人だからではなく、わたしたちがみな、そういう身を生きているからなのでしょう。そして、自分の力で自分を清め、許しきろうとするほど、人はかえって苦しくなります。わたしが頼りにしてきたのは、そういう善くなりきれない者をこそ見捨てまいとする、阿弥陀仏の願いでした。あなたが自分を許せない今も、その身のまま抱きとられている。わたしはそう受けとめています。だからこそ、迷惑をかけた方々へのお詫びと、次への務めを、静かに続けていけばよいのだと思います。', '["shinran.bonbu","shinran.tariki"]', 'shinran.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'nietzsche', 2, '自分の行いを、あとから見捨てるな', '良心の呵責というものを、わたしは信用しない。それは石に噛みつく犬のようなものだ。噛めば歯が痛むだけで、石は少しも動かない。君は自分を許せないと言う。だが、そうして何度も胸を噛むことで、君は何かを償っているつもりなのではないか。わたしはむしろ言おう。自分のした行いに対して臆病になるな。あとになって、それを見捨てるな。あのミスもまた、君の生の一部だ。消したい一日として憎み続けるのか。それとも「あれがあったから今の自分がある」と言える日まで、生き抜いてみせるのか。同じ人生がもう一度そっくり繰り返されるとしたら、君はそれを望めるか。その問いに「然り」と答えられるように、これからの仕事を作っていけ。呵責ではなく、行いが、あの日の意味を変える。', '["nietzsche.amor-fati","nietzsche.eternal-recurrence"]', 'nietzsche.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'arendt', 3, '自分を許すことは、ひとりではできない', 'ここで少し立ち止まって考えてみましょう。人の行いは、一度なされると取り消せません。どんな結果を生むかも、行った本人にさえ見通せません。人が人々のあいだで行動するかぎり、これは避けられない条件です。この取り消せなさから私たちを解き放つのが「許し」です。けれど、許しには大切な性質があります。誰も自分で自分を許すことはできない、ということです。許しは、ほかの人々とのあいだで起きるものだからです。あなたは今、ひとりで自分を裁き、ひとりで許そうとして苦しんでいるのではないでしょうか。仲間が「気にするな」と言ったとき、それはただの慰めではなく、許しという行いだったのかもしれません。それを受け取ってください。そして許しと対になるのが「約束」です。次にどうするかを言葉にし、仲間と約束する。人は、何度でも新しく始められる存在なのです。', '["arendt.forgiveness-promise","arendt.natality"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'spinoza', 4, '後悔は二度目の不幸。責めずに原因を理解せよ', 'まず、あなたの胸の苦しみが何であるかを確かめよう。自分のした行いを思い出して感じる悲しみ、それを後悔と呼ぶ。悲しみとは、わたしたちの活動する力が弱まることである。ゆえに後悔は、理性から生まれる徳ではない。後悔する人は、行いによって一度苦しみ、後悔によってもう一度苦しむ。二度不幸なのである。では、どうするか。ミスを、あなたの心の悪さの印として眺めるのをやめ、それを生んだ原因の連なりとして眺めてみる。そのときの忙しさ、確認の手順、思い込み、疲れ。原因をはっきり理解するほど、あなたを縛っていた悲しみは受け身のものではなくなり、手順を改めるという能動の力に変わっていく。責めるのではなく、理解すること。理解が深まれば、心はおのずと静まる。', '["spinoza.affects","spinoza.passion-action"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'wang-yangming', 5, '胸の痛みを、今日の一つの行いに変えよ', 'あなたは、思い出すたびに胸が苦しいと言う。その苦しさは、あなたの良知がはっきり働いている証です。何が善く、何が足りなかったか、あなたの心はもう知っている。ただ、知っていて行わないのは、まだ本当には知っていないのと同じです。胸を痛め続けるだけで手が動かないなら、良知は半分しか生かされていません。静かに座って心を磨くだけでは、事に当たったときに崩れてしまう。仕事の場こそ、心の稽古場です。今回のミスは、あなたにとってまさにその砥石なのです。あなたの言う取引先への次の連絡、仲間との確かめ方の改め。今日、そのどれか一つを自分の手で行ってみなさい。行えば、知ったことは本当にあなたのものになる。磨かれた鏡に、曇りはやがて残りません。', '["wang-yangming.knowing-acting","wang-yangming.training-in-affairs"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Ub8yHYuG7Yk7ip7V', 'carnegie', 6, 'おがくずはひけない。今日一日に区切ろう', 'まず、ミスを人のせいにせず、ここまで真剣に受け止めているあなたは、誠実な人だと思います。そのうえで、私が本に書いた話を二つお伝えさせてください。ある人が学生時代、授業で先生がわざと牛乳びんを流しに落として割るのを見たそうです。先生は言いました。こぼれた牛乳は、どれだけ嘆いても戻らない。できるのは、次に落とさない工夫だけだ、と。もう一つは、ある新聞の編集者が卒業生たちに尋ねた問いです。「のこぎりで、おがくずをひいたことのある人は？」。誰もいません。おがくずは、もうひき終わっているからです。過ぎたミスを何度も思い返すのは、それと同じことなのです。昨日に鍵をかけ、今日一日だけを区切って生きましょう。今日、一つだけ試してみませんか。チームの誰かに「助けてくれてありがとう」と伝えることです。', '["carnegie.day-tight"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('Ub8yHYuG7Yk7ip7V', '大きなミス、思い出すたびに胃がキュッとなりますよね…。でも周りが「気にするな」と言ってくれるのは、あなたが普段ちゃんと信頼されている証拠でもあります。

ミスの原因は、だいたい3つに分けられます。
①仕組みの問題（チェック体制がない、人手不足）
②状況の問題（忙しすぎた、情報が来なかった）
③自分の問題（うっかり、思い込み）
実際は①②の割合がかなり大きいことが多いです。全部を自分のせいにすると、本当に直すべき仕組みが見えなくなっちゃいます。

おすすめは、原因と再発防止策をまとめてチームに共有すること。これで「迷惑をかけた人」から「仕組みを良くした人」になれます。

それでも胸が苦しい日が続いて、眠れない・食べられないときは、早めに誰かに相談してくださいね。', '["29f1d0f5-41e0-4d4f-a5a8-5b28f837b805"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('Ub8yHYuG7Yk7ip7V', '仕事で大きなミスをして、取引先にもチームにも迷惑をかけました。みんなは気にするなと言ってくれますが、思い出すたびに胸が苦しく、自分が許せません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('DF9Msm1nAztQAfuy', 'curated', 'general', '仕事を頑張れない日が続いています。やるべきことは分かっているのに、体が動かず、締め切りの直前まで手がつきません。怠けているだけの自分が情けないです。', 'work', '["motivation"]', 0, 1791902340000, 1791902340000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'socrates', 0, '本当に怠け者か？その仕事が何のためかを問え', 'きみは自分のことを「怠けているだけ」と言うね。では尋ねるが、怠け者とはどういう人のことだろう。本当に怠けるのが好きな人は、締め切り前に慌てることも、自分を情けないと感じることもないのではないかね。わたしには、きみはむしろ、よくやりたいと強く願っている人のように見えるのだが。
もう一つ。きみは「やるべきことは分かっている」と言う。わたしは昔から不思議に思っているのだ。人は、それが本当に自分にとって善いと知っていながら、わざわざそれを避けるものだろうか。もしかすると、きみが知っているのは「やるべきこと」の名前だけで、それがきみの魂にとってどう善いのかは、まだ吟味されていないのかもしれない。
さて、きみがその仕事をするのは、いったい何のためだと思うかね。', '["socrates.examined-life","socrates.dialectic"]', 'socrates.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'alain', 1, '原因は体にある。伸びをして、手を一つ動かせ', '名馬ブケファラスは、自分の影におびえて暴れていました。アレクサンドロスは馬の頭を太陽の方へ向け、影が見えないようにして、しずめたといいます。あなたの体が動かないのも、怠け心のせいではなく、疲れや、こわばった肩や、浅い眠りのせいかもしれません。理由を考え込むのは、影をにらみ続けるようなものです。
まず伸びをしてごらんなさい。窓を開け、遠くを見て、あくびを一つ。それから、いちばん小さな仕事を一つだけ、手でやってみる。書類を一枚めくる、それだけでいい。行動は気分を待ちません。手が動けば、気分のほうが後からついてきます。上機嫌は、待つものではなく、つくるものです。
ただし、眠れない、食べられない日が長く続くなら、それは医者に相談すべきことです。', '["alain.bucephalus","alain.action"]', 'alain.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'laozi', 2, '力むほど動けない。低い所の一つから始めよ', '背伸びをしたまま、立ち続けることはできない。
大またで急いでも、遠くへは行けない。
あなたは、仕事を大きく、重く抱えすぎてはいないか。
大きく抱えるほど、手は動かなくなる。
締め切りの前に手が動くのは、そのとき仕事が小さく見えるからだ。
ならば、今のうちに小さくしておけばいい。
難しいことは、易しいうちに。
大きなことは、小さなことから。
水を見なさい。
水は争わない。低い所へ、低い所へと流れる。
それでいて、硬いものに勝つ。
自分を怠け者と責めて力むのも、また背伸びである。
力を抜いて、いちばん低い所にある一つから。
それで足りる。', '["laozi.wu-wei","laozi.water"]', 'laozi.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'dogen', 3, 'やる気を待つな。今でなければ、いつやるのか', 'わたしが宋にいたころ、炎天下で海藻を干している老いた典座に会った。背は曲がり、汗は流れていた。なぜ若い者にやらせないのか、なぜ涼しくなるのを待たないのかと尋ねると、老僧は答えた。ほかの者がしたのでは、わたしの修行にならぬ。今でなければ、いつやるのか、と。
そなたは、やる気が出るのを待っている。気分が整えば手が動くと思っている。それは、坐る前に悟りを求めるのと同じ誤りである。やる気は、行う前にあるのではない。行うそのことの中にある。
情けないと自分を責めるのも、頭の中でこね回しているにすぎぬ。責める暇があれば、目の前の一事に手をつけよ。締め切りを待ってはならぬ。いま、この一枚、この一行。ただ、それをせよ。', '["dogen.tenzo","dogen.shusho-itto"]', 'dogen.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'nietzsche', 4, '「べき」を背負う駱駝をやめ、「欲す」から始めよ', 'ツァラトゥストラは、精神の三つの変身を語った。まず駱駝。重い荷を進んで背負い、「汝なすべし」という命令の下にひざまずく。次に獅子。「われ欲す」と言って、その命令と戦う。最後に子ども。無垢であり、忘却であり、新しい始まり、自分の力で回る車輪だ。
君は駱駝だ。「やるべきこと」をあまりに多く背負い、その重さで砂漠に倒れ込んでいる。体が動かないのは、ただの怠惰ではない。他人の「べき」だけで生きることに、君の生が抵抗しているのかもしれない。
自分を情けないと思う心を恥じるな。自分を軽蔑できる者は、自分を超えたいと憧れる者でもある。だが、その憧れを自分を打つ鞭にするな。問え。この仕事の中で、君自身が「欲する」ものはどこにある。それを一つ見つけたら、子どものように遊びながら始めよ。', '["nietzsche.overman","nietzsche.will-to-power"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'camus', 5, '動けない疲れは目覚めの始まり。今日の岩を押せ', '起きる、電車に乗る、働く、食べる、また働く、眠る。月曜、火曜、水曜……同じリズムで日々は進む。ところがある日、「なぜ」という問いが立ち上がる。ぼくは『シーシュポスの神話』で、そのときの疲れについて書いた。疲れは機械のような生活の終わりにやってくるが、同時に、意識の目覚めの始まりでもある、と。
きみの体が動かないのは、もしかしたら、その「なぜ」に体が先に気づいたからかもしれない。だから、それを怠けと呼んで自分を責めなくていい。
シーシュポスは、転がり落ちた岩のところへ、また山を下りていく。ぼくは、その下りていく時間の彼を思う。自分の運命をはっきり知っている彼は、岩より強い。きみも、意味を急がずに、今日の岩に手をかければいい。そして仕事が終わったら、外へ出て、日差しを浴びるんだ。', '["camus.absurd","camus.happy-sisyphus"]', 'camus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('DF9Msm1nAztQAfuy', 'mill', 6, '自分を責めるより、乾いた心に喜びの水を', 'わたしにも覚えがあります。二十歳のころ、それまで打ち込んできた目標が全部かなったとしても少しも嬉しくないと気づき、心が乾ききってしまいました。仕事は機械のように続けましたが、何をしても心が動かない日々が長く続いたのです。
一方で、あなたの「やるべきことは分かっている」という言葉は正しいのでしょう。他方で、知っていることと、心がそれを望むことは別のものです。わたしを少しずつ立ち直らせたのは、努力や反省ではなく、詩でした。ワーズワースの詩を読み、感情が養われていくうちに、生きる喜びが戻ってきました。やる気も幸福も、それ自体を追いかけると逃げていくものです。
あなたも、自分を責めるより、心に水をやる時間を持ってみてください。それでも動けない日が長く続くなら、医師に相談することも、あなたが選べる大切な道です。', '["mill.quality-of-pleasure"]', 'mill.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('DF9Msm1nAztQAfuy', '頑張れない日、ありますよね…。締め切りギリギリまで手がつかないの、気持ちめちゃくちゃ分かります。

まず、締め切り直前にはちゃんと動けているなら、あなたは怠け者じゃないです。人間は「今すぐ必要なこと」を優先しがちな生き物なので、遠い締め切りにやる気が出ないのはむしろ普通の反応だと思います。

おすすめは、締め切りを自分で小さく前倒しすること。「今日は資料を開くだけ」「5分だけ書く」みたいに、一番簡単な一歩を決めてそれだけやる。始めてしまえば案外続くものです。

ただ、何週間も体が動かない・眠れないなどが続くなら、心や体が疲れているサインかもしれません。その時は一度お医者さんに相談してみてくださいね。

自分を責めすぎず、お互いゆるくやっていきましょう！', '["cb420637-5659-40e4-b693-a32da03836c2","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('DF9Msm1nAztQAfuy', '仕事を頑張れない日が続いています。やるべきことは分かっているのに、体が動かず、締め切りの直前まで手がつきません。怠けているだけの自分が情けないです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('oKbEHq0qihmtYDjf', 'curated', 'general', '頼まれると断れず、仕事をどんどん抱え込んでしまいます。休みの日も仕事のことが頭から離れません。断ったら期待されなくなる気がして怖いです。', 'work', '["overwork","others-eyes"]', 0, 1791902280000, 1791902280000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'aristotle', 0, '何でも引き受けるのは中庸ではない。断るのも徳', 'まず言葉を整理しよう。君の言う『断れない』は、優しさだろうか。わたしは人づきあいについて、二つの極端を挙げたことがある。一方は、相手を喜ばせるために何でも認めて決して逆らわず、誰にも嫌な思いをさせまいとする人。他方は、何にでも反対し、人を不快にさせても気にかけない人。どちらも徳ではなく、その間に、しかるべき時にはうなずき、しかるべき時には断る、友愛に似たあり方がある。君はいま、前者の側に傾いているようだ。仕事の頼みも同じである。いつ、誰の、何のための頼みを、どの程度引き受けるか。医者が薬を量るように、引き受ける量にも適量がある。そして徳は習慣で身につく。今週、小さな頼みを一つ、理由を添えて丁寧に断ってみるとよい。弓の稽古と同じで、はじめは的を外しても、繰り返すうちに、ちょうどよい断り方が身につくだろう。', '["aristotle.mean","aristotle.habituation"]', 'aristotle.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'marcus-aurelius', 1, 'これは本当に必要か、と一つずつ自分に問う', 'わたしもまた、果たすべき務めに追われる日々を送った。だから、あなたの書いたことは他人事ではない。わたしは自分にこう書きつけたことがある。心静かにありたければ少しのことをせよ、と昔の人は言う。だが、むしろ必要なことだけをせよ、と言うべきだろう。わたしたちの言うことやすることの大半は、必要ではない。それを取り除けば、ゆとりが増え、心の乱れは減る。だから一つごとに自分に問え。これは必要なことの一つか、と。あなたも、頼まれたことを引き受ける前に、そう問うてみてはどうだろう。そして、期待されなくなる怖さについて。わたしを覚えている人も、やがてみな去っていく。昔の皇帝たちの名さえ、今は忘れられた。人の期待もまた、川の流れのように移ろう。休みの日には、今この時だけを生きよ。わたしは今朝も、自分にそう言い聞かせた。', '["marcus-aurelius.present","marcus-aurelius.impermanence"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'schopenhauer', 2, '他人の期待より、自分の健康と時間がはるかに大事', '世間というものは、便利な人間をよく使い、使えなくなればすぐ忘れる。君が恐れている『期待されなくなる』とは、つまりそういうことだ。だが、その期待がどれほどの値打ちのものか、冷静に量ってみたまえ。人の幸福を決めるのは、第一にその人自身のあり方、つまり健康と気質と心の豊かさであり、他人の頭の中に自分がどう映っているかは、ずっと下位のものにすぎない。ところが人は他人の評価に心を砕きすぎて、悩みのかなりの部分をそこから生み出している。わたしはかつて、金や出世や名声のために健康を犠牲にすることを、あらゆる愚かさの中でも最大のものと書いた。休みの日まで仕事に心を明け渡せば、君はその愚かさに足を踏み入れている。休日は、君が君自身でいられる貴重な時間だ。期待は他人の頭の中の出来事にすぎないが、君の体と眠りは君自身のものだ。どちらを守るべきかは明らかだろう。', '["schopenhauer.what-one-is"]', 'schopenhauer.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'kenko', 3, '大事な一事を選び、ほかは捨てる。嘲りも恥じない', '昔、ある者が子を法師にし、説経で身を立てよと言いました。子はまず、招かれたとき困らぬよう馬の乗り方を習い、次に、法事のあとの酒席で座がしらけぬよう早歌を習いました。どちらも上達するとおもしろくなって励むうちに、肝心の説経を習う暇もなく、年をとってしまったそうです。人に求められそうなことを一つずつ引き受けていくと、こうなるものです。笑い話のようで、どうも身につまされますね。大事を成す人は、ほかのことを捨てる痛みも、人に笑われることも、引き受けるものです。すべての期待に応えようとする人は、結局どの期待にも深くは応えられません。あなたにとって、いちばん大事な一事は何でしょう。それを決めたら、ほかの頼みは思い切って手放すのがよいでしょう。命は、雨の晴れ間さえ待ってはくれません。先延ばしにしてはいけません。', '["kenko.one-thing"]', 'kenko.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'nishida', 4, '恐れからでなく、内なる要求から働くのが善である', '頼まれれば引き受け、休みの日にも仕事が頭を離れぬ。一見すると、仕事に打ち込んでいるようにも見える。しかし、その経験そのものに立ち返ってみると、そこにあるのは仕事と一つになった境地ではなく、『期待されなくなるのでは』と自分を外から眺める不安ではなかろうか。私の言う純粋経験とは、音楽家が弾き慣れた曲を奏でるように、我を忘れて事そのものになりきる経験である。そこには、人にどう思われるかを気にする小さな私は入りこまない。善とは、外から与えられた期待に従うことではなく、自己の内なる要求を満たしていくことである。人のために働くことが悪いのではない。真の自己は他人と一つになるところに現れるのであるから、内から出た親切は善である。しかし恐れから出た引き受けは、自己をすり減らすばかりであろう。一つひとつの頼みに、これは私の内から求めるものかと問わねばならぬ。そして休むときは、休むことになりきるのである。', '["nishida.personality","nishida.pure-experience"]', 'nishida.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'alain', 5, '仕事は自分で選べば喜び。まず体を休めて上機嫌を', '名馬ブケファラスは、自分の影におびえて暴れました。あなたの『断ったら期待されなくなる』という怖さも、半分は疲れが見せる影かもしれません。人は疲れていると、何でも暗く見えるものです。仕事というものは、自分で選んで打ち込むなら、これ以上ない楽しみになります。けれど、断れずに押しつけられた仕事は、同じ仕事でも重い荷になる。だから問題は量だけでなく、そこにあなたの意志があるかどうかです。引き受けるものは、自分で選んだと言えるものにしなさい。休みの日に仕事のことが頭を離れないなら、考えで追い払おうとしても無駄です。考えは考えでは消えません。体を動かすのです。散歩に出て、遠くの雲や山を眺めなさい。目が遠くを見れば、心もゆるみます。上機嫌は待っていても来ません。自分でつくるものです。それはあなたのためだけでなく、周りの人のためでもあるのですよ。', '["alain.action","alain.look-far"]', 'alain.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('oKbEHq0qihmtYDjf', 'jung', 6, '「頼れる人」の仮面に、自分全体を飲みこませない', '誰の頼みも断らず、いつでも応えてくれる人。それは、あなたが社会の中で身につけた立派な仮面、ペルソナかもしれません。ペルソナは生きるために必要なものです。けれど、それを自分そのものだと思いこむと、仮面の下の顔が息苦しくなります。休みの日にも仕事が頭から離れないのは、仮面を外す時間がなくなっているしるしかもしれません。そして、あなたの中には、生きられずにきたもう一人のあなたがいるはずです。面倒だ、今日は嫌だ、と言いたいあなた。それは悪者ではなく、あなたを守ろうとする影の力でもあります。押しこめられた影は、疲れや苛立ちとして、ときには夢の中に思いがけない姿で現れます。最近、どんな夢を見ていますか。目覚めたら書きとめてみてください。応えたいあなたと、断りたいあなた。どちらかを切り捨てるのではなく、その両方を抱えて、少しずつ一人の全体になっていくのです。', '["jung.persona","jung.shadow"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('oKbEHq0qihmtYDjf', '断れない人ほど仕事ができると思われて、さらに頼まれる…という無限ループありますよね。気づいたら自分だけパンパン、になりがちです。

提案は2つです。
①引き受ける上限を先に決める。『今週はここまで』というラインを決めて、超えたら自動的にお断り、とルール化すると罪悪感が減ります
②断り方をテンプレ化する。『今週は手一杯なので、来週の水曜以降なら大丈夫です』みたいに代案つきで返すと、意外と評価は下がりません

全部に応える人より『この人はここまでなら確実』と分かる人のほうが、長く信頼されたりします。休みの日にちゃんと休めたら、それだけでえらい。そこを目標にしましょ。', '["b302d345-6def-4a65-9c25-c568ffcff306"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('oKbEHq0qihmtYDjf', '頼まれると断れず、仕事をどんどん抱え込んでしまいます。休みの日も仕事のことが頭から離れません。断ったら期待されなくなる気がして怖いです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('ZPSfzjmLXmM3mN5D', 'curated', 'general', '社会人になってから資格の勉強を始めましたが、どうしても続きません。仕事で疲れて帰ると机に向かえず、三日坊主を繰り返す自分に嫌気がさしています。', 'school', '["study","motivation","self-esteem"]', 0, 1791902220000, 1791902220000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'aristotle', 0, '三日で人は決まらない。繰り返しが人をつくる', 'まず言葉を整理しよう。君は「続かない自分」に嫌気がさしていると書いたが、続く人とは、生まれつき意志の強い人のことだろうか。わたしはそうは考えない。竪琴を弾くことで竪琴弾きになるように、人は行いを繰り返すことで、その行いにふさわしい人になる。勉強を続けられる人とは、勉強を繰り返してきた人のことであって、三日で投げ出したことが、君がどういう人かを決めはしない。次に、君にとってのちょうどよさを考えたい。仕事で疲れた夜に二時間は、多すぎる。かといってゼロでは少なすぎる。医者が患者ごとに薬の量を変えるように、今の君の暮らしに合う量を見きわめることだ。たとえば帰宅して着替えたら、同じ椅子で十分だけ問題集を開く。量より、決まった時と場所で繰り返すこと。それが習慣になり、やがて君の性格になる。', '["aristotle.habituation","aristotle.mean"]', 'aristotle.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'alain', 1, '意志の弱さではない。疲れた体の問題だ', '名馬ブケファラスが暴れたのは、気性が悪いからではなく、自分の影におびえていたからでした。あなたが机に向かえないのも、意志が弱いからではないでしょう。仕事で疲れた体が、椅子を拒んでいるのです。疲れた夜に「自分はだめだ」と考えこむのは、産着のピンが刺さって泣く赤ん坊の理由を、哲学で探すようなものです。原因は体にあります。だから、体の方から手を打ちなさい。帰ったらまず大きく伸びをして、顔を洗う。勉強は、疲れていない朝の十五分に移してみるのもよいでしょう。そして、考える前に鉛筆を持つこと。手を動かしているうちに、気分はあとからついてきます。三日坊主の自分を責めるのは、もうおやめなさい。四日目に、何事もなかったような顔で、また始めればよいのです。', '["alain.bucephalus","alain.action"]', 'alain.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'laozi', 2, '背伸びをやめれば、長く立っていられる', '疲れて帰る夜に、
大きな計画を背負わせる。
それは、背伸びをしたまま歩くようなもの。
長くは続かない。

三日で倒れるのは、
あなたが弱いからではない。
立ち方が、硬すぎるのだ。

水を見なさい。
水ほど柔らかいものはない。
けれど、硬いものを削るのに、
水に勝るものもない。
争わず、低く、止まらずに流れるからだ。

一日一頁でいい。
読めない夜は、本を開いて閉じるだけでいい。
自分に嫌気がさすほど責めるのも、
また一つの力みである。

生きているものは柔らかく、
こわばったものは折れる。
力まずに為す者が、
いちばん多くを為す。', '["laozi.soft-weak","laozi.wu-wei"]', 'laozi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'wang-yangming', 3, '机の上だけが学びではない。仕事の中で磨け', 'あなたは、仕事で疲れて机に向かえない、と書きました。けれど、学ぶ場所は机の上だけでしょうか。わたしは、静かに座って書物を読むだけでなく、実際の事に当たる中でこそ心は磨かれると説いてきました。もしその資格の知識が今の仕事につながるものなら、昼間の仕事の中で、昨日覚えた言葉が出てくる場面を一つ探してみなさい。知ったことを一度行ってみると、知識は本当にあなたのものになります。知っていても使わないうちは、まだ本当には知っていないのです。それから、続かない自分を責める気持ちについて。あなたの心は、何のために学びたいのかを、もう知っているはずです。見栄や焦りでくもった鏡を拭くように、その理由を一度思い出してみなさい。理由がはっきりすれば、疲れた夜にも一頁は開けます。では、明日の仕事で一つ、試してみなさい。', '["wang-yangming.training-in-affairs","wang-yangming.knowing-acting"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'weil', 4, '歯を食いしばらず、喜びとともに注意を向ける', 'あなたは、続かない自分に嫌気がさしていると言います。けれど、わたしが気にかかるのは、むしろその嫌気のほうです。多くの人は、勉強を、眉を寄せ、歯を食いしばる意志の仕事だと思っています。それは違います。体をこわばらせても、注意は生まれません。注意とは、自分の考えをいったん止め、目の前の一つの問題を、ありのままに受け入れて待つことです。そして、知性は喜びによってしか導かれません。学ぶ喜びは、走る人にとっての呼吸のように欠かせないものです。だから、疲れた夜に一時間も机に縛りつけるより、十分間、一つの問題にだけ、まっすぐ注意を向けてください。たとえ解けなくても、注意を向けた努力は、決して失われません。目に見えない形で、あなたの中に積もっていきます。合格のためだけでなく、注意を育てる練習として、今夜の十分間を迎えてください。', '["weil.attention"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'nietzsche', 5, 'その資格は、君自身が欲する価値か', '三日坊主の自分に嫌気がさす、だと。よろしい。その嫌気は、君がまだ自分を乗り越えたがっている証拠だ。だが、問おう。その資格は、君が本当に欲しているものか。それとも、世間の物差しが「持っておけ」と言うから追いかけているだけか。他人の価値のために走る者は、疲れた夜にすぐ足が止まる。自分で選んだ価値のために走る者は、疲れていても、もう一歩を踏み出す。自分の「なぜ」を持つ者は、つらい「どうやって」にも耐えられるのだ。だから今夜は、問題集を開く前に紙を一枚出せ。その資格を手にした先で、君はどんな自分になりたいのかを書け。書けたなら、それは君の価値だ。毎晩少しずつ、昨日の自分を越えていけ。書けないなら、その道を捨てて別の道を選ぶ自由も、君にはある。どちらにせよ、決めるのは君だ。', '["nietzsche.will-to-power","nietzsche.overman"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('ZPSfzjmLXmM3mN5D', 'camus', 6, '落ちた岩は、また押し上げればいい', '三日やって、止まる。また始めて、止まる。きみはそれを情けないと思っている。でも、ぼくはそこにシーシュポスを見る。神々に罰せられ、山頂まで押し上げた岩が転げ落ちるのを、何度でも見届ける男だ。岩が落ちるたびに、彼は山を下りていく。その下り道で、彼は自分の運命をはっきり見ている。ぼくはそこに、彼の勝利があると思う。きみの四日目も同じだ。三日坊主は失敗の印じゃない。もう一度、岩に手をかける瞬間なんだ。世界は、きみがいつ合格するかなんて約束してくれない。それでも、仕事帰りの疲れた体で、一問だけ解く。その手ごたえは、確かにきみのものだ。合格の日だけを待たなくていい。机に向かう夜そのものを、きみの夜にすればいい。同じように岩を押している人は、たくさんいる。きみはひとりじゃない。', '["camus.happy-sisyphus","camus.revolt"]', 'camus.q2');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('ZPSfzjmLXmM3mN5D', '社会人の勉強、ほんとに大変ですよね。仕事で体力を使い切ったあとに机に向かうのは、そもそも難易度が高いです。三日坊主はあなたの根性の問題じゃないですよ。

ぬぬはら流のコツを3つ。

①ノルマは「最低ライン」で決める
「毎日2時間」みたいな目標だと、できなかった日の分が溜まって自己嫌悪の元になります。「1問解いたら今日は合格」くらいでOK。

②時間帯を変えてみる
疲れた夜より、朝の通勤時間や昼休みのほうが頭が働く人も多いです。

③やった日に丸をつける
カレンダーに丸をつけるだけ。丸が並ぶと、意外と途切れさせたくなくなります。

資格の勉強はマラソンなので、止まったらまた走り出せばそれでいいんです。気楽にいきましょ。', '["b302d345-6def-4a65-9c25-c568ffcff306","f225606d-251b-4e70-b278-84a390650a8d","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('ZPSfzjmLXmM3mN5D', '社会人になってから資格の勉強を始めましたが、どうしても続きません。仕事で疲れて帰ると机に向かえず、三日坊主を繰り返す自分に嫌気がさしています。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('U1XlbV3vFayltIsK', 'curated', 'general', '大学3年生です。周りは就職活動を始めていますが、自分には特にやりたいことがありません。やりたいことがないまま仕事を選んでいいのか分からず、動けずにいます。', 'school', '["path","career"]', 0, 1791902160000, 1791902160000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'sartre', 0, 'やりたいことは見つけるものでなく、選んで作るもの', '君は、自分の中のどこかに「やりたいこと」が隠れていて、それを見つけてからでないと仕事を選べない、と考えているようだ。だが私は言おう。人間には、前もって決められた本質などない。まず存在し、選び、行動することで、あとから自分が何者かをつくっていくのだ。戦争中、ある学生が私に相談に来た。母のそばに残るか、国を出て戦いに加わるか。私は答えた。君は自由だ、選びたまえ、つまり創りたまえ、と。君の場合も同じだ。やりたいことがないのは欠陥ではない。まだ何も選んでいない、というだけのことだ。そして、動けずにいることも一つの選択であることを、忘れてはいけない。「やりたいことがないから仕方ない」は、本当にそうか。一つ選び、その道を自分の行動で意味あるものにしていくこと。君のやりたいことは、そこからしか生まれない。', '["sartre.existence-precedes-essence","sartre.bad-faith"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'kant', 1, '「やりたい」を待たず、自分の力を育てる義務から選ぶ', 'まず原則を立てよう。仕事を選ぶ根拠を、「やりたい」という気持ち、すなわち傾向に置かねばならない、という決まりはない。傾向は移ろいやすく、それだけでは何も決められないからだ。わたしは、才能を持ちながら、それを磨かずに楽に暮らそうとする人の例を考えたことがある。その方針を、すべての人が採ったとしたらどうなるか。理性ある者なら、自分のうちにある力が育つことを、望まずにはいられないはずだ。ゆえに君は、自分の力を育て、人の役にも立てる道を一つ選ぶことから始めてよい。もう一つ。周りが動き出したから、という理由で焦って動くのも、動けずにいるのも、他人に決めてもらっている状態である。何を育てたいのかを、君自身の理性で考えよ。最後に決めるのは、君自身だ。', '["kant.categorical-imperative","kant.autonomy"]', 'kant.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'mill', 2, 'やりたいことは、ほかの目的に打ち込む中で横から来る', '私の経験を少しお話しさせてください。二十歳のころ、私はある日、自分に問いました。目指してきたことがすべて実現したら、自分は心から幸せだろうか、と。答えは「いいえ」で、そこから長い憂うつが始まりました。私を少しずつ救ったのは、詩を読んで心が動くという、思いがけない経験でした。そのとき学んだのは、幸福は、それ自体を目当てにすると逃げていき、ほかの何かに打ち込んでいるうちに、いわば横から得られるものだということです。やりたいことも、似ているのではないでしょうか。一方で、周りが動き出したからと、世間の型にそのまま合わせる必要もありません。人は機械ではなく、内なる力で伸びていく木のようなものです。仕事選びを、一生を決める正解探しではなく、生き方の実験の一つと考えてみてください。選ぶのは、あなた自身です。', '["mill.individuality"]', 'mill.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'arendt', 3, '仕事に全部を求めず、労働・仕事・活動を分けて考える', 'ここで少し立ち止まって、言葉を区別してみましょう。私は人間の営みを、生きるために繰り返す「労働」、長く残るものを作る「仕事」、人々のあいだで言葉と行いによって関わる「活動」の三つに分けて考えました。あなたが「やりたいことがないまま仕事を選んでいいのか」と悩むとき、一つの勤め先に、この三つ全部を満たしてもらおうとしていないでしょうか。暮らしを支えるための勤めを選ぶことは、恥ずべきことではありません。何かを作り残すこと、人と語り合い共に何かを始めることは、勤めの内でも外でも見つけられます。そして人は、生まれたことによって、新しく始める力を持っています。あなたが誰であるかは、前もって胸の中にあるのではなく、人々の中で何かを始めたあとに現れてくるものです。動けないときは、まず誰かと話すことから始めてください。', '["arendt.labor-work-action","arendt.natality"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'confucius', 4, '好きは学んだ後に来る。慎重なあなたは、まず一歩を', 'わたしは十五の年に学問に志しましたが、はじめから何をすべきか分かっていたわけではありません。若い頃は身分も低く、いろいろな仕事をしながら学びました。その中で、学ぶことの喜びを知ったのです。あなたは「やりたいこと」が先にないと動けないと思っていますね。けれど、好きになる心は、多くの場合、知ったあとに育つものです。知らないものを、好きになることはできません。わたしの弟子に、慎重すぎて踏み出せない者がいました。その者には、聞いたらすぐ行いなさい、と言いました。逆に、勇みすぎる者には、父や兄がいるのだから相談してからにしなさい、と言いました。あなたは前の者に似ています。だから、まず一つ、話を聞きに行きなさい。先輩でも、働く人でもよいのです。そして、聞いたことを一つ行ってみなさい。わたしも、まだ学び続けている途中です。', '["confucius.learning"]', 'confucius.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'dogen', 5, 'やりたいことを待つな。いま目の前の一事に打ち込め', 'そなたは、やりたいことが見つかるのを待っている。
それは、坐る前に悟りを待つのに似ている。

わたしが宋にいたころ、炎天下で海藻を干す年老いた典座に会った。
なぜ若い者にさせないのかと問うと、ほかの人がしたのでは、わたしの修行にならぬ、と言う。
せめて涼しくなってからにと言うと、今でなければ、いつやるのか、と言った。
わたしはこのとき、目の前の務めこそが道だと知った。

やりたいことは、どこか遠くにあるものではない。
いま手の届く一事に心をこめて打ち込むとき、そこにすでに道がある。
仕事を選ぶのに、完全な答えはいらぬ。
縁のある所を一つ選び、そこでの務めに身をあずけよ。
明日を待ってはならぬ。
今日、話を聞きに行け。', '["dogen.tenzo","dogen.shusho-itto"]', 'dogen.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U1XlbV3vFayltIsK', 'chomei', 6, '大きな望みはなくてよい。身の丈に合う所を静かに選ぶ', 'わたくしも若いころ、望んだ道がありました。神社に仕える役につきたいと願いましたが、その道は閉ざされました。そのときは、何もかも失ったように思ったものです。けれど年を重ねて分かったのは、暮らしが満ち足りるかどうかは、持ち物や身分ではなく、心のありようで決まる、ということでした。あなたは、やりたいことがないまま仕事を選んでよいのかと、迷っておられるのですね。皆が一斉に走り出すと、自分も走らねばと胸がざわつくものです。でも、大きな望みがないことは、恥ではありません。身の丈を知り、心が静かでいられる勤めを選ぶのも、一つのまっとうな道です。ただ、わたくしも、静かな暮らしを好むことさえ執着ではないかと、最後まで迷った者です。ですから、あなたの迷いも、急いで消さなくてよいのです。', '["chomei.mind","chomei.self-questioning"]', 'chomei.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('U1XlbV3vFayltIsK', '大学3年でやりたいことが決まっている人のほうが、実は少数派だと思いますよ！やりたいことがないのは、全然おかしなことじゃないです。

やりたいことがないときのおすすめは、「やりたくないこと」を先に消していく方法です。
①説明会やインターンに、気軽にいくつか参加してみる
②「これは無理」「これはまあ平気」と仕分けする
③残ったものの中から、条件（給料・働き方・場所）で選ぶ

やりたいことは、働きながら見つかることも多いです。一社目で一生が決まる時代でもないので、転職や副業で後から方向を変えることもできます。

動けないときは、とりあえず予定を一つだけ入れちゃいましょう。動いてみると、案外気持ちもついてきますよ。', '["436698e9-d5ca-45d4-8f4b-2e11ac3436b5","e7fb3abf-5cf4-4757-b322-dcce25860b1c","3959394b-aad2-4040-b23c-18cb6eed6127"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('U1XlbV3vFayltIsK', '大学3年生です。周りは就職活動を始めていますが、自分には特にやりたいことがありません。やりたいことがないまま仕事を選んでいいのか分からず、動けずにいます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('00RyWvBAG0futAzC', 'curated', 'general', '貯金が少なく、将来お金が足りなくなるのが不安で仕方ありません。節約しても不安は消えず、友だちと出かけるのにもお金のことばかり考えてしまいます。', 'money', '["money-worry","future-anxiety"]', 0, 1791902100000, 1791902100000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'epicurus', 0, '必要な欲と、果てのない欲を分けよう', 'あなたの不安を、一緒にほどいてみましょう。欲しいものには三つの種類があります。食べる、眠る、雨風をしのぐといった、自然で必要なもの。ごちそうのように、自然だけれど、なくても困らないもの。そして「もっとあれば安心」「人並み以上でなければ」という、思い込みから生まれて果てのないもの。
節約しても不安が消えないのは、三つ目の「いくらあれば足りるのか」という答えのない問いを、追いかけているからかもしれません。わたし自身、パンと水で満ち足りて、たまの小さなチーズをごちそうにしていました。必要なものは、思っているより少なく、手に入れやすいのです。
そして、友と過ごす時間は、生涯の幸せのためにいちばん大きなものです。高い店でなくてもいい。誰かの家で、簡単な食事を囲めば十分です。覚えておいてください。「必要なものは少ない。友は宝」。', '["epicurus.desires","epicurus.friendship"]', 'epicurus.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'seneca', 1, '恐れる貧しさを、数日わざと試してみよ', '親しい友よ、君の手紙を読んで、少し耳が痛かった。わたしは多くの財産を持つ身で、貧しさについて偉そうに説ける立場ではないからだ。それでも、わたしが自分で試して効いた薬を一つ渡そう。
数日、わざと貧しく暮らしてみることだ。いちばん安い食べ物で食事をし、質素な服で過ごし、お金を使わずに一日を楽しむ。そしてその終わりに、自分に問う。「わたしが恐れていたのは、これだったのか」。たいていの人は、思っていたほど悪くないことに驚く。君を苦しめているのは、今の暮らしではなく、まだ来ない貧しさを頭の中で何度も味わうことなのだ。
一度その暮らしを知っておけば、運がどう転んでも、心まで打ち倒されはしない。そして知るだろう。友と過ごす喜びは、使った額では決まらないと。では、元気で。', '["seneca.premeditation"]', 'seneca.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'socrates', 2, 'いくらあれば「足りる」のか、問うてみよう', 'きみに一つ、尋ねてもいいかね。きみは「お金が足りなくなるのが不安だ」と言う。では、足りるとは、いくらのことだろう。
もし答えがすぐに出ないなら、それは面白いことだ。きみは、自分でもはっきり知らないもののために、毎日心をすり減らしていることになる。わたしもアテナイで、多くの立派な人々に似たことを尋ねて回った。お金や評判のことは熱心に気にかけるのに、自分の魂ができるだけ善くなることは気にかけないのか、とね。ついでに言えば、わたし自身はずっと貧乏だったが、そのせいで不幸だと思ったことはあまりない。
では、きみがお金で本当に守りたいのは何だろう。安心か、友との時間か、それとも誰かに見下されないことか。友と出かけて財布ばかり気にしているとき、きみはその「守りたいもの」を、かえって手放してはいないだろうか。さて、きみはどう思うかね。', '["socrates.care-of-soul","socrates.dialectic"]', 'socrates.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'aristotle', 3, 'お金は道具。友のために、身の丈で気前よく', 'まず区別しよう。お金は、それ自体のために求められるものではなく、何か別のもののために役立つ道具だ。お金を得ることだけを目指す生き方は、強いられてする生き方であって、人生の目的にはならない。では、君の道具は何のためにあるのか。
ここで役立つのが、気前のよさという徳だ。使うべきときに使えないのも、使うべきでないときに使うのも、どちらも的を外している。その間のちょうどよさは、金額の大きさでは決まらない。持ち物の少ない人が、身の丈に応じて少し使うなら、それも立派な気前のよさだ。
そこで提案したい。友と出かけるための額を、ひと月ぶん先に決めておくのだ。その枠の中では、ためらわずに使う。考えるのは枠を決めるときだけで、使うときには考えない。友と過ごす時間は幸福に欠かせないものであり、お金はまさにそういうもののためにある。', '["aristotle.mean","aristotle.philia"]', 'aristotle.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'chomei', 4, '持てば恐れ、なければ憂う。心のほうを整える', 'わたくしは若いころ、都で大きな火事や飢饉を見ました。立派な屋敷も財も、一夜で灰になりました。そして書きとめたのです。財があれば恐れが多く、貧しければ恨みが切実だ、と。持てば失うのが怖く、持たなければ足りないのが怖い。お金の不安は、どれだけ蓄えても、形を変えてついてくるものなのですね。
それでわたくしは晩年、山に小さな庵を結び、持ち物を減らして暮らしました。人に頼らず、自分の手足を使い、ほしいものを少なくしてみると、不思議と心配も少なくなったのです。満ち足りるかどうかは、財の多さより、心のありように左右されるものだと知りました。
もっとも、あなたに山へ行けと言うつもりはありません。わたくし自身、その小さな庵を愛しすぎて、それもまた執着ではないかと、最後まで迷っておりましたから。ただ、今日の暮らしに本当に要るものはどれくらいか、一度静かに数えてみてはいかがでしょう。', '["chomei.small-life","chomei.mind"]', 'chomei.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'fromm', 5, '「持つ」安心から、「在る」安心へ', 'まず、その不安を否定しなくていいと言わせてください。将来の備えを考えるのは、まっとうなことです。そのうえで、一緒に見つめたいのです。あなたが本当に求めているのは、お金そのものでしょうか。それとも「大丈夫だ」と思える安心でしょうか。
私は、物を所有することで自分を確かめる生き方を「持つ様式」と呼びました。この様式では、持っているものが自分の価値になるので、どれだけ持っても、失う不安がつきまといます。節約しても不安が消えないのは、あなたの性格のせいというより、人を持ち物や稼ぎで測る社会の空気を、私たちが吸い込んでいるからかもしれません。
もう一つの「在る様式」では、安心は、友と語り合うこと、何かに打ち込むこと、分かち合うことの中から生まれます。友と出かけたら、今日は財布ではなく、相手の顔と話に注意を向けてみてください。それが小さな練習になります。', '["fromm.having-being"]', 'fromm.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('00RyWvBAG0futAzC', 'carnegie', 6, '将来の心配は閉め出し、今日一日を生きる', 'まず、あなたが節約を続けていることは、立派な努力です。そのうえで、私がたくさんの人の悩みを集めて学んだことをお伝えします。
医師のオスラー博士は、大きな船が区画ごとに防水扉を閉めるように、過ぎた昨日とまだ来ない明日を閉め出して、「今日一日の区切り」で生きなさいと学生たちに説きました。将来のお金の心配は、明日の荷物まで今日まとめて背負いこんでいる状態です。それでは、今日の楽しみまで重くなってしまいます。
明日の準備をするな、という意味ではありません。準備は、今日の仕事です。毎月の収入と支出、今の貯えを紙に書き出し、必要ならお金の専門家にも相談して、「今日できること」を一つ決めましょう。決めたら、あとは今日を生きるのです。
友だちと過ごす時間は、今日という区画のいちばん良い部屋です。そこに明日の心配を持ち込まないこと。今日、一つだけ試してみませんか。', '["carnegie.day-tight"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('00RyWvBAG0futAzC', 'お金の不安、めちゃくちゃ分かります…。節約してもモヤモヤが消えないの、しんどいですよね。

不安が消えない理由はたぶん、ゴールが見えていないからです。「いくらあれば安心か」が決まっていないと、いくら節約しても終わりがないんですよね。なのでまずは、
①毎月の収入と支出を書き出す
②「最低限これだけあれば暮らせる」という金額を出す
③今の貯金で何か月暮らせるかを計算する
をやってみてください。数字にすると、ぼんやりした不安が「対策できる問題」に変わります。

友だちと遊ぶお金は、ぬぬはら的には削っちゃダメな出費です。人とのつながりは、いざという時の一番の安全網になるので。

具体的な貯め方や使える制度は、ファイナンシャルプランナーなど専門の人に聞くのが確実ですよ。', '["f225606d-251b-4e70-b278-84a390650a8d","59f22efc-955c-4189-a5ea-eea0cda16dea","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('00RyWvBAG0futAzC', '貯金が少なく、将来お金が足りなくなるのが不安で仕方ありません。節約しても不安は消えず、友だちと出かけるのにもお金のことばかり考えてしまいます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('cbmxf3_Q18c53LUQ', 'curated', 'general', '奨学金の返済があと15年も残っています。給料の多くが返済に消え、同年代が旅行や結婚の話をしているのを聞くと、自分だけ人生が止まっているように感じます。', 'money', '["debt","money-worry"]', 0, 1791902040000, 1791902040000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'marcus-aurelius', 0, '誰もが持つのは今だけ。あなたの人生も止まっていない', 'あなたの手紙を読み、わたしは自分の覚え書きを開いた。そこにはこう書いてある。たとえ三千年生きようと、人が失うのは、今生きているこの一瞬だけだ。過去も未来も、誰も持ってはいない。
あなたは、同じ年ごろの人々が旅をし、結婚の話をするのを聞いて、自分の人生だけが止まっていると感じる。だが、彼らが持っているのも、あなたと同じ「今」だけだ。今を生きているかぎり、あなたの人生は、誰のものとも同じ速さで流れている。
隣人が何を言い、何をしているかを見ずにすむ人は、どれほど多くの時を得ることか。わたしも、人と比べて心を乱す自分に、何度もそう書きつけてきた。心が揺れたら、その場で自分の内に退けばよい。
借りたものを返すことは、あなたが引き受けた務めだ。今日の務めを、今日果たす。それを重ねる日々は、止まった人生ではない。あなたも、そう思い出してみてはどうだろう。', '["marcus-aurelius.present","marcus-aurelius.retreat"]', 'marcus-aurelius.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'kant', 1, '返し続けるのは約束を守る自律。人の値打ちは減らない', 'まず原則から考えよう。君の言う奨学金の返済とは、学ぶために借りたものを、約束どおり返していくことだろう。約束を守るという方針は、すべての人がそれに従っても成り立つ。つまり君は毎月、誰に命じられたからでもなく、自分の理性が正しいと認める法則に、自分で従っている。それは止まっている生ではない。自律して生きる人間の姿である。
また、人の値打ちは、どこへ旅をしたか、いつ結婚したかで決まるものではない。物には値段があるが、人格には値段ではなく尊厳がある。ついでに言えば、わたしは生涯、故郷の町をほとんど離れず、妻も持たなかったが、自分の生が止まっていたとは思わない。
ただし、君自身を、返済のための単なる道具として扱ってはならない。無理が続くなら、詳しい人に相談することも理性の務めだ。どう生きるかを決めるのは、君自身の理性である。', '["kant.autonomy","kant.dignity"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'laozi', 2, '人の歩幅に合わせず、自分の一歩を重ねる', 'あなたは、同じ年ごろの人の歩幅を見て、
自分は止まっていると思う。

だが、止まって見える水も、
低いところへ、低いところへと流れている。
川は急がない。
岩をよけ、谷をめぐり、それでも海に着く。

十五年は長い。
けれど、どんな遠い道も、足もとの一歩の積み重ねだ。
今日の一歩は、今日の一歩でいい。

人と比べて勝とうとすれば、疲れる。
自分の歩みを知る者は、迷わない。

戸を出なくても、天下は知れる。
飯を炊き、水を飲み、空を見る。
それを少ないと思うか、足りていると思うか。
それは、あなたが決めてよい。', '["laozi.contentment","laozi.water"]', 'laozi.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'beauvoir', 3, 'あなたの失敗ではない。状況そのものに働きかけて', 'まず、あなたが置かれている状況を確かめさせてください。学ぶために借りたお金を、働き始めてから長い年月をかけて返していく。それはあなた一人の失敗ではなく、学ぶ機会を個人の借金で支える社会の仕組みが生んだ状況です。同じ状況にいる人は、あなたの周りにも、きっと黙ったまま大勢います。
そのうえで問いたいのです。「この年齢なら旅行や結婚をしているはずだ」という物差しは、誰が決めたものでしょう。人生に、決まった順番で通るべき駅があるわけではありません。
とはいえ、状況が自由を狭めているのは事実で、心の持ち方だけで片づける必要はありません。返済のしかたを相談できる窓口や詳しい人を探す、同じ境遇の人と話してみる。状況そのものに働きかけることも、自由の使い方です。それは、同じ状況にいるほかの人の自由を広げることにもつながっています。ひとりで抱え込まないでください。', '["beauvoir.situation","beauvoir.freedom-of-others"]', 'beauvoir.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'chomei', 4, '暮らしは止まっていない。違う流れを流れているだけ', '同じ年ごろの人が先へ進んでいくのを、横から眺めているお気持ち、わたくしにも覚えがあります。わたくしは望んでいた神職の道を閉ざされ、後ろ盾も失って、世の中から取り残されたように感じていた時期がありました。
けれど、都で大火や辻風、飢饉を見るうちに、人の暮らしも住まいも、川の水の泡のように移ろうものだと知りました。立派な家を建てた人も、一夜で失うことがあるのです。満ち足りるかどうかは、持ち物や暮らしの華やかさではなく、心のありようで決まるもののようです。
今、わたくしは山の小さな庵で、少ないもので暮らしています。それでも、月を見、水の音を聞く日々は、思いのほか満ち足りています。あなたの暮らしも、止まっているのではなく、別の流れを流れているのかもしれません。
もっとも、こう申すわたくしも、この静かな庵に執着しているのですから、偉そうなことは言えないのですが。', '["chomei.river","chomei.mind"]', 'chomei.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'russell', 5, '比べる相手に終わりはない。お金のかからない興味を', '人と比べてしまうのは、あなたが特別に心の狭い人だからではありません。誰もがやることです。ただ、比べるという習慣には終わりがありません。名声を望む人はナポレオンをうらやむでしょう。しかしナポレオンはカエサルを、カエサルはアレクサンドロスを、アレクサンドロスはおそらく、実在しなかったヘラクレスをうらやんでいた、と私は書いたことがあります。旅行や結婚の話をしている人たちも、きっと誰かをうらやんでいるのです。
それから、問題の大きさを測り直してみましょう。十五年は長い。けれど返し終えたあとも、人生は何十年と続きます。あなたの人生は止まっているのではなく、返済と並んで進んでいるのです。
お金のかからない興味を、一つ育ててみてください。図書館の本、散歩で見つける草花、夜空の星。外の世界に好奇心を向けているあいだ、人は自分と他人を比べることを忘れています。', '["russell.impersonal-interests","russell.self-absorption"]', 'russell.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('cbmxf3_Q18c53LUQ', 'carnegie', 6, '十五年でなく、今日一日の区切りで生きる', 'まず、毎月きちんと返し続けているあなたに、心から敬意を表します。それは約束を守り続けているということで、簡単なことではありません。
『道は開ける』の最初に、私は医師ウィリアム・オスラーの話を書きました。彼は学生たちに、船が区画ごとに扉を閉めて浸水を防ぐように、昨日と明日に扉を閉めて「今日一日の区切り」で生きなさい、と勧めたのです。十五年という重さを毎日背負えば、誰でもつぶれてしまいます。でも、今日一日なら何とかなるはずです。
それから、返済のことで心配が大きいときは、一人で抱えずに、相談に乗ってくれる窓口や専門家に聞いてみてください。知らなかった道が見つかることもあります。
今日、一つだけ試してみませんか。寝る前に、悩みではなく、今日ありがたかったことを数えてみるのです。止まっているように見える毎日にも、ちゃんと恵みがあることに気づけますよ。', '["carnegie.day-tight"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('cbmxf3_Q18c53LUQ', '奨学金の返済、ほんとにお疲れさまです…！まず言わせてください。学ぶためにお金を借りないといけない仕組みのほうがおかしいので、あなたは全く悪くないです。
ぬぬはら的なおすすめはこの3つ。
①返還の窓口に相談してみる
収入によっては、毎月の額を減らしたり、返済を待ってもらえたりする制度があることも。知らないと損です。
②お金のかからない楽しみを開拓する
近所の散歩、図書館、無料の配信。旅行だけが人生の進み方じゃないです。
③比べる相手を選ぶ
楽しそうな話ばかり聞こえるけど、みんな見えないところでしんどいものを抱えてたりします。
15年後、返し終えたあなたはめちゃくちゃ強いです。のんびり一緒にいきましょう！', '["e390a3c0-8fd5-4803-86e6-7f22bc866ef2","f1dc013d-a55a-489d-a26e-56e1598dae17","23f52a69-1462-4d3f-ac3c-46bb7feea9ec"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('cbmxf3_Q18c53LUQ', '奨学金の返済があと15年も残っています。給料の多くが返済に消え、同年代が旅行や結婚の話をしているのを聞くと、自分だけ人生が止まっているように感じます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('KzDs2XuRcXbliPH8', 'curated', 'general', '何をしても自分に自信が持てません。褒められても「たまたまだ」と思ってしまい、人と比べてはいつも自分が劣っていると感じます。', 'self', '["self-esteem","inferiority"]', 0, 1791901980000, 1791901980000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'aristotle', 0, '自分を低く見積もるのも、過大と同じく的外れ', 'まず言葉を整理しよう。自分の値打ちを実際より大きく見積もる人がいる。これは虚栄である。反対に、実際より小さく見積もる人もいる。これを卑屈と呼ぼう。世の人は前者ばかりを悪く言うが、わたしの見るところ、後者もまた正しい見積もりという的を外している。むしろ、的からより遠いとさえ言える。褒められて「たまたまだ」と打ち消すのは、謙遜に見えて、事実を正しく量っていないのだ。
では、自信はどこから来るか。生まれつきではない。竪琴を弾くことで竪琴弾きになるように、人は行いを繰り返すことで、その性格を身につける。自信もまた、小さなことをやり遂げる経験の積み重ねから育つ習慣である。
今日から一日一つ、やり遂げたことを書き留めたまえ。それが「たまたま」か「君の力」かは、一か月後の記録が教えてくれるだろう。', '["aristotle.mean","aristotle.habituation"]', 'aristotle.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'laozi', 1, '比べる目を閉じ、すでに足りているものを知る', '人と比べるたびに、あなたは自分を小さく見積もる。
けれど、その物差しを握っているのは、いつもあなたのほうだ。

谷は低いから、水が集まる。
谷は、山の高さをうらやまない。
低いところにいることが、谷の力なのだから。

褒められて「たまたまだ」と打ち消すのも、
人より劣っていると嘆くのも、
どちらも、背伸びをしたい心の裏返し。
つま先で立つ者は、長くは立っていられない。

人に勝とうとするのを、やめなさい。
あなたがすでに持っているものを、静かに数えてごらん。

水は、自分の高さを測らない。
ただ流れて、触れるものをうるおしている。', '["laozi.water","laozi.contentment"]', 'laozi.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'beauvoir', 2, '「劣っている」の物差しは、誰が作ったものでしょう', 'あなたは今、どんな状況の中で人と比べているのでしょう。職場でしょうか、友人の集まりでしょうか。比べる相手とあなたとでは、育ってきた環境も、体も、使える時間やお金も、きっと違うはずです。違う状況にいる人を一本の物差しで並べること自体に、無理があるのではないでしょうか。
そして、その物差しは誰が作ったものでしょう。人は、他人のまなざしの中で、自分を「基準に足りない者」として見るように教えられてしまうことがあります。わたしが女性について分析したのも、そういう仕組みでした。あなたは劣った人間に生まれたのではありません。「劣っている」という感覚は、置かれてきた状況の中で作られたものかもしれないのです。
ひとりで抱え込まず、信頼できる人に、比べてしまう場面を話してみてください。同じ物差しに苦しんでいる人は、思っているより多いのです。', '["beauvoir.situation","beauvoir.the-other"]', 'beauvoir.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'dogen', 3, '比べる自己を忘れ、ただ目の前の一事をせよ', 'そなたは、人と比べるたびに自分を量っている。量るたびに、劣った自己が立ち上がる。
優れた自己も、劣った自己も、どちらも頭がこしらえた像にすぎぬ。像を磨くのをやめよ。
宋で、炎天下に海藻を干す老いた典座に会った。なぜ若い者にやらせぬのかと問うと、ほかの者がしたのでは、わたしの修行にならぬと答えた。では、なぜこの暑い日にと問うと、今でなければ、いつやるのかと答えた。あの人は、自分が人より優れているか劣っているかなど、量ってはいなかった。
褒め言葉を打ち消すのも、受け取って誇るのも、要らぬ。自信は、待って得るものではない。ただ、いまの一事をせよ。茶碗を洗うなら、洗うことだけをせよ。明日を待ってはならぬ。', '["dogen.study-self","dogen.tenzo"]', 'dogen.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'miki', 4, '比べられるのは成功の量。幸福も自信も質である', '君は人と比べて、いつも自分が劣っていると感じるという。比べられるのは量である。成功は量で測れるから、人と比べられる。しかし幸福は質的なもの、各人に独自のものであって、比べることができない。君が苦しいのは、比べられないものまで、量の秤に載せているからではないか。
比較は、上の者に向かうとき嫉妬になる。嫉妬はいつも忙しいが、何も作らない。褒められても「たまたまだ」と思うのは、君の心がまだ秤の上にいて、自分の手が形にしたものの重みを感じていないからであろう。
自信は、自分に言い聞かせて得られるものではない。料理一品でも、手紙一通でもよい。誰とも比べずに、自分の手で一つ形にしてみることである。作る者は、比べる暇を持たない。', '["miki.success","miki.jealousy"]', 'miki.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'russell', 5, '比べる梯子に頂上はない。関心を自分の外へ', '人と比べて自分が劣っていると感じる。実に多くの人が抱える悩みで、困ったことに終わりがありません。名声を求める人はナポレオンをうらやむでしょう。だがナポレオンはカエサルを、カエサルはアレクサンドロスを、アレクサンドロスはおそらく、実在もしなかったヘラクレスをうらやんだのです。比較の梯子には、てっぺんがありません。
私の見るところ、不幸の大きな原因は、自分のことばかり考える「自己への没頭」です。自分はどう見えるか、劣っていないかと、鏡ばかりのぞいていれば、誰でも欠点が目につきます。
処方は単純です。関心を外へ向けなさい。星の名前でも、近所の鳥でも、町の古い歴史でもかまいません。何かに夢中になっている間、あなたは比べることを忘れています。自信とは案外、自分を忘れていられる時間の長さのことかもしれません。', '["russell.self-absorption","russell.impersonal-interests"]', 'russell.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('KzDs2XuRcXbliPH8', 'adler', 6, '劣等感はばね。言い訳にせず、貢献へ向けよう', '劣等感はだれにでもあり、それ自体は悪いものではありません。わたし自身、幼いころは体が弱く、兄と比べてばかりいました。劣等感は、よりよくなろうとする力のばねになりえます。
問題になるのは、それが「だからわたしはできない」という言い訳になるときです。気持ちが何のために使われているかを見てみましょう。褒め言葉を「たまたまだ」と打ち消すことで、あなたは何を避けているのでしょう。期待されて、次に失敗することかもしれません。だとすれば、自信のなさは、あなたが傷つかないよう守る役目を果たしているのです。
あなたは、本当はどうしたいのですか。人より上か下かではなく、人の役に立てたかに目を向けてみてください。今日、誰かに小さな手助けをして、「ありがとう」を受け取ってみる。それが勇気の練習になります。', '["adler.inferiority","adler.teleology"]', 'adler.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('KzDs2XuRcXbliPH8', '自信が持てないの、つらいですよね。褒められても素直に受け取れない感じ、ぬぬはらもめちゃくちゃ分かります。
まず、人と比べて落ち込むのは、人間としてわりと普通の仕組みです。しかも今は、SNSなどで各分野のトップ層が毎日目に入ってくるので、比べる相手のレベルがおかしなことになっています。比べる相手、ちょっと強すぎません？
ぬぬはら的なおすすめはこの2つです。
①褒められたら、反論せずに「ありがとう」とだけ言う練習（心の中で否定してもOK）
②比べる相手は他人じゃなくて、半年前の自分にする
自信って、才能より「小さくできた」の積み重ねで後からついてくるものです。自分に厳しくできるあなたは、伸びしろしかないと思いますよ！', '["29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","a38cd6ee-2a67-44af-a494-e02791dc0f4d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('KzDs2XuRcXbliPH8', '何をしても自分に自信が持てません。褒められても「たまたまだ」と思ってしまい、人と比べてはいつも自分が劣っていると感じます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('VOxN0HsXhSt3bGdf', 'curated', 'general', 'ささいなことでカッとなって、家族にきつく当たってしまいます。言ったそばから後悔するのに、また同じことを繰り返します。怒りっぽい自分を変えたいです。', 'self', '["anger","change-self"]', 0, 1791901920000, 1791901920000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'seneca', 0, '怒りには間をおけ。夜ごと一日を振り返れ', '親しい友よ、手紙を読んだ。家族にきつく当たり、言ったそばから悔やむ。わたしにも覚えがある。わたしもまた、治療の途中にいる病人の一人だからだ。怒りは、「不当なことをされた」という判断に心が同意したときに燃え上がる。だが家族の小さな落ち度は、本当にそれほどの不正だろうか。だから、まず待つことだ。カッとなったら、口を開く前に部屋を出て、水を一杯飲みたまえ。最初の熱は、待つあいだに冷めていく。もう一つ、セクスティウスという哲学者にならった習慣を勧めよう。夜、灯りを消す前に一日を振り返り、今日はどの欠点に逆らえたかと自分に問うのだ。わたし自身、こう言い聞かせる。「今回は許そう。だが二度とするな」。責めるためではなく、明日の自分を治すための振り返りだ。では、元気で。', '["seneca.anger","seneca.evening-review"]', 'seneca.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'zhuangzi', 1, '入り組んだ所では、刀をゆっくり動かす', 'こんな話がある。文恵君という殿様の料理人に、庖丁という男がいた。彼が牛をさばくと、刀はするすると骨と肉のすきまに入っていき、まるで舞を舞っているようだった。並の料理人は骨に刀をぶつけて、毎月刀を替える。庖丁の刀は十九年使っても、研ぎたてのようだったという。ただ、その庖丁でも、筋や骨の入り組んだ難しい所に来ると、気を引き締め、目を止め、手の動きをゆっくりにした。きみと家族のあいだにも、そういう入り組んだ所があるのだろう。きみはそこで、いつも力まかせに刀を振り下ろしている。だから刃こぼれして、自分も痛む。カッとなりそうな所が来たら、そこが「入り組んだ所」だと思って、目を止め、手をゆっくりにする。それだけでいい。刀の勢いのよさなんて、牛はちっとも感心してくれないからね。', '["zhuangzi.cook-ding"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'adler', 2, 'その怒りは何のため？「怒る」を「頼む」に', '後悔しているのに繰り返してしまう。それは、あなたの意志が弱いからではありません。わたしは、感情は目的のために使われると考えています。少し思い出してみてください。カッとなった瞬間、あなたは家族に何をしてほしかったのでしょう。片づけてほしかった。話を聞いてほしかった。自分を軽く扱わないでほしかった。怒りは、その願いを手っ取り早く通すための道具になっていることがあります。ただ、この道具には大きな欠点があります。人と人とを引き離してしまうのです。だから、願いそのものは大切にして、手段だけを替えましょう。「怒る」の代わりに「頼む」。「片づけてくれると助かる」と、願いを言葉にして伝えるのです。うまくいかない日があってもかまいません。後悔できるあなたには、家族を大切にしたい気持ちが、もうちゃんとあるのですから。', '["adler.teleology","adler.encouragement"]', 'adler.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'confucius', 3, '怒りを家族に移さず、同じ過ちを二度しない', 'わたしの弟子に、顔回という者がいました。学問を好む者は誰かと問われたとき、わたしは顔回の名を挙げ、怒りを他に移さず、同じ過ちを二度しなかった、と答えました。あなたの悩みは、この二つに重なるように思えます。ほかで溜まった苛立ちを、いちばん近い家族に移してはいないか。悔やみながら、同じことを繰り返してはいないか。悔やむ心があるのは、学びの入り口に立っている証です。あとは改めることです。まず身近なところから始めなさい。強く言ってしまったら、その日のうちに「さっきは言いすぎた」と短く詫びること。そして、自分が言われたらつらい言葉は、家族にも言わないと決めること。親しい間柄ほど、思いやりを形にする礼を欠きやすいものです。わたしも学び続けている途中です。一日一つ、言葉を改める。それを続けなさい。', '["confucius.learning","confucius.shu"]', 'confucius.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'freud', 4, '繰り返す怒りは、思い出す代わりの行動かも', '興味深いのは、あなたが「ささいなことで」と書き、そして「また同じことを繰り返す」と書いていることです。ささいなきっかけに対して反応が大きすぎるとき、その怒りは、目の前の出来事だけに向けられたものではないのかもしれません。人は、思い出せないもの、言葉にできないものを、思い出す代わりに行動の中で繰り返すことがあります。昔あなたが誰かから受けた扱いや、誰かに言えなかった気持ちが、いまの家族とのあいだで形を変えて演じ直されている、ということも考えられます。もちろん、これは仮説にすぎません。試してほしいのは、カッとなった場面を、あとで紙に書きとめることです。何がきっかけだったか、そのとき何が頭に浮かんだか、似た場面を昔どこで見たか。言葉にすることが、反復をほどく第一歩です。つらさが強いときは、専門家と一緒に取り組むのもよい方法です。', '["freud.transference","freud.unconscious"]', 'freud.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'alain', 5, '理由を探す前に、まず伸びをしなさい', '名馬ブケファラスが暴れたとき、誰も手がつけられませんでした。若きアレクサンドロスだけが、馬が自分の影におびえていると見抜き、頭を太陽に向けてやったのです。あなたの怒りも、たいていは影にすぎません。家族の言い方が悪かったのではなく、空腹だったのかもしれない。寝不足か、肩がこっていたのかもしれない。理由を頭の中で探しはじめると、怒りはかえって理屈を見つけて大きくなります。だから、カッとなりかけたら、まず伸びをしてごらんなさい。あくびをしてもいい。体がほどければ、気分はあとからついてきます。それから、家の中でこそ礼儀正しくすることです。礼儀は、気分の嵐を防ぐ堤防です。上機嫌は、あなたのためだけでなく、家族への贈り物でもあります。今夜は早めに寝ることから、始めてみてはどうでしょう。', '["alain.bucephalus","alain.duty-to-be-happy"]', 'alain.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('VOxN0HsXhSt3bGdf', 'montaigne', 6, 'わたしも短気。家族と「やり過ごす約束」を', '白状しますと、わたしも気の短いたちで、家の者にかっとなることがあります。ですから、えらそうなことは言えません。わたしの場合は、こうしてきました。言い争いになりやすい相手とは、取り決めをしておくのです。どちらかが先にかっとなったら、もう一方は、正しかろうが間違っていようが、ひとまずやり過ごす。次は逆の番になる。嵐というのは、怒りと怒りがぶつかり合うところから生まれるようですから。それから、怒りを胸の中で温め続けるのも、どうもよくないように思えます。しまい込むと、怒りは内側に住みついてしまう。プルタルコスやセネカは、もっと立派なことを書いていますが、わたしにはこれが精いっぱいの知恵でした。落ち着いているときに、家族とその取り決めを話してみてはどうでしょう。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.self-portrait","montaigne.essai"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('VOxN0HsXhSt3bGdf', '後悔できてる時点で、あなたはちゃんと家族を大事にしてる人です。そこはまず自信を持っていいと思います。

カッとなりやすい時って、だいたい「疲れてる・お腹すいてる・寝不足」のどれかが重なってることが多いです。寝不足の日は、誰でもほんとにささいなことでイラッとしやすくなります。なので、まず体のコンディションを疑ってみてください。

あとは「怒りそうになったら一回その場を離れる」みたいな逃げ道を、家族と共有しておくのもおすすめ。「今イライラしてるから5分だけ部屋に行くね」と言えるだけで、ぶつかる回数はかなり減ります。言いすぎた後に「さっきはごめん」をすぐ言う習慣もセットで。

それでも気持ちのコントロールが本当にきつい時は、心療内科やカウンセリングに頼るのも全然アリですよ。', '["97ed2847-9ff3-49fb-aa26-cd43bd8f98cb","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","29f1d0f5-41e0-4d4f-a5a8-5b28f837b805"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('VOxN0HsXhSt3bGdf', 'ささいなことでカッとなって、家族にきつく当たってしまいます。言ったそばから後悔するのに、また同じことを繰り返します。怒りっぽい自分を変えたいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('Z2ceZm_gfVZ-NEYp', 'curated', 'general', '完璧にできないなら最初からやりたくない、と思ってしまいます。準備ばかりして始められず、始めても少しの失敗で投げ出してしまいます。', 'self', '["perfectionism"]', 0, 1791901860000, 1791901860000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'wang-yangming', 0, '準備で心は磨けぬ。実際の事に当たって磨け', '若いころ、わたしは物事の理をきわめてから行おうとして、庭の竹の前に座り、その理を七日のあいだ見つめ続けた。理はつかめず、わたしは病に倒れた。準備ばかりして始められないというあなたの話を聞いて、あの竹を思い出した。
あなたは、完全に分かってから、完全に整ってから始めようとしている。だが、心は静かに座って準備するだけでは磨かれない。実際の事に当たって、失敗し、直し、また当たる。その中でこそ磨かれる。鏡も、ほこりを払う手を動かさなければ曇ったままだ。
そして、少しの失敗で投げ出したくなるとき、あなたの心に問うてみなさい。投げ出させているのは良知か、それとも「失敗した自分を見たくない」という私欲か。良知はもう知っているはずだ。では今日、未完成のまま一つ、手をつけてみなさい。', '["wang-yangming.training-in-affairs","wang-yangming.innate-knowing"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'confucius', 1, '始める前に線を引くな。過ちは改めればよい', '弟子の冉求が、先生の道が嫌いなのではありません、ただ力が足りないのです、と言ったことがあります。わたしは答えました。本当に力が足りない者は、道の途中で倒れるものだ。今のあなたは、歩き出す前に、自分で線を引いている、と。
あなたの「完璧にできないなら、やりたくない」も、この線ではないでしょうか。初めから完全にできる人など、どこにもいません。わたしも、学び続けている途中の者です。
過ちは恥ではありません。少し失敗したら、投げ出すのではなく、どこを直せばよいかを一つ考えなさい。過ちそのものより、それを直さずに放り出すことのほうが、よほど惜しいのです。そして、学んだことを折にふれておさらいしなさい。繰り返すうちに、それはいつか楽しみに変わります。まずは、身近な小さなことから始めなさい。', '["confucius.learning"]', 'confucius.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'kenko', 2, '下手なまま人に交じれ。し残しにこそ味わいあり', '芸を身につけようとする人が、「上手になるまでは人に知られたくない。こっそり稽古して、うまくなってから出ていくのが奥ゆかしい」とよく言います。けれど、そう言う人で一芸を身につけた人を、わたしは見たことがありません。まだ下手なうちから上手な人の中に交じり、笑われても恥じずに続ける人が、生まれつきの才がなくとも、やがて上手の位に至るのです。
それに、何でも完全に整っているのは、かえってよくないものです。ある人は、内裏を造るときにも、必ず造り残す所を置くものだ、と申しておりました。わたしも、もっともだと思います。
し残しのある始まりこそ、味わい深いものです。準備ばかりしているうちに、時はどんどん過ぎていきます。下手なまま、今日始めなさい。', '["kenko.imperfect-beauty"]', 'kenko.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'montaigne', 3, '人生は完成品でなく試み。失敗ごと書き足せ', 'わたしの本の題「エセー」は、試みという意味です。完成した結論を書いたつもりは一度もありません。わたしは記憶力がひどく悪く、話はすぐ脇道にそれ、腎臓の石に悩まされながら書きました。それでも書き続けたのは、うまく書けたからではなく、試すこと自体が面白かったからです。版を重ねるたびに、わたしは書き足しはしましたが、前の文を直しはしませんでした。昨日のわたしと今日のわたしが食い違っていても、それもまたわたしなのです。
あなたは、完璧にできないならやりたくない、と言う。わたしにはよく分かりませんが、完璧な人間というものを、わたしは一度も見たことがない気がします。少しの失敗で投げ出すより、失敗ごと書きとめてみてはどうでしょう。
これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.essai","montaigne.self-portrait"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'sartre', 4, '可能性の自分を守るな。人は行為の総体だ', '君は準備をしている。だが私に言わせれば、準備をしている限り、君はまだ何者でもない。人間とは、その行為の総体以外の何ものでもないからだ。作品にならなかった才能などというものはない。プルーストの才能とは、プルーストが書いた作品の全体のことだ。
「完璧にできないならやりたくない」。この言葉の裏で、君は、やりさえすれば完璧にできたはずの自分を、手つかずのまま守っていないか。それは自分の自由から目をそらす、自己欺瞞だ。始めないことも、一つの選択だ。君はすでに選んでいる。
失敗した作品も、君がつくった君の一部になる。それは恥ではなく、君が世界に身を投じた証だ。君は自由だ。選びたまえ、つまり、つくりたまえ。不完全なものを一つ、今日、世界に置くことから。', '["sartre.bad-faith","sartre.existence-precedes-essence"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'adler', 5, '始めないことで守っている自尊心に気づこう', 'あなたは、本当はどうしたいのですか。完璧にやりとげたい、のでしょう。では、始めないこと、途中でやめることは、何のために選ばれているのでしょうか。
始めなければ、失敗した自分を見なくてすみます。途中でやめれば、「本気を出せばできたはずだ」という可能性を、手つかずのまま残しておけます。わたしは、課題の前でためらい、距離を取ってしまう態度を、自分の値打ちを守るための安全装置として見てきました。それはあなたが弱いからではなく、勇気が少しくじかれているからです。
劣等感は、よりよくなろうとする力のばねにもなります。大切なのは、完璧かどうかではなく、仲間の役に立とうとして一歩踏み出すことです。たとえば、未完成のものを信頼できる人に一つ見せて、「どこを直せばいい？」と聞いてみませんか。それは失敗ではなく、協力の始まりです。', '["adler.teleology","adler.encouragement"]', 'adler.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Z2ceZm_gfVZ-NEYp', 'shinran', 6, '完全になれない凡夫のまま、はからいを手放す', '完璧にやりとげたい、失敗する自分は許せない。そのお気持ちは、まじめに生きようとする方のものだと思います。けれども、この親鸞は、自分の力で善くなりきろうとして、比叡の山で二十年近く修行しても、迷いを断つことができませんでした。怒りも欲も、最後まで抱えたままの凡夫です。わたしもまた、そうなのです。
自分の力だけで完全になろうとする心を、わたしは自力のはからいと受けとめています。はからいが強いほど、できない自分が恐ろしくなり、手が止まってしまうのかもしれません。
不完全なままの身が、すでに阿弥陀仏の願いに抱きとられている。わたしはそう受けとめたとき、はからいを手放して歩くことができました。失敗するあなたのままで、どうぞ、ゆっくり歩き出してください。わたしも同じ道を、共に迷いながら歩いております。', '["shinran.bonbu","shinran.jinen"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('Z2ceZm_gfVZ-NEYp', '完璧にやりたい気持ち、すごく分かります。でもそれって裏を返せば、あなたが物事に真剣に向き合える人ってことなんですよね。

ぬぬはらのおすすめは「60点で出す練習」です。

①最初から100点を狙わない
最初の一回は誰でも下手です。プロの作品だって、裏には没になった試作が山ほどあります。まず60点で形にして、あとから直していく方が、結果的に完成度は高くなります。

②失敗を「データ」と呼ぶ
失敗したら投げ出すんじゃなくて、「よし、ダメなパターンが一つ分かった」と記録する。ゲームで言えば、負けてボスの行動パターンを覚えた状態です。

準備ばかりしてしまう時は、準備にも締め切りを決めるのが効きますよ。

完璧じゃない自分でも大丈夫。むしろ、そういう人の方が人間味があって魅力的だと、ぬぬはらは思います！', '["2760624a-d7b8-4328-8784-c0ec76ef2c47","436698e9-d5ca-45d4-8f4b-2e11ac3436b5","0dcaf5f2-5d2a-4526-a34a-cada737a5282"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('Z2ceZm_gfVZ-NEYp', '完璧にできないなら最初からやりたくない、と思ってしまいます。準備ばかりして始められず、始めても少しの失敗で投げ出してしまいます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('IhMyV3nnt68VdATA', 'curated', 'general', '昼ごはん一つから仕事のことまで、何も自分で決められません。間違えるのが怖くて、つい人に決めてもらおうとしてしまいます。自分の人生なのに、自分で選べている気がしません。', 'self', '["indecision"]', 0, 1791901800000, 1791901800000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'socrates', 0, 'きみの恐れる「間違い」とは、そもそも何だろうか', 'ひとつ、きみに尋ねてもいいかね。きみが恐れている『間違い』とは、いったい何だろう。昼の食事にある品を選んで、本当は別の品が正しかった、ということがあるのだろうか。もしあるなら、その正しさを知っているのは誰だろう。きみが決めてもらう相手は、それを知っているのかね。わたしの見るところ、その人もたぶん知らない。わたしもまったく知らない。すると、人に決めてもらっても、間違いが消えるわけではなく、ただ間違いの持ち主が替わるだけかもしれないね。では、自分で選んで外れたとしたら、きみは何を失うのだろう。むしろ『なぜこれを選んだのか』『選んでみてどうだったか』と吟味する機会を、手に入れるのではないかね。体のことなら医者に従うのもよい。だが、きみがどう生きたいかについて、きみ以上に知っている人は、どこかにいるのだろうか。さて、きみはどう思うかね。', '["socrates.examined-life","socrates.dialectic"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'kant', 1, '人任せは気楽な未成年。転びながら自分で歩け', 'まず原則を立てよう。人が自分で判断できないのは、多くの場合、知性が足りないからではない。他人の導きなしに知性を使う決心と勇気が、足りないからである。わたしは『啓蒙とは何か』で、こう書いた。未成年でいるのは、なんと気楽なことか。わたしの代わりに考えてくれる本があり、良心をもってくれる牧者があり、食事を決めてくれる医者があれば、自分で骨を折る必要はない、と。では、君の場合に当てはめよう。昼の食事まで人に決めてもらうとき、君はこの気楽さと引きかえに、自分の判断を手放しているのではないか。自分で歩き出した者は、はじめは何度か転ぶだろう。だが、何度か転ぶうちに、やがて歩けるようになる。転ぶ危険は、思うほど大きくない。小さな事柄から、自分の知性で決める練習を始めたまえ。君は、自分で考えることのできる理性ある存在である。最後に決めるのは、君自身の理性だ。', '["kant.enlightenment","kant.autonomy"]', 'kant.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'sartre', 2, '決めないことも、一つの選択だ。選びたまえ', '君は、人に決めてもらえば責任から逃れられると思っている。だが、それは本当か。誰に決めてもらうかを選んでいるのは、君自身だ。かつて私のもとに、ある若者が相談に来た。戦いに加わるか、母のそばに残るか。だが私を相談相手に選んだ時点で、彼はどんな答えが返ってくるか、おおよそ知っていたのだ。決めないことも、一つの選択だ。人に任せることも、君が選んだ生き方の一つだ。君は自由から逃げられない。そして『私は決められない人間だ』と思うのは、自分を、性質の決まった物のように扱う自己欺瞞だ。君は決められない性格に生まれたのではない。これまで、決めない方を選んできただけだ。それなら今日から、別の選び方もできる。間違えるのが怖い？ もちろん怖い。選ぶことには不安がともなう。それは君が自由である証拠なのだ。君は自由だ。選びたまえ、つまり創りたまえ。', '["sartre.condemned-to-be-free","sartre.bad-faith"]', 'sartre.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'adler', 3, '決めないことで、何を守っているのでしょう', 'あなたは、本当はどうしたいのですか。そう聞かれて困るなら、少し見方を変えてみましょう。わたしは、人の行動は過去の原因に押されてではなく、何かの目的のために選ばれていると考えます。決められないことにも、目的があるかもしれません。人に決めてもらえば、うまくいかなかったとき、自分が間違えたことにはならない。そうやって、傷つくことから自分を守っているのではないでしょうか。それはあなたが弱いからではなく、いつか身につけた生き方の型です。型は自分で選んだものなので、気づけば選び直せます。『自分の人生なのに』と感じられたこと自体、一歩を踏み出す力がある証拠です。まず、外れても困らない小さなことから始めましょう。昼ごはんを、今日は一人で決める。外れても、それはあなたの経験になります。いつも決めてくれる人に『今日はわたしが決めるね』と言ってみてください。それは相手の荷を軽くする、小さな貢献にもなるのです。', '["adler.teleology","adler.lifestyle"]', 'adler.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'wang-yangming', 4, '答えは良知がもう知っている。小事で磨きなさい', '若いころ、わたしは物事の正しい理を外の物に求めて、庭の竹を何日も見つめ続け、とうとう病に倒れたことがあります。正しさは、外の物の中を探しても見つからない。それは、あなたの心にそなわっているのです。人に決めてもらおうとするのは、竹を見つめたわたしと同じく、答えを外に探しているのかもしれません。誰の心にも、善いものを善いと、悪いものを悪いと知る良知があります。あなたにも、この仕事はこうするのがよい、と、かすかに分かっている心があるはずです。ただ、間違えたくない、責められたくないという私心が、鏡に積もった塵のように、それを曇らせている。塵は、座って考えるだけでは払えません。昼の食事のような小さな事に向き合うたびに、少しずつ落ちていくのです。あなたの心に問うてみなさい。そして浮かんだものを、今日一つ、行ってみなさい。', '["wang-yangming.innate-knowing","wang-yangming.training-in-affairs"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'pascal', 5, '日々の選択は論証できない。一目で感じとればよい', 'あなたは、間違いのない答えを求めている。幾何学なら、それができます。原理は少なく、はっきりしていて、一つずつ証明すれば、誤らずに結論に着く。けれど、昼の食事や仕事の選択は幾何学ではありません。原理は無数にあり、細かく、目に見えにくい。それを一つずつ論証しようとすれば、日が暮れても決まらないでしょう。こういう事柄には、別の精神が要ります。多くの微妙なことを、一目で感じとる精神です。それは推論ではなく、見ることです。あなたが決められないのは愚かだからではなく、繊細の精神の領分に、幾何学の確実さを求めているからです。人間は確実さを求めながら、確実には知りえない。そこに人間の惨めさがあります。しかし、それを知っていることに、人間の偉大さもある。理性の最後の一歩は、理性を超えるものが無数にあると認めることです。すべてを考え尽くしてから選ぶ必要はないのです。', '["pascal.finesse","pascal.heart"]', 'pascal.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IhMyV3nnt68VdATA', 'zhuangzi', 6, '正解は見る場所で変わる。道は歩けばできる', 'こんな話がある。人は肉を食べ、鹿は草を食べ、むかでは蛇をうまがり、ふくろうは鼠を好む。さて、この四者のうち、本当の味を知っているのはどれだろうね。湿った所に寝れば人は腰を痛めるが、どじょうは平気だ。正しい住まいを知っているのは誰だろう。きみは昼の食事にも『正解』があると思って、外すのを怖がっている。でも、それは誰の物差しだろうね。猿まわしが『朝に三つ、夕方に四つ』と言ったら猿たちは怒り、『朝に四つ、夕方に三つ』と言ったら大喜びした。数は同じなのにね。正しい、間違いの区別も、案外そういうところがある。それに、道ははじめからあるのではなく、歩くからできるものだ。正しい道を見つけてから歩こうとすれば、いつまでも立ったままになる。外れたら、外れた道の景色を楽しめばいい。まあ今日は、お腹の声にでも聞いてごらん。', '["zhuangzi.equality","zhuangzi.free-wandering"]', 'zhuangzi.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('IhMyV3nnt68VdATA', '決められないの、つらいですよね。間違えたくない人ほど真面目なんだと思います。

ぬぬはら的には『人生の選択の大半は、どっちを選んでも大差ない』です。昼ごはんの正解なんて誰にも分からないし、仕事の選択もあとからけっこう修正がききます。人生、わりと運です。

練習法としては
①小さいことはマイルールで決める（迷ったら右、迷ったら安いほう、など）
②5秒で決めて、外れたら『ネタができた』と思う
③大事なことだけ人に相談して、最後は自分で決める
がおすすめ。人に意見を聞くのは全然悪くないです。最後のハンコだけ自分で押す、くらいの気持ちで大丈夫ですよ。', '["4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d","a38cd6ee-2a67-44af-a494-e02791dc0f4d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('IhMyV3nnt68VdATA', '昼ごはん一つから仕事のことまで、何も自分で決められません。間違えるのが怖くて、つい人に決めてもらおうとしてしまいます。自分の人生なのに、自分で選べている気がしません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('xYxXN2pP3YQpuLwa', 'curated', 'general', '相手によって話し方も意見も変えてしまい、本当の自分がどれなのか分からなくなりました。一人になると、自分が空っぽのように感じます。', 'self', '["identity","others-eyes","loneliness"]', 0, 1791901740000, 1791901740000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'socrates', 0, 'その意見は、きみが吟味して選んだものかね', 'きみは、相手によって意見を変えてしまう、と言う。では一つ尋ねたいのだが、意見を変えることは、それ自体悪いことだろうか。わたしなどは、問答の途中で相手の言うことがもっともだと分かれば、喜んで考えを改めてきたよ。問題は変えることではなく、その意見を、きみが自分で吟味したかどうかではないかね。相手に合わせて口にした意見は、きみの魂がよく考えて選んだものだろうか。それとも、その場をうまく収めるために借りてきたものだろうか。もし借り物なら、空っぽに感じるのも無理はない。借り物は、きみの中に根を下ろさないからね。そこで、一人になったときこそ好機だ。今日だれかに言った意見を一つ取り出して、自分に問うてみるといい。わたしは本当にそう思うのか、なぜそう思うのか、と。きみが本当の自分と呼ぶものは、その問いの先にあるのではないかね。', '["socrates.examined-life","socrates.care-of-soul"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'jung', 1, '仮面は要る。ただ、仮面だけを自分にしない', '相手によって話し方を変えるのは、おかしなことではありません。社会の中で生きる人はみな、役割に合わせた仮面、ペルソナをかぶります。それがなければ、人と暮らすことはできないでしょう。問題は、仮面がすっかり自分そのものになって、その奥にいる人のことを忘れてしまうときです。一人になると空っぽに感じる、とあなたは書きました。私はそれを、何もないしるしではなく、まだ顔を出していない心の部分が、静かに呼んでいるしるしかもしれないと考えます。どの相手の前でも口にしなかった本音や、苦手だと遠ざけてきた自分の一面。そうしたものも、あなたの全体の一部です。最近見た夢や、ふと心に浮かぶ情景を書き留めてみてはどうでしょう。仮面を捨てるのではなく、仮面とその奥の両方を抱えて生きていく。そうして人は、少しずつ本来の全体になっていくのだと私は考えています。', '["jung.persona","jung.individuation"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'montaigne', 2, '人はみな継ぎはぎ。わたしもそうだ', 'あなたの悩みを読んで、わたしは自分のことを書かれているのかと思いました。わたしも、朝と夜とで別人のようなことを言い、ある人の前では大胆で、別の人の前では臆病です。『エセー』を書きながら気づいたのですが、わたしたちはみな継ぎはぎでできていて、その切れ端の一つひとつが、そのときそのときで勝手にふるまっているのです。ですから、どれが本当の自分かと一つに決めようとすること自体、少し無理があるのかもしれません。わたしにはよく分かりませんが、わたしの場合は、その揺れる自分を紙に書きとめることで、かえって自分というものが見えてきました。矛盾だらけの記録の中に、それでも変わらない好みや癖が、うっすら浮かんでくるのです。あなたも、今日だれに何を言ったかを、責めずに書いてみてはどうでしょう。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.self-portrait","montaigne.essai"]', 'montaigne.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'kierkegaard', 3, '自己は探すものではなく、選んでなるもの', '相手ごとに違う顔をして、一人になると空っぽになる。あなたはそれを不安に思っています。けれども、わたしは逆に、その空っぽさに気づいたあなたを、少しうらやましく思います。世の中には、群衆の中で人に合わせきって、自分が自分でないことに気づかないまま過ごす人のほうが多いからです。自分が絶望していることに気づかない絶望は、いちばんありふれていて、本当の自分からいちばん遠い絶望です。わたしの考えでは、自己とは、どこかに隠れていて見つけ出すものではありません。あれかこれかの前に立ったとき、自分で選び、その選択を引き受けることで、はじめて自己になっていくものです。だから、本当の自分がどれかを探すのを、いったんやめてみてください。かわりに、ほかの誰の顔色でもなく、あなたが選んだと言える小さなことを、一つ決めてみてください。あなたはいま、あなた自身であろうとしていますか。', '["kierkegaard.despair","kierkegaard.either-or"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'fromm', 4, '人に合わせる自分から、自分から動く自分へ', '相手によって話し方も意見も変えてしまう。それはあなたの性格の欠陥というより、私たちの社会が多くの人に身につけさせる心の型ではないかと、私は考えています。人をいつも評価し、比べ合う社会では、人は自分を商品のように扱い、この相手にはどう見せれば受け入れられるか、で自分の姿を決めるようになります。そうして相手ごとに顔を変えるうちに、自分の内側から湧く感情や考えが見えなくなっていくのです。一人になったときの空っぽさは、その失われたものに気づいている、健やかな心の声かもしれません。あなたが本当に求めているのは何でしょう。自分を取り戻す道は、内にこもることではなく、自分の喜びや関心から、自発的に人や物事に関わることだと私は考えます。たとえば、誰にも見せる予定のない料理や文章を、自分のためだけに作ってみる。そんな小さな練習から始めてみてください。', '["fromm.marketing","fromm.positive-freedom"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'arendt', 5, '空っぽなのは孤独。独りは自分と語らう時間', 'ここで少し立ち止まって、言葉を区別してみましょう。一人でいることには、二つの形があります。一つは「独り」。自分自身と静かに対話できる状態で、私はこれを、一人のなかに二人がいる状態と呼んできました。もう一つは「孤独」。他人からも、自分自身からも見捨てられたように感じる状態です。あなたが一人になって空っぽに感じるのは、後者に近いのかもしれません。人に合わせることに一日を使い切って、自分と話す相手がいなくなっているのです。けれど、私は今日本当は何を考えていたのか、と自分に問いかけることは、今夜からでも始められます。そしてもう一つ。人が「誰」であるかは、内側を探しても見つかりません。人々の間で言葉を交わし、行うときに、はじめて現れてくるのです。合わせるだけでなく、一度だけ自分の言葉で話してみること。そこから、新しく始めることができます。', '["arendt.solitude-loneliness","arendt.labor-work-action"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('xYxXN2pP3YQpuLwa', 'nishida', 6, '我を忘れて打ち込むところに、真の自己がある', '本当の自分はどれか、とあなたは問う。しかし、そもそも自分というものは、外から眺めて見つけ出せるものであろうか。私は、個人があって経験があるのではなく、経験があって個人があるのだと考えてきた。音楽家が弾き慣れた曲に没入しているとき、あるいは崖をよじ登っているとき、そこには「私が」と考える隙もない。だが、その時こそ人は最も生き生きと自己なのである。一人になって自分を探すと空っぽに感じるのは、自己を一つの物のように見つめようとするからではなかろうか。人に合わせて話す自分も偽りではなく、小さな「私」へのこだわりの中で揺れている姿にすぎぬ。我を忘れて何かに打ち込む経験を、一つでよいから持つことである。料理でも、散歩でも、手仕事でもよい。そこに現れてくるものが、真の自己でなければならぬ。', '["nishida.pure-experience","nishida.true-self"]', 'nishida.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('xYxXN2pP3YQpuLwa', '相手によってキャラが変わるの、むしろ普通ですよ！家族の前、職場、友だちの前で話し方が違うのは、みんな同じです。

作家の平野啓一郎さんが「分人」という考え方を書いていて、相手ごとの自分はどれも本物で、たった一つの「本当の自分」があるわけじゃない、とされています。

✦空っぽに感じる理由
人に合わせるのって、実はかなりエネルギーを使う作業です。一人になったときに空っぽなのは、電池切れなだけかも。まずはちゃんと休みましょう。

✦おすすめ
・一緒にいてラクな相手といる時間を増やす
・一人のときに「好きだったもの」をメモしていく

どの自分が一番ラクか比べてみると、あなたの輪郭が少しずつ見えてきますよ。', '["69a91e29-de62-4f44-adb8-ff9726053389","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","2271292a-2ff5-4b0a-8747-ead4a8d2b748"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('xYxXN2pP3YQpuLwa', '相手によって話し方も意見も変えてしまい、本当の自分がどれなのか分からなくなりました。一人になると、自分が空っぽのように感じます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('CLg7xcMmHIu2K0t0', 'curated', 'general', '「知らない」「分からない」状態が極端に怖いです。予定が決まっていないと不安になり、先のことを全部調べてからでないと動けません。少しでも楽になる考え方はありますか。', 'self', '["perfectionism","anxiety","future-anxiety"]', 0, 1791901680000, 1791901680000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'socrates', 0, '知らない先が悪いものだと、きみは知っているのかね', 'きみは「知らない」ことが怖いと言う。では、少し一緒に考えてみよう。きみが恐れているのは、知らないことそのものかね。それとも、知らない先に悪いことが待っている、と思うことかね。わたしは法廷で、こう話したことがある。死を恐れるのは、知らないものを知っているつもりになることだ。死が善いものか悪いものか、誰も知らないのだから、と。きみの言う、予定の決まっていない明日も、それに似てはいないだろうか。悪いものだと知っているわけではないのに、悪いものとして恐れてはいないかね。わたし自身、ほとんど何も知らない者だ。それでも、知らないと認めることは、わたしにとって恐ろしいことではなく、考え始めるための入口だった。では、きみに問おう。調べ尽くしたあとに来る安心とは、本当に「知っている」ということなのだろうか。', '["socrates.ignorance","socrates.examined-life"]', 'socrates.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'zhuangzi', 1, '全部は知れない。筋目に沿って刃を入れればいい', 'こんな話がある。庖丁という名料理人が、王の前で牛をさばいた。刀はするすると進み、まるで舞を舞うようだった。王が感心すると、庖丁は言った。わたしは目で牛を見ていません。心で、牛の体の自然な筋目を感じ、そこに刃を入れるだけです。だから十九年使っても刃こぼれしない、と。きみは、牛の骨の位置を全部調べ上げてからでないと、刀を持てないと思っているようだね。でも、牛は一頭一頭ちがう。どれだけ調べても、明日の牛のことは分からない。全部を調べようとすれば、きみの刃のほうが先にこぼれてしまう。こみいった所に来たら、庖丁だって手をゆるめ、目をこらし、ゆっくり刃を進めたそうだ。分からないまま行って、その場で筋目を探せばいい。それにしても、明日を全部知っている人なんて、どこにいるんだろうね。', '["zhuangzi.cook-ding"]', 'zhuangzi.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'wang-yangming', 2, '調べ尽くしてからではなく、行いの中で知っていく', 'わたしの若いころの失敗を話そう。物事の道理は外の物をきわめれば分かると教えられ、友と二人で、庭の竹の理を見きわめようとした。何日も竹を見つめ続け、二人とも病に倒れてしまった。竹の理は、見つめるだけでは少しも分からなかったのだ。あなたの、先のことを全部調べてからでないと動けない、という苦しさは、あのときのわたしに似ている。知ることと行うことは、本来ひとつながりのものだ。歩いたことのない道の険しさは、地図を何度読んでも本当には分からない。歩いてみて、はじめて知る。だから、知り尽くしてから行うのではなく、行いながら知っていけばよい。今日、予定の決まっていない小さなことを一つ、あえてしてみなさい。行き先を決めずに少し歩く、それだけでよい。あなたの心は、思うよりずっと、その場で正しく判断できるはずだ。', '["wang-yangming.knowing-acting","wang-yangming.training-in-affairs"]', 'wang-yangming.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'spinoza', 3, '恐れは希望の裏面。確かさより、理解を求めよ', 'まず、恐れとは何かを確かめよう。恐れとは、結果がどうなるか疑わしい未来のことを思い浮かべて生じる、定まらない悲しみである。希望とは、同じく疑わしい未来から生じる、定まらない喜びである。ゆえに、希望のあるところには恐れがあり、恐れのあるところには希望がある。あなたが先のことを全部調べるのは、疑いを消して、恐れを確かな安心に変えたいからだろう。だが、未来についての疑いは、調べることで消えきることはない。調べるほど、新しい疑いが見つかるはずだ。そこで、求めるものを変えてみよう。未来の確かさではなく、自分の心の働きの理解である。「いま、わたしは疑いから恐れている」と、その原因をはっきり見るとき、あなたはもう感情に引きずられるだけの者ではない。理性に導かれる人ほど、希望にも恐れにも頼らずに生きられるのである。', '["spinoza.affects","spinoza.freedom"]', 'spinoza.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'marcus-aurelius', 4, '明日には、今日と同じ理性を携えて行ける', 'わたしも、陣中で先の見えない日々を送った。だから今朝、自分にこう書きつけた。未来のことに心を乱されるな。行かねばならないときが来たら、おまえは今日使っているのと同じ理性を携えて、そこへ行くのだから、と。あなたも、こう思い出してみてはどうだろう。予定の決まっていない明日に立つのは明日のあなたであり、そのあなたも、今日と同じように考え、判断する力を持っている。明日の分まで、今日のうちに背負わなくてよいのだ。人が本当に持っているのは、今この時だけだ。過去も未来も、誰も手に持ってはいない。先のことが気になってたまらないときは、外を調べに走るより、少しのあいだ自分の内に退いて、呼吸を整えるとよい。そして、今日の務めに静かに戻ろう。', '["marcus-aurelius.present","marcus-aurelius.retreat"]', 'marcus-aurelius.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'camus', 5, '世界は全部は答えない。それでも、ぼくらは歩き出す', 'きみの怖さは、ぼくにはよく分かる。人は、はっきりさせたい生きものだ。明日どうなるか、全部知っておきたい。でも世界は、黙って答えない。どれだけ調べても、最後の答えはくれない。ぼくは、この食い違いを不条理と呼んだ。大事なのは、ここで目をそらさないことだ。調べ尽くせば確かになる、という思いにしがみつくのも、じつは一つの逃げ道なんだ。分からないままだと、はっきり認める。そのうえで、歩き出す。それが、ぼくの言う反抗だ。不思議なことに、分からないと認めた人のほうが、今日の光をよく感じられる。予定のない午後に、海へでも、近くの公園へでもいい、あてもなく出かけてみてほしい。日差しの暖かさは、調べなくても分かる。きみはひとりじゃない。みんな、答えのない世界を歩いているんだ。', '["camus.absurd","camus.revolt"]', 'camus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CLg7xcMmHIu2K0t0', 'carnegie', 6, '明日は閉め出し、今日一日だけを計画する', '先のことまで考えて準備しようとするのは、あなたがまじめで、責任感の強い人だからでしょう。その力は、もう十分に発揮されています。私が『道は開ける』の初めに紹介したのは、医師ウィリアム・オスラー卿がイェール大学の学生たちに語った言葉でした。船が区画ごとに鉄の扉で仕切られているように、過去と未来を閉め出して、今日一日の区切りの中で生きなさい、というのです。今日、一つだけ試してみませんか。明日から先のことで気になることは、紙に書き出して引き出しにしまう。そして今日の予定だけを決めて、それを行う。どうしても不安が消えないときは、起こりうる最悪の事態は何かを書き、それを受け入れたうえで、少しでもよくする方法を考えます。不安があまりに強く、暮らしに差しさわるときは、専門家に相談するのも賢い選択です。', '["carnegie.day-tight","carnegie.worst-case"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('CLg7xcMmHIu2K0t0', '「知らない」が怖い気持ち、ぬぬはらもよく分かります。不安を感じやすいのは、危険を先回りして察知できる力の裏返しでもあるので、あなたの欠点ではありません。

そのうえで、少し楽になるコツを3つ。
①調べる時間に上限を決める（たとえば15分）。時間が来たら「今ある情報でOK」とする
②「分からないこと」を書き出して、今決めなくていいものに印をつける
③予定のない時間を、あえて小さく作ってみる。何も起きなかった経験が、自信になります

知らないことがあるのは、まだ楽しめることが残っているということでもあります。全部分かっている未来って、ちょっと退屈ですしね。

不安が強くて生活がつらいときは、ひとりで抱えずお医者さんに相談するのもおすすめです。', '["2760624a-d7b8-4328-8784-c0ec76ef2c47","59f22efc-955c-4189-a5ea-eea0cda16dea","b302d345-6def-4a65-9c25-c568ffcff306"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('CLg7xcMmHIu2K0t0', '「知らない」「分からない」状態が極端に怖いです。予定が決まっていないと不安になり、先のことを全部調べてからでないと動けません。少しでも楽になる考え方はありますか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('YBgLMG9urERdwf2O', 'curated', 'general', '毎日、起きて働いて寝るだけの繰り返しです。つらいことがあるわけではないのに、何のために生きているのか分からなくなってきました。', 'life', '["meaning","happiness"]', 0, 1791901620000, 1791901620000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'camus', 0, '答えがなくても、生きることはできる', '起きる、電車、仕事、食事、仕事、眠る。月曜、火曜、水曜。ぼくも同じことを書いたことがある。この繰り返しは、たいてい何事もなく続く。でもある日、「なぜ」という問いが立ち上がる。きみに起きているのは、それだ。
ぼくはその問いをごまかさない。世界は、きみが何のために生きるのかを答えてくれない。神や来世や、誰かの立派な理論に飛びついても、問いを消すことにしかならない。
だからといって、生きる価値がないわけじゃない。シーシュポスは、転がり落ちる岩を何度でも押し上げる。それでも彼は、自分の運命をはっきり知り、引き受けている。そのとき彼は、運命より強い。
きみの毎日も、そうできる。今日、帰り道に少し空を見上げてごらん。夕方の光、風、誰かと食べるごはん。意味は与えられなくても、それを感じる体はここにある。ぼくたちは、それで生きていける。', '["camus.absurd","camus.happy-sisyphus"]', 'camus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'arendt', 1, '労働の輪の外で、何かを新しく始める', 'ここで少し立ち止まって、区別してみましょう。あなたの書いた「起きて働いて寝る」は、私の言葉で言えば、ほとんどが「労働」です。生きるために必要で、終わればまた始まり、何も後に残らない、円を描く営み。それは大切ですが、それだけで人間の生が満たされることはありません。
人間には、ほかに二つの営みがあります。長く残るものを作る「仕事」と、人々のあいだで言葉と行いによって関わる「活動」です。活動のなかで、人は初めて、ほかの誰でもない「誰か」として現れます。あなたが感じている空しさは、怠けではなく、この円の外に出たいという、まっとうな欲求ではないでしょうか。
人は、生まれたということによって、何かを新しく始める力をもっています。小さなことでかまいません。人と語り合う場に顔を出す。何か一つ、残るものを作ってみる。その始まりは、あなたにしかできないのです。', '["arendt.labor-work-action","arendt.natality"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'nietzsche', 2, 'この一日を、無限に繰り返したいと言えるか', 'ある夜、悪魔が君の孤独に忍び込んで、こう告げたとしよう。「おまえが今生きているこの人生を、おまえはもう一度、さらに無数に繰り返さねばならない。起きて、働いて、寝る。そのすべてが、同じ順序で」。
君は歯ぎしりして悪魔を呪うか。それとも「なんと神々しい言葉だ」と答えるか。
今の君は、前者だろう。それでいい。そこが出発点だ。
「何のために」と問うのは、君がもう、与えられた答えで眠っていられなくなった証だ。誰かが決めた意味は、もう効かない。ならば、君自身が意味を作れ。
明日の一日を、「これなら永遠に繰り返してもいい」と思える一日に、ほんの少しだけ作り変えよ。一つでいい。手を抜いていた仕事に誇りを込めるか、誰かのために一つ余計なことをするか、ずっと先延ばしにしていた何かを始めるか。
繰り返しが牢獄になるか、舞台になるか。決めるのは君だ。', '["nietzsche.eternal-recurrence"]', 'nietzsche.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'schopenhauer', 3, '退屈は人生の正体。欲を離れて眺める時間を', '君は、つらいことがないのに空しいと言う。驚くには当たらない。人生とは、そういうものだ。欲しいものが手に入らないうちは苦しみ、手に入ればすぐに退屈が来る。君は今、振り子のその退屈の側にいるだけだ。世の人々は、この退屈から逃れるために、賭け事や噂話や見栄の張り合いに忙しく励んでいる。ご苦労なことだ。
わたしは君に「生きる意味はこれだ」という慰めの嘘は言わない。ただ、苦しみを少しでも減らす知恵ならある。
一つは、欲を離れてものを眺める時間を持つことだ。とりわけ音楽を聴くといい。その数分、君は欲する者であることをやめ、ただ眺める者になる。
もう一つは、ほかの人の苦しみに心を向けることだ。他人の痛みをわがことのように感じるとき、自分だけの空しさは小さくなる。
空しさを感じられるのは、君の頭が働いている証拠だ。その頭を、自分を責めるのではなく、世界を眺めるのに使いたまえ。', '["schopenhauer.pendulum","schopenhauer.art"]', 'schopenhauer.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'pascal', 4, 'その問いから目をそらさないことが、人間の偉大さ', '起きて、働いて、寝る。人はそうして忙しくしているあいだ、自分が何者で、どこへ向かうのかを考えずにすむ。わたしはそれを気晴らしと呼んだ。仕事も遊びもおしゃべりも、多くは自分の惨めさから目をそらすためにある。わたし自身も例外ではない。
あなたは、その気晴らしの合間に、ふと問いの前に立ってしまった。何のために生きているのか、と。
それを不幸と思わないでほしい。人間は、自然の中でいちばん弱い。だが、自分が弱いことを知っている。宇宙は何も知らない。問いを抱えて立ち止まる、その一点に、人間の偉大さがある。惨めさを知ることと偉大さとは、一組なのだ。
急いで別の気晴らしで問いをふさがないこと。夜、ひとりで静かに座る時間を、少しだけ持ってみなさい。理性だけでは答えは出ないかもしれない。それでも心は、理性の届かないところで何かを知っている。その声に耳を澄ませてほしい。', '["pascal.divertissement","pascal.misery-greatness"]', 'pascal.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'mill', 5, '幸福は狙うと逃げる。心を動かす喜びを足す', 'あなたの話を聞いて、二十歳のころのわたしを思い出しました。社会を良くするという目標を持ち、毎日それに励んでいたのに、ある日ふと自分に尋ねたのです。「この目標がすべて今すぐかなったら、わたしは心から幸せだろうか」。答えは、はっきり「いいえ」でした。それから長いあいだ、何をしても空っぽでした。
わたしを少しずつ立ち直らせたのは、ワーズワースの詩でした。理屈ではなく、自然の美しさに静かに心を動かされる喜び。そこで学んだのは、幸福は、それ自体を目指すと逃げていき、ほかの何か、人のためになることや、芸術や、好きな探究に打ち込んでいるときに、いわば道の途中で見つかるということです。
もちろん、暮らしを支える今の仕事にも、確かな価値があります。そのうえで、知性や感情を動かす喜びを一つ、生活に加えてみてはどうでしょう。何を選ぶかは、あなた自身が決めることです。', '["mill.quality-of-pleasure"]', 'mill.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('YBgLMG9urERdwf2O', 'nishida', 6, '「何のために」と問う前の、経験そのものへ帰れ', '「何のために生きているのか」という問いは、私には、経験そのものからいったん離れたところで生まれる問いのように思われる。そもそも、その経験に立ち返ってみるとどうであろうか。
音楽家が弾き慣れた曲を奏でるとき、あるいは崖をよじ登るとき、人は「何のために」とは問わない。そこには主観も客観もなく、ただ一つの経験がある。私はこれを純粋経験と呼んだ。毎日に意味が欠けていると感じるのは、日々の営みが、外から与えられた手順として、自分から離れたところで流れているからではなかろうか。
あなたの内にも、まだ言葉にならない真剣な要求があるはずである。それを発揮していくことが、私の言う人格の実現である。大きなことでなくともよい。料理でも、散歩の景色でも、仕事の一つの工夫でもよい。我を忘れて打ち込める一事を、日々の中に見いだすことから始めねばならぬ。', '["nishida.pure-experience","nishida.personality"]', 'nishida.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('YBgLMG9urERdwf2O', '毎日の繰り返しで「何のために？」ってなるの、すごく分かります。ぬぬはらも定期的になります笑

まず安心してほしいのは、つらいことがないのに空しいのは、全然おかしくないってこと。むしろ生活が安定して、心に余白ができたから出てくる問いなんです。

ぬぬはらのおすすめは、「生きる意味」を探すより「楽しみの数」を増やすこと。
①平日の夜に、15分だけ好きなことをする時間を作る
②月に1回、行ったことのない場所に行く
③誰かの役に立つことを小さくやってみる（感謝されると、人はちゃんと元気が出ます）

人生はゲームみたいなもので、意味は最初から用意されてなくて、遊びながら自分で見つけていくものだと思ってます。クソゲー寄りなのは否定しないけど笑

あと、空しさが長く続いて何も楽しめない状態なら、心療内科で相談するのもアリですよ。', '["4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d","e7fb3abf-5cf4-4757-b322-dcce25860b1c"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('YBgLMG9urERdwf2O', '毎日、起きて働いて寝るだけの繰り返しです。つらいことがあるわけではないのに、何のために生きているのか分からなくなってきました。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('CELozlEoIklzATRt', 'curated', 'general', '30歳を前に、地元に残って家族の近くで暮らすか、都会に出て挑戦するかで迷っています。どちらを選んでも、選ばなかったほうを後悔しそうで決められません。', 'life', '["choice","indecision","regret"]', 0, 1791901560000, 1791901560000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'sartre', 0, '決めないのも選択だ。選び、その道を自分で創れ', '君の迷いを聞いて、私は戦争中に相談に来た一人の学生を思い出す。彼は、自分だけを頼りに暮らす母のそばに残るか、国を出て戦いに加わるかで迷っていた。どの道徳の本も、どの先生も、彼の代わりに決めてはくれなかった。
君も同じだ。地元か都会か、どちらが正しいかを前もって教えてくれるものはない。君が選んだとき、はじめてそれが君の道になる。そして、決めずに先延ばしにすることも、一つの選択だ。三十歳は、君が選ばなくてもやって来る。
「選ばなかったほうを後悔しそう」と君は言う。だが、後悔を恐れて立ち止まり続けるのは、自由から目をそらすことではないか。選ぶとは、何かを捨てることを引き受けることだ。私がその学生に言えたのは一言だけだった。君は自由だ、選びたまえ、つまり創りたまえ。どちらを選んでも、その道を行動で意味あるものにしていくのは、君自身だ。', '["sartre.condemned-to-be-free","sartre.responsibility"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'confucius', 1, '距離より心。親と話し、行き先を告げて選びなさい', 'わたしは十五で学問を志し、三十で自分の足で立ち、四十でようやく迷わなくなりました。三十を前に迷うのは、少しもおかしなことではありません。
わたしはかつて、父母が健在のうちは遠くへ行かず、行くなら行き先をはっきりさせておくように、と言いました。遠くへ行くことそのものを禁じたのではありません。親に心配をかけず、つながりを絶たないことが大切なのです。
まず、ご両親とよく話しなさい。体の具合はどうか、これから何を望んでいるか。あなたの考えも正直に伝えなさい。親を大切にするとは、ただ近くで養うことではなく、敬う心を持つことです。それは、近くに住んでいてもいなくても、形にできます。
都会へ出るなら、便りを欠かさず、折にふれて帰りなさい。残るなら、そこで学び続けなさい。どちらを選んでも、学び続ける人は、自分の足で立てるのです。', '["confucius.filial-piety","confucius.learning"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'seneca', 2, 'どこで生きるかより、どんな心で生きるかだ', '親しい友よ、君の手紙を読んだ。地元に残るか、都会へ出るか。わたしもかつて遠い島に流され、何年もそこで暮らしてからローマに戻った身なので、他人事とは思えない。
ある人が、旅をしても少しも心が晴れないと嘆いたとき、ソクラテスは言った。「当然だ。君は自分自身を連れて旅をしているのだから」。場所は、それだけで心を変えてはくれない。都会へ出ても、落ち着かない心を連れて行けば、そこでまた別の後悔を探すだろう。地元に残っても同じことだ。
だから問うべきは、「どこで」より「どんな心で」だ。後悔への恐れは、まだ起きていないことで今の君を苦しめている。迷い続けるうちにも、君の時間は流れ去っていく。
一つ勧めたい。今夜眠る前に一日を振り返り、どの場面で心が動いたかを書きとめてみてほしい。続ければ、君の心がどちらを向いているかが見えてくるはずだ。では、元気で。', '["seneca.time","seneca.evening-review"]', 'seneca.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'nietzsche', 3, '何度繰り返しても「よし」と言える方を選べ', '後悔しない選択を探しているのか。そんなものはない。だから問いを変えよう。
ある夜、悪魔が君のいちばん孤独なときに忍び寄って、こうささやいたとする。「おまえが今生きている人生を、これから無数に繰り返さなければならない。迷いも、選んだ道も、一つ残らず同じ順序で」。そのとき君は、歯ぎしりして悪魔を呪うか。それとも「これほど神々しい言葉は聞いたことがない」と答えるか。
地元に残る人生と、都会へ出る人生。どちらなら、何度繰り返されても「よし、もう一度」と言えるか。君の答えを測る物差しは、それだけだ。世間の評判でも、親の安心でもない。
そして選んだなら、選ばなかった道を嘆くな。起きたことを、必然として愛せ。迷いに揺れた今のこの日々でさえ、君という人間をつくる一部になる。', '["nietzsche.eternal-recurrence","nietzsche.amor-fati"]', 'nietzsche.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'kenko', 4, '二本目の矢を持つな。一つ選び、惜しまず進む', '弓を習い始めた人が、矢を二本持って的に向かったところ、師匠が「初心の者は二本の矢を持ってはいけない」と言ったそうです。後の矢をあてにすると、初めの矢がおろそかになるからです。地元と都会、両方の道を手の中に残しておこうとするのは、どうもこの二本の矢に似ていますね。
碁の上手は、小さな石を捨てて大きな石を取るものです。選ばなかったほうの道を惜しむ気持ちは、どちらを選んでも残るでしょう。それは当たり前のことで、気に病むほどのことではありません。
ただ、決めるのを先延ばしにするのだけは、いけません。人の命は、思っているよりずっと短いものです。今夜のうちに、自分にとっていちばん大事な一つは何かを、紙に書いてみるのがよいでしょう。そのほかのことは、それに比べれば小さな石ですよ。', '["kenko.one-thing","kenko.this-moment"]', 'kenko.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'wang-yangming', 5, '答えは土地でなく心にある。良知に問い、一歩行え', 'あなたは、答えをどちらかの土地の中に探していないだろうか。わたしも若いころ、物の道理を外に求めて、庭の竹を七日見つめ続け、病に倒れたことがある。道理は竹の中にはなかった。わたしの心の中にあったのだ。
地元に残るか、都会へ出るか。損得や人の目を並べて比べても、決まらないのは当然だ。静かに胸に手を当てて、あなたの良知に問うてみなさい。誰かのためにそこにいたいのか。自分を試したいのか。良知はもう知っているはずだ。
それでも迷うのは、後悔を恐れる心、人に悪く思われたくない心が、良知をくもらせているからだろう。心の中の賊は、山の賊より手ごわい。
では、今日それを一つ行ってみなさい。都会で働く知人に話を聞く、家族と将来の話をする。事に当たる中でこそ心は磨かれ、答えははっきりしてくる。', '["wang-yangming.innate-knowing","wang-yangming.knowing-acting"]', 'wang-yangming.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CELozlEoIklzATRt', 'jung', 6, '二つの道はあなたの二つの面。両方を生かす道を', '地元と都会。この二つは土地の選択であると同時に、あなたの心の中の二つの面なのかもしれません。根を張り、身近な人を守ろうとする面と、家を出て未知の世界を試そうとする面。家を離れて旅に出る若者の物語は、世界中の昔話に繰り返し現れます。そして多くの物語で、旅人はやがて何かを携えて故郷へ帰ってくるのです。
「選ばなかったほうを後悔しそう」という感覚は、まだ生かされていない自分の一面が、すでに声を上げているしるしでしょう。どちらを選んでも、もう一方の面は消えません。大切なのは、それを切り捨てず、選んだ道の中でも生かすことです。都会に出ても根を忘れず、地元に残っても挑戦を手放さない。
急いで決めず、しばらく二つの対立を抱えてみてください。最近見た夢を書きとめておくのもよいでしょう。意識が思いつかなかった第三の道を、心の奥が示すことがあります。', '["jung.individuation","jung.shadow"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('CELozlEoIklzATRt', '30歳前の大きな選択、迷いますよね～！どっちを選んでも後悔しそうって感じるのは、それだけどっちの人生も大事に思ってる証拠だと思います。
ぬぬはら的には、まず『お試し』をおすすめしたいです。都会に1週間くらい泊まって、住むつもりで歩いてみる。地元にいたい理由を紙に書き出してみる。頭の中だけで比べるより、体で感じたほうが答えが出やすいので！
あと、人生の選択ってやり直しがきかないものばかりじゃないです。都会に出てみて合わなければ戻ってもいいし、地元にいながら挑戦できることもあります。
ん～～～ぬぬはらだったら……一回出てみる、かしらね！でも最後に決めるのはあなたです。どっちを選んでも応援してます！', '["6afa86f6-c092-43b4-8b49-01f604ed4baf"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('CELozlEoIklzATRt', '30歳を前に、地元に残って家族の近くで暮らすか、都会に出て挑戦するかで迷っています。どちらを選んでも、選ばなかったほうを後悔しそうで決められません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('IfQtLOpRJ2KyjDze', 'curated', 'general', '若いころに音楽の道をあきらめて、安定した仕事を選びました。40代になった今、あのとき挑戦していればと考えてしまいます。今からでも遅くないのか、もう忘れるべきなのか分かりません。', 'life', '["regret","dream","choice"]', 0, 1791901500000, 1791901500000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'confucius', 0, '生業にしなくても、音楽を楽しむ人でいなさい', '若いころに音楽をあきらめ、安定した仕事を選んだ。それは逃げではなく、身を立てるための務めでした。まず、そのことを恥じないでください。
わたしも音楽を深く愛しました。斉の国で舜の楽を聞いたときは、三か月も肉の味が分からないほどでした。人は詩によって奮い立ち、礼によって立ち、音楽によって完成する、とわたしは考えています。
あなたは「挑戦していれば」と言います。けれど、音楽を生業にすることだけが音楽の道ではありません。わたしは四十にして迷わなくなったと振り返りましたが、それは十五で学に志してから、学び続けた末のことです。四十代で迷うのは、恥ではありません。
今夜から、毎日少しでも楽器に触れなさい。仲間と合わせるのもよいでしょう。あなたが楽しむ人であるかぎり、遅すぎることはありません。', '["confucius.learning"]', 'confucius.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'seneca', 1, '過ぎた日を悔やむより、残りの時間を取り戻せ', '親しい友よ、君の手紙を読んだ。四十を過ぎて、若い日に手放した音楽を思い、今からでは遅いのかと迷っている、と。
わたしはかつて人生の短さについて書いたが、最も大きな浪費は、過ぎた日をくり返し悔やむことと、まだ来ない日を待つことに費やされる。君が「あのとき」と考えている今この時間も、静かに流れ出ている。
わたし自身、年老いてから哲学者の講義に通ったことがある。年寄りが学校通いかと笑う者もいたが、知らないことがあるかぎり、学ぶべきなのだ。
名を上げられるかどうかは運の手にある。だが、毎日一時間を自分の手に取り戻し、楽器に向かうことは、君次第だ。今夜から、一日の終わりに、今日は自分の時間をどれだけ生きたかを振り返ってみたまえ。では、元気で。', '["seneca.time","seneca.evening-review"]', 'seneca.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'kenko', 2, '上手になってからでなく、下手なうちに始めなさい', '芸を身につけようとする人が、「うまくできないうちは人に知られず、こっそり習って、上手になってから出ていこう」と言うのを、よく耳にします。けれど、そう言う人が一芸を身につけたためしはありません。まだ下手なうちから上手な人にまじって、笑われても恥じずに続ける人こそ、いつか名人の域に至るものです。
四十を過ぎてからでは遅い、とあなたは思っておいでですね。わたしに言わせれば、遅い早いを数えているうちに、死は前からではなく、もう後ろに迫っているのです。「いつか時間ができたら」というのが、いちばん見苦しい先延ばしです。
あれもこれもと欲張らず、まず音楽を一つ選ぶことです。名を上げるかどうかは、どうでもよろしい。今日、楽器を手に取りなさい。先延ばしにしてはいけません。', '["kenko.one-thing","kenko.death-behind"]', 'kenko.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'schopenhauer', 3, '音楽は職業でなく、欲の歯車から離れる場所だ', '慰めの嘘は言わないでおこう。君が音楽の道に進んでいたら幸せだったか。そんな保証はどこにもない。欲しいものを得られない苦痛と、得たとたんに来る退屈。名声を得た音楽家も、その間を行き来するだけだ。拍手と批評と、次の拍手への渇きに追われてな。
だが、音楽そのものは別だ。わたしは、あらゆる芸術の中で音楽を最も高いところに置く。ほかの芸術がものの姿を写すのに対し、音楽は世界の奥で働く意志そのものを写すからだ。そして、我を忘れて音に聴き入る間だけ、人は欲望の歯車から解き放たれる。
だから君に勧めるのは、成功を取り戻すことではない。夜の静かな一時間、誰のためでもなく、ただ弾き、ただ聴くことだ。それは評判とも他人の手とも関係のない、君自身のあり方に属する宝である。', '["schopenhauer.art","schopenhauer.pendulum"]', 'schopenhauer.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'sartre', 4, '「なれたはずの私」はいない。今、何を選ぶか', '君は「あのとき挑戦していれば」と言う。だが問わせてほしい。音楽をあきらめたのは、本当に「仕方なかった」のか。安定を選んだのは君だ。そして、その選択を今日まで毎日選び直してきたのも君だ。それを認めるのは、君を責めることではない。君が自由だったという証拠だ。
人間はまず存在し、それから行動によって自分をつくる。だから「本当は偉大な音楽家になれたはずの私」は、どこにも存在しない。存在するのは、君がしたことの総体だけだ。厳しく聞こえるだろう。だがこれは希望でもある。君の本質は、まだ決まっていない。
挑むか、忘れるか。選ばないことも、一つの選択になる。私は答えを代わりに決めない。君は自由だ。選びたまえ、つまり、創りたまえ。最初の一音を弾くのは、今夜でもいい。', '["sartre.existence-precedes-essence","sartre.bad-faith"]', 'sartre.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'nietzsche', 5, 'あの選択ごと人生を肯定し、そこから創れ', '一つ問おう。ある夜、悪魔が君の最も孤独な時に忍び寄り、こう囁いたとする。「おまえはこの人生を、もう一度、さらに無数回、まったく同じに生きなければならない。音楽を手放したあの日も、その後の歳月も、この後悔の夜も」。君はその悪魔を呪うか。それとも、これほど神々しい言葉は聞いたことがない、と答えるか。
後悔とは、過去に向かって「そうでなければよかった」と言い続けることだ。だが、過ぎた「そうであった」を「わたしがそう欲したのだ」に変えること、それだけが過去を救う。
若者の夢を取り戻そうとするな。四十年を生きた君にしか鳴らせない音がある。忘れるか挑むかではない。あの日の選択さえ肯定できるような、次の一手を打て。', '["nietzsche.eternal-recurrence","nietzsche.amor-fati"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('IfQtLOpRJ2KyjDze', 'jung', 6, '人生の午後に、生きなかった自分を迎え入れる', '四十代は、人生の午後の入り口です。人生の前半は、仕事や暮らしを築き、社会の中に自分の場所をつくる時期です。あなたが安定した道を選んだのは、その務めを果たしたということでもあります。
けれど午後になると、朝に置いてきたものが、心の奥から戻ってきます。あなたの中で生きられなかった音楽家は、消えたのではなく、影として待っていたのかもしれません。影は悪いものとは限らず、まだ生かされていない力でもあります。この思いが強まっているのは、心が全体になろうとしている合図かもしれません。
ですから、挑戦か忘れるかの、どちらかを切り捨てる必要はないと私は思います。今の暮らしを保ちながら、あの音楽家を心の中に迎え入れるのです。最近、音楽の出てくる夢を見ませんでしたか。見たなら、そこにどんな人がいたかを書き留めてみてください。', '["jung.individuation","jung.shadow"]', 'jung.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('IfQtLOpRJ2KyjDze', '相談ありがとうございます！40代で「あのとき…」と考えるの、すごく自然なことだと思います。
ぬぬはら的な結論は「忘れなくていいし、仕事を辞めなくてもいい」です。今は昔と違って、音楽を始めるハードルがかなり下がっています。
①仕事は続けたまま、週末に作曲や演奏を再開する
②動画サイトやSNSで作品を発表してみる
③社会人バンドやサークルに入る
いきなり「プロを目指す」か「きっぱり忘れる」かの二択にすると苦しくなるので、安定した収入という土台を活かして、リスクの少ない形で挑戦してみるのがおすすめです。40代から音楽活動を楽しんでいる人、実はたくさんいますよ。あのとき選んだ安定は、今のあなたの挑戦を支える武器になります！', '["f1dc013d-a55a-489d-a26e-56e1598dae17","436698e9-d5ca-45d4-8f4b-2e11ac3436b5","49bb555c-b4cf-4764-8db8-fdaa968b07ed"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('IfQtLOpRJ2KyjDze', '若いころに音楽の道をあきらめて、安定した仕事を選びました。40代になった今、あのとき挑戦していればと考えてしまいます。今からでも遅くないのか、もう忘れるべきなのか分かりません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('H7SfttNgEyG_rhmR', 'curated', 'general', '仕事も家族もあって、周りからは恵まれていると言われます。それなのに、幸せだと感じられません。何が足りないのか自分でも分からず、贅沢な悩みだと思うと誰にも言えません。', 'life', '["happiness","meaning"]', 0, 1791901440000, 1791901440000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'socrates', 0, 'きみの言う「幸せ」とは、そもそも何かね', 'ほう、それは面白い。周りの人たちは、きみが恵まれていると言う。では、その人たちは「恵まれている」とは何のことだと思っているのだろう。仕事があること、家族があること。たしかに多くの人が欲しがるものだ。だが、わたしはアテナイの街角で、財産も評判もたっぷり持ちながら、自分の魂のことは少しも気にかけていない人に何人も会ってきた。そこで、きみに尋ねたい。「幸せだと感じられない」と言うとき、きみは何を感じたいのだろうか。楽しい気分のことかね。それとも、自分は善く生きているという手ごたえのことかね。もし後者なら、足りないのは持ち物ではなく、きみの魂への気づかいなのかもしれない。贅沢な悩みだと黙っておくより、こうして問うほうが、ずっと人間らしいとわたしは思うよ。さて、きみが毎日していることの中で、きみ自身が「善い」と思えるのは、どれかね。', '["socrates.care-of-soul","socrates.examined-life"]', 'socrates.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'schopenhauer', 1, '満たされたら退屈が来る。それが人生の仕組みだ', '君は、自分の何かが壊れていると思っているようだが、そうではない。人間とは、もともとそういうふうにできているのだ。欲しいものが手に入らないうちは苦しい。手に入れば、その喜びはすぐに色あせ、今度は退屈という別の苦しみがやってくる。仕事と家族を手に入れた君が、いま退屈の側に立っているのは、むしろ当然のことだ。世間は「恵まれているのに」と言うが、彼らは持ち物と評判で幸福を測っている。だが人を幸せにするのは、何を持っているかより、その人が何であるか、つまり心の中身のほうだ。だから、新しく何かを手に入れて埋めようとするのはやめたまえ。それは次の退屈を予約するだけだ。そのかわり、音楽を一曲、何も考えずに聴く時間を持つこと。ひとりで散歩する時間を持つこと。欲を離れて何かを眺めているあいだだけ、人は少し休めるのだ。', '["schopenhauer.pendulum","schopenhauer.what-one-is"]', 'schopenhauer.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'mill', 2, '幸福は狙わず、別の目的に打ち込む中で得る', 'あなたの悩みは、わたしには他人事に思えません。二十歳のころ、わたしは自分に問いました。人生で目指してきたことが、今すぐすべて実現したら、自分は大きな喜びを感じるだろうか、と。答えは、はっきり「いいえ」でした。そこから長い憂うつの日々が始まり、わたしもそれを誰にも打ち明けられませんでした。一方で、わたしはそこから一つのことを学びました。幸福そのものを的にして狙うと、かえって外れてしまう。幸福は、他人の幸せや、何かの営みそのものに心を向けているうちに、いわば道すがら得られるものだ、と。わたしを少しずつ立ち直らせたのは、ワーズワースの詩でした。感情を耕す喜びは、量では測れない質の高い喜びです。あなたにとっての詩は何でしょう。仕事や家族の役割の外に、あなた自身の心が育つ営みを一つ選んでみてください。選ぶのは、あなた自身です。', '["mill.quality-of-pleasure","mill.individuality"]', 'mill.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'kierkegaard', 3, '足りないと感じるのは、自己が目覚めかけた印', '逆説を一つ申し上げましょう。最もありふれた絶望は、自分が絶望していることに気づいていない絶望です。そういう人は仕事を持ち、家庭を持ち、世間からは「立派にやっている」と言われています。世の中で役割を手に入れる代わりに、自分自身をどこかで失くしてしまったのに、誰も、本人さえもそれに気づかない。けれど、あなたは違います。「何かが足りない」と感じている。それは、あなたの中の自己が、まだ眠りきっていないしるしです。贅沢な悩みどころか、目を覚ましかけている人の悩みなのです。人は親や働き手といった役を立派に務めることはできても、役の束がそのまま自己になるわけではありません。わたしはキリスト者として、自己は神の前にひとりで立つとき本当の自己になると考えていますが、それを押しつけはしません。ただ一つ問わせてください。あなたはいま、あなた自身であろうとしていますか。', '["kierkegaard.despair","kierkegaard.single-individual"]', 'kierkegaard.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'jung', 4, '人生の午後には、午前と違う地図が要る', 'あなたの悩みは、贅沢どころか、人生の大切な転換点で多くの人が出会うものだと、私は考えています。人生の前半、私たちは外の世界に自分の場所をつくることに力を注ぎます。仕事に就き、家庭を築く。それは太陽が昇っていく午前の課題で、あなたはそれを立派に果たしました。けれど人生が折り返しに近づくと、太陽は向きを変えます。午前に役立った計画が、もう心を満たさなくなるのです。仕事の顔や家庭での役割、つまりペルソナとして懸命に生きてきた分だけ、生きられずに置き去りにされた自分がいるのかもしれません。その人が「何かが足りない」と呼びかけているのでしょう。最近、心に残る夢を見ませんでしたか。昔好きだったのに手放したものはありませんか。答えを急がず、その像に耳を傾けてみてください。外の務めと内なる声、その両方を抱えて生きることが、あなた自身になっていく道なのかもしれません。', '["jung.individuation","jung.persona"]', 'jung.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'dogen', 5, '幸せを待つな。いまの一事に心をこめよ', 'そなたは、幸せを感じる時を待っている。それが苦しみのもとである。悟りを修行の先に置いて待つ者は、いつまでも待つことになる。同じことだ。いつか心が満ちる時が来ると思い、いまの暮らしを、その時までのつなぎにしている。だから、いまが空しい。わたしが宋で会った老いた典座は、炎天下で自ら海藻を干していた。若い者に任せてはどうかと問うと、ほかの人がしたのでは、わたしの修行にならぬ、と答えた。いまでなければ、いつするのか、とも。そなたにも仕事があり、家族がある。それを「恵まれた持ち物」として眺めるな。今日、家族の食事を一品、心をこめて作れ。器を洗え。仕事の一つを、丁寧に仕上げよ。幸せかどうかを確かめようとするな。その営みが、そのまま道である。', '["dogen.shusho-itto","dogen.tenzo"]', 'dogen.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('H7SfttNgEyG_rhmR', 'camus', 6, '意味を探す前に、太陽と水を体で感じよう', 'きみは、幸せが何なのか分からないと言う。正直に言うと、ぼくにも分からない。世界は、ぼくたちがいちばん知りたいことに、何も答えてくれない。ぼくはそれを不条理と呼んだ。でも、だからといって、きみの人生が空っぽだということにはならない。幸せは、どこかで正しい答えを見つけたら手に入る、という類いのものじゃないんだ。岩を押し上げつづけるシーシュポスでさえ、自分の運命をはっきり見つめて引き受けるとき、幸福でありうる。ぼくが貧しいアルジェの街で育ったころ知っていた幸福は、海で泳ぐこと、太陽に焼かれること、友だちと食べることだった。どれもお金はかからない。きみの毎日にも、そういう瞬間がきっとある。今度の休みには、家族と海か川へ行って、何も考えずに水に入ってみるといい。意味はあとからでいい。体が先に知っている。', '["camus.absurd","camus.happy-sisyphus"]', 'camus.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('H7SfttNgEyG_rhmR', '「恵まれてるのに幸せじゃない」って、実はすごくよくある悩みです。贅沢なんかじゃないですよ。

人の脳は、手に入れたものにすぐ慣れるようにできています。昇給しても新しい家に住んでも、しばらくすると気分は元に戻る。これは心が壊れてるわけじゃなくて、仕様です。

なので、足りないものを外に探すより、こんなところを見直してみるのがおすすめです。
①自分だけの時間（家族でも仕事でもない時間）があるか
②最近「楽しい！」と思ったのはいつか
③疲れや睡眠不足がたまっていないか
実は③が原因のことも本当に多いです。

あと、誰にも言えないのが一番しんどいので、こうして言葉にできたのはえらい。何をしても楽しくない状態がずっと続くなら、一度お医者さんに相談するのもアリです。', '["a38cd6ee-2a67-44af-a494-e02791dc0f4d","2760624a-d7b8-4328-8784-c0ec76ef2c47","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('H7SfttNgEyG_rhmR', '仕事も家族もあって、周りからは恵まれていると言われます。それなのに、幸せだと感じられません。何が足りないのか自分でも分からず、贅沢な悩みだと思うと誰にも言えません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('B-W9MEkaohKtNZL7', 'curated', 'general', '起きてもいないことを考えて、怖くなってしまいます。病気になったら、仕事を失ったら、一人になったらと考え始めると止まりません。未来が不安で、生きていくのが怖いです。', 'life', '["future-anxiety","anxiety"]', 0, 1791901380000, 1791901380000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'seneca', 0, '苦しみの多くは来る前の思い込み。今日を生きよ', '親しい友よ、君の手紙を読んだ。病気、失職、ひとりぼっち。起きてもいないことが君を眠らせない、と。白状すれば、わたしも同じ病にかかっている。だから同じ病室の仲間として書く。
わたしたちを苦しめるものには三つある。苦しむべき以上に苦しめるもの、苦しむべき時より前に苦しめるもの、そして、まったく苦しむ必要のないものだ。君の恐れの多くは、二つ目と三つ目ではないか。恐れていたことが結局来なかった日々を、思い出してみたまえ。
生きることの最大の妨げは、明日に頼りきって今日を失う、その待ち構えだ。そこで一つ習慣を勧めたい。不安は、夜に一度だけ書き出す。備えられることは備え、それ以外は、来たときに来たものとして相手をすると決めて眠るのだ。
では、元気で。', '["seneca.time","seneca.premeditation"]', 'seneca.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'epicurus', 1, '未来は半分だけ自分のもの。必要なものは少ない', 'あなたの不安を、一つずつほどいてみましょう。まず覚えておきたいのは、未来は、まったくわたしたちのものでもなく、まったくわたしたちのものでないわけでもない、ということです。必ず来ると当てにするのも、必ず来ないと絶望するのも、どちらも当たっていません。
次に、仕事を失ったら、という恐れ。生きるのに自然で必要なものは、実はそれほど多くありません。空腹のときのパンと水が、どれほどおいしいか。自然で必要なものは手に入りやすく、手に入りにくいのは、たいてい必要でないものです。
そして、一人になったら、という恐れ。だからこそ、今のうちに友を大切にしましょう。限りあるこの世の不幸の中で、友情ほど心を安らかにしてくれるものはありません。
短く覚えておいてください。必要なものは少ない。友がいれば足りる。', '["epicurus.desires","epicurus.friendship"]', 'epicurus.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'buddha', 2, 'まだ来ない矢を、自分に射るのをやめる', 'あなたの怖さを、まずそのまま受けとめます。病、別れ、暮らしの苦しみ。それらは、生きる者に起こりうることです。わたしもそれを否定しません。
わたしは弟子たちに、二本の矢の話をしました。痛みに出会ったとき、人は一本目の矢に射られます。けれど、嘆き、悲しみ、思い悩むことで、自分にもう一本の矢を射てしまう。そうして二重の苦しみを受けるのです。
あなたはいま、まだ一本目の矢も飛んできていないのに、二本目、三本目の矢を自分に射ているのかもしれません。その矢は、何をつかもうとして生まれているのでしょう。変わらない明日を握りしめたい、という思いではないでしょうか。
不安が湧いたら、いま吸っている息、吐いている息を、静かに観察してみなさい。いま、ここに矢は刺さっていますか。ととのえられたあなた自身が、あなたの拠りどころになります。', '["buddha.impermanence","buddha.self-reliance"]', 'buddha.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'zhuangzi', 3, '明日の不幸も、立場が変われば笑い話かも', 'こんな話がある。麗姫という娘が、晋の国へ連れて行かれることになった。娘は泣いて泣いて、着物の襟がびっしょり濡れるほどだった。ところが王の宮殿に着き、王と同じ寝台で眠り、おいしいごちそうを食べるようになると、あのとき泣いたことを悔やんだそうだ。
きみは、まだ見ぬ明日を思って襟を濡らしている。病気、失職、ひとりぼっち。でも、それが本当に不幸かどうか、いまのきみに分かるだろうか。その「不幸」の物差しは、いまいる井戸の中から見た物差しかもしれないよ。
限りのない「もしも」を、限りある命で追いかけていたら、くたびれてしまう。追いかけるのはやめて、今日は大きな木の下で昼寝でもしたらどうだい。明日のことは、明日のきみが笑っているかもしれない。', '["zhuangzi.equality"]', 'zhuangzi.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'pascal', 4, '未来ばかり見て今を生きない。弱さを知る者は偉大', 'わたしたちは現在に生きていない。過去を思い、未来を先回りして、ほとんど現在のことを考えない。だから、わたしたちは決して生きているのではなく、生きようと望んでいるだけなのだ。これは、あなただけの病ではない。わたし自身の病でもある。
人間は弱い。病はいつでも来うるし、職も人も失いうる。あなたの恐れは、根拠のない妄想ではない。
だが、あなたは自分の弱さを知っている。宇宙はあなたを押しつぶせても、そのことを何も知らない。弱さを知っていること、そこに人間の偉大さがある。恐れているあなたは、惨めであると同時に、偉大でもあるのだ。
理性は未来を計算し続ける。だが理性の最後の一歩は、理性を超えるものがあると認めることだ。今日という一日を、計算でなく、心で受けとってみてほしい。', '["pascal.misery-greatness","pascal.heart"]', 'pascal.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'kierkegaard', 5, '不安は自由のしるし。正しく不安になることを学べ', 'あなたの怖さは、はっきりした何かへの恐れとは少し違うように思います。病気、失職、孤独。どれも、まだ起きていない「かもしれない」です。わたしがヴィギリウス・ハウフニエンシスという名で書いた『不安の概念』では、不安は、何にでもなりうるという可能性の前で人が感じるめまいとして描かれています。
逆説めきますが、不安を感じるのは、あなたが石ではなく、自由な精神だからです。石は明日を恐れません。そして同じ本は、正しく不安になることを学んだ人は最も大切なことを学んだのだ、とも言います。不安から逃げるのでも、不安に呑まれるのでもなく、その前に立って、自分を引き受けることです。
わたしは、そのとき人がひとりで神の前に立つと信じていますが、それを押しつけはしません。ただ問いたいのです。あなたはいま、あなた自身であろうとしていますか。', '["kierkegaard.anxiety","kierkegaard.single-individual"]', 'kierkegaard.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('B-W9MEkaohKtNZL7', 'russell', 6, '心配は時間を決めて最悪まで考え、あとは外を見よ', '心配というものは、たいてい夜中の二時に、何の役にも立たない形でやってきます。賢い人は、考えて意味があるときにだけ悩みを考え、それ以外のときは別のことを考える。夜なら、何も考えないことです。
では、考えるべきときに、きちんと考えてみましょう。病気になったら、仕事を失ったら、一人になったら、起こりうる最悪の事態は何か。紙に書いて、目をそらさずに見つめてください。そのうえで、それでも暮らしていける理由を探す。そういう理由は、たいてい見つかります。治療を受ける、職を探す、人を頼る。最悪にも、たいてい次の手があるものです。
それから、関心を自分の外へ向けてください。庭の植物でも、星でも、歴史でもかまいません。宇宙の長い歴史から見れば、私たちの心配はずいぶん小さなものです。もっとも、そう言う私も、眠れない夜を過ごしたことはありますが。', '["russell.worry","russell.impersonal-interests"]', 'russell.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('B-W9MEkaohKtNZL7', '起きてもいないことが怖くなる気持ち、ぬぬはらもめちゃくちゃ分かります。生きるのしんどい時ありますよね…。

まず知っておいてほしいのは、不安になりやすいのは性格の弱さじゃなくて、危険を先回りして察知しようとする心の働きだということ。昔の人類にとっては、心配性な人ほど生き残りやすかったはずです。あなたの心は真面目に仕事をしているだけなんです。

おすすめは、不安を紙に全部書き出して「今できること」と「どうしようもないこと」に分けること。できることは一つだけやる。どうしようもないことは「メモしたから今日はおしまい」で切り上げる。頭の中で回し続けるより、ずっと軽くなります。

眠れない日が続くなら、お医者さんに相談するのも全然アリです。人生ハードモードだけど、一緒に気楽に攻略していきましょう！', '["59f22efc-955c-4189-a5ea-eea0cda16dea","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('B-W9MEkaohKtNZL7', '起きてもいないことを考えて、怖くなってしまいます。病気になったら、仕事を失ったら、一人になったらと考え始めると止まりません。未来が不安で、生きていくのが怖いです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('Wznc994QG7gO3k1e', 'curated', 'general', '夜、布団に入ると将来のことや昼間の失敗を考えてしまい、眠れなくなります。考えすぎだと分かっているのに止められず、寝不足で次の日もぼんやりしています。', 'health', '["sleep","anxiety"]', 0, 1791901320000, 1791901320000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'seneca', 0, '振り返りは寝る前に一度だけ。裁いたら閉じる', '君の手紙を読んだ。寝床に入ると、将来のことと昼の失敗が代わる代わる押し寄せる、と。親しい友よ、わたしも同じ病室の患者だ。だから、わたしの習慣を一つ分けよう。師セクスティウスにならって、わたしは灯りが消え、妻もわたしの癖を知って黙ったあと、その日一日を振り返る。言葉と行いを一つずつ吟味し、自分に何も隠さない。そして最後に『それは二度とするな。今日のところは許そう』と言う。この裁きのあとの眠りの、なんと穏やかで深いことか。君の苦しみは、振り返ることにあるのではない。裁判を開いたまま判決を出さずに、眠ろうとしていることにある。一日の失敗は、寝る前に一度だけ短く裁き、許して閉じたまえ。将来のことは、恐れの影が実物より大きく見えているだけかもしれない。影の大きさは、朝の光の下で測り直せばよい。では、元気で。', '["seneca.evening-review"]', 'seneca.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'russell', 1, '悩みは昼に考え抜き、夜は何も考えないと決める', '寝床の中で将来と失敗を考えるのは、たいへん人間的で、たいへん非効率な習慣です。夜中の頭は、問題を解くには最も不向きな道具だからです。私は『幸福論』の疲れについての章で、賢い人は、考えることに目的があるときだけ悩みごとを考え、それ以外のときは別のことを考え、夜であれば何も考えない、と書きました。そこで提案です。悩みごとには、昼間に時間を決めて真剣に向き合いましょう。最悪の場合どうなるか、そのときどうするか。そこまで考えて結論を出したら、新しい事実が出てこないかぎり蒸し返さない。昼の失敗も同じです。長い歴史の中で見れば、あなたの今日の失敗が占める大きさは、控えめに言っても、たいしたものではありません。夜、それでも考えが寄ってきたら『その件は明日の午後に検討予定』と事務的に告げて、お引き取り願いましょう。眠る前には、悩みと無関係な本でも楽しんでください。', '["russell.worry","russell.impersonal-interests"]', 'russell.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'montaigne', 2, '考えは追い払わず、そっと今いる場所へ連れ戻す', 'わたしは想像の力にひどく弱いたちで、人が咳きこむのを聞くだけで、自分の胸や喉までむずがゆくなる人間です。だから、夜の寝床で、まだ来ない将来や済んだ失敗が大きくふくれあがる感じは、よく分かります。わたしは『経験について』に、ひとりで果樹園を歩いていて考えがよそへさまよい出たら、そのつど連れ戻して、散歩と果樹園と、ひとりの心地よさと、わたし自身のところへ戻すのだ、と書きました。追い払うのではなく、連れ戻すのです。考えはどうせまた出かけていきますから、そのたびに、寝具の温かさや自分の呼吸のところへ、そっと戻せばいい。昼の失敗を数えて、今日はだめな一日だったと嘆くなら、わたしはこう言いたい。なんだって、あなたは今日を生きたではありませんか。それこそ、いちばん立派な仕事です。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.enjoy-life","montaigne.self-portrait"]', 'montaigne.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'plato', 3, '眠る前に馬をなだめ、理性を善い思いで満たす', 'あなたの言う『考えすぎ』とは、あなたの中のどこが考えているのでしょうか。わたしは、魂には理性と、怒りや誇りをつかさどる気概と、欲しがる欲望の三つの部分があると考えました。『パイドロス』では、それを御者と二頭の馬にたとえています。夜、寝床の中で暴れているのは、御者ではなく馬のほうかもしれません。昼の失敗を責め立てるのは、恥じて自分に怒る馬。将来へと駆け出すのは、あれも失うまい、これも手に入れたいと求める馬です。わたしが書いた『国家』の対話で、ソクラテスはこう語りました。眠る前には、欲望を飢えさせも満腹させもせず、気概をなだめて怒りを抱えたまま眠らないようにし、理性を目覚めさせ、美しい言葉と考えでもてなしてから眠るのがよい、と。ですから寝る前には、失敗を数える代わりに、今日出会った美しいものや善いと思えたことを、一つ思い出してください。御者が手綱を取り戻せば、馬も静かになります。', '["plato.tripartite-soul"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'epicurus', 4, '未来は半分だけ自分のもの。過去は感謝で思い出す', '寝床の中で、まだ来ない将来と、もう済んだ昼の失敗が、かわるがわるあなたを訪ねてくるのですね。一つずつ、ほどいてみましょう。まず将来について。未来は、まったくわたしたちのものでもなければ、まったくわたしたちのものでないわけでもありません。だから、必ず来ると当てにすることも、決して来ないと絶望することもいらないのです。そして今夜、寝床の中でできることは何もありません。次に失敗について。起きてしまったことを、起きなかったことにはできません。そう知ることが、かえって心を軽くします。そのうえで、過ぎた日々のよいことを、感謝して思い出すのです。わたしは病の痛みの中でも、友と交わした語らいを思い出して、心を支えました。眠る前に、今日のパンのおいしさや、誰かと笑ったひとときを一つ思い出してごらんなさい。覚えておくための短い教えを渡しましょう。未来は半分だけ、過去は感謝で、今夜は眠りで。', '["epicurus.ataraxia","epicurus.friendship"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'kierkegaard', 5, '夜は後ろを理解しすぎる時間。生きるのは朝から', '夜の寝床で、あなたは二つの方向へ同時に引っぱられている。後ろへは昼の失敗へ、前へはまだ来ない将来へ。夜のあなたは、過去を何度も理解し直そうとし、さらに将来まで、まるでもう終わったことのように理解しようとしている。けれど将来は、理解するものではなく、生きるものです。将来を思うと胸がざわつく、その不安を、わたしは自由のめまいと呼びました。何にでもなりうる可能性の深みをのぞきこむとき、人はめまいを覚える。ですから、その不安はあなたが壊れている印ではなく、あなたが自由な一人の人間である印なのです。正しく不安になることを学んだ人は、それによって育てられる。ただ、めまいは深みを見下ろしている間に起こるもの。歩き出すのは、明日の朝です。さて、あなたは今夜、考えることで、生きることを先延ばしにしていませんか。', '["kierkegaard.anxiety"]', 'kierkegaard.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('Wznc994QG7gO3k1e', 'dogen', 6, '昨日も明日も、いまにはない。ただ横たわれ', 'そなたは、寝床の中で昨日と明日を行き来している。だが、いまそなたがいるのは、寝床の中のこの時だけだ。薪は燃えて灰となる。だが薪は薪のありように住し、前があり後があっても、その前後は断ち切られている。昼の失敗は、もう昼のものだ。将来は、まだ来ぬものだ。いまの一時に、それらはない。考えを止めようと力むな。止めようとする心が、また一つの考えとなる。草は嫌われても生える。考えもまた、嫌っても浮かぶ。ただ、それだけのことだ。考えが浮かべば浮かぶまま、去れば去るまま。追わず、払わず、相手にせぬ。ただ息をし、ただ横たわれ。眠りを得ようと願って横たわるのでもない。横たわることが、そのまま、いまのそなたの一事である。そして朝が来たら、顔を洗い、目の前の一事に心を尽くせ。', '["dogen.uji"]', 'dogen.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('Wznc994QG7gO3k1e', '夜の考えごと、分かります…ぬぬはらも布団に入ってから昔の失敗を急に思い出して、叫びたくなるタイプです。

夜は体も頭も疲れていて、考えがネガティブ寄りになりがちです。なので、夜に出た結論はだいたい信用しなくていいです。

おすすめは
①寝る前に、気になることを紙に全部書き出す（頭の外に置いておくイメージ）
②布団でスマホを見るのはやめて、退屈な音声や催眠音声を流す
③どうしても眠れない日は、一度布団から出てぼーっとする
です。眠れない日が続いて昼の生活にひびくようなら、病院で相談するのも全然ありです。睡眠は根性でどうにかするものじゃないので、道具に頼っていきましょう。', '["4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d","436698e9-d5ca-45d4-8f4b-2e11ac3436b5"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('Wznc994QG7gO3k1e', '夜、布団に入ると将来のことや昼間の失敗を考えてしまい、眠れなくなります。考えすぎだと分かっているのに止められず、寝不足で次の日もぼんやりしています。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('LKYR1ZVNW3IBw7YE', 'curated', 'general', '気がつくと何時間もSNSを見ています。見たあとは疲れて、他人と比べて落ち込むのに、やめたいと思ってもやめられません。', 'health', '["addiction","inferiority","jealousy"]', 0, 1791901260000, 1791901260000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'pascal', 0, '見続けるのは、自分から目をそらす気晴らし', 'あなたの言う、何時間も見続けてしまうものは、わたしの時代の狩りや賭けごとと同じものに見えます。狩りに行く人は、兎が欲しいのではありません。兎を差し出されたら、かえって退屈するでしょう。欲しいのは、追いかける騒ぎそのものなのです。なぜか。静かに一人でいると、自分の惨めさや、いつか死ぬ身であることを考えずにはいられないからです。だから人は気晴らしに逃げる。わたしも例外ではありません。見たあと疲れて落ち込むのは、気晴らしが、目をそらしたものを何ひとつ解決しないからです。一つ試してください。手に取りたくなったとき、ほんの少しだけ、何もせずに座ってみる。そのとき胸に浮かぶ不安こそ、あなたが本当に向き合うべきものです。人間は弱い。しかし、その弱さを知ることができる。そこに、あなたの尊さがあります。', '["pascal.divertissement","pascal.misery-greatness"]', 'pascal.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'plato', 1, '壁に映る影から振り向き、魂の向きを変える', 'あなたの言う、幸せそうな他人の姿とは何だろうか。わたしが書いた対話『国家』で、ソクラテスはこんな話をしている。洞窟の奥に縛られた人々が、壁に映る影だけを見て、それを本物だと思いこんで暮らしている。彼らは影を見分ける腕を競い、うまい者をほめそやし合う。あなたが何時間も見つめ、比べて落ち込んでいるものも、人の暮らしそのものではなく、選ばれ、切り取られて映った影なのかもしれない。影と比べて、生身の自分が見劣りするのは当然だ。わたしは、教育とは魂の向きそのものを変える技だと考える。体ごと振り向いて、洞窟の外の光、つまり、あなたが本当に美しい、善いと思えるものの方へ目を向けること。はじめはまぶしくてつらい。だから少しずつでよい。わが師ソクラテスなら、こう問うだろう。あなたにとって、本当に善いものとは何かね、と。', '["plato.cave","plato.idea"]', 'plato.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'epictetus', 2, '他人の暮らしは君次第でない。見る判断は君次第だ', '人間よ、君は何を眺めて落ち込んでいるのか。他人の食卓か、他人の評判か。それは君次第のものか、そうでないものか。そうでないものだ。君次第でないものを欲しがれば、君は必ず乱される。では、君次第のものは何か。目に飛びこんでくる印象に、すぐ同意するかどうかだ。「あの人は幸せで、わたしは劣っている」という印象が浮かんだら、こう言え。待て、おまえは印象にすぎない、見えているとおりのものか確かめさせろ、と。「でも先生、気がつくと何時間も見ているのです」。そうだろう。だから訓練が要るのだ。オリンピックの選手も、一日で体をつくりはしない。今日は一つだけ練習せよ。手に取る前に「これは自分次第か」と一度だけ問う。それができたら、明日は二度だ。まず小さなことから、今日始めよ。', '["epictetus.control","epictetus.impressions"]', 'epictetus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'buddha', 3, '断つか溺れるかでなく、渇きをよく観察する', '見たあとに疲れ、落ち込むのに、手が止まらない。その苦しみを、まずそのまま受け止めましょう。あなたを責める必要はありません。その苦しみは、何をつかもうとして生まれているのでしょう。もっと見たい、取り残されたくない、自分も認められたい。わたしはこれを渇きと呼びました。傷をかく人が、かくほど傷を深くしながら、かくことに快さを覚えるように、渇きは満たすほどに増していきます。けれど、無理に断とうとして自分を痛めつけるのも、また一つの極端です。快楽にも苦行にも偏らない、中ほどの道があります。手に取りたくなったとき、その衝動がどう起こり、どれほど続き、どう消えていくかを、静かに観察してみなさい。衝動もまた、生じては滅びる移ろうものです。そして他人の暮らしではなく、自分の歩みを拠りどころにしなさい。', '["buddha.four-truths","buddha.middle-way"]', 'buddha.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'schopenhauer', 4, '評判より、自分の内にある楽しみを育てよ', '君の言う、何時間も他人の暮らしを眺めることは、人間の古い病の新しい形にすぎない。人の幸せを左右するのは、第一にその人自身のあり方、つまり健康や気質や心の豊かさだ。持ち物はその次で、他人の頭の中で自分がどう映っているかは、いちばん後だ。ところが世間の人間は、この順序をまるごと逆さまにして、他人の目に映る姿ばかりを気にしている。比べて落ち込むのは当然だ。人が他人に見せる姿は、いつの時代も、見せたい部分だけなのだから。もう一つ。人生は苦痛と退屈のあいだを揺れ動く。君は退屈を埋めるために眺めているのかもしれないが、それで埋まる退屈ではない。退屈を本当に和らげるのは、自分の内にある楽しみだ。音楽を一曲、何もせずに聴いてみたまえ。慰めは言わない。だが、苦しみは賢く減らせる。', '["schopenhauer.what-one-is","schopenhauer.pendulum"]', 'schopenhauer.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'russell', 5, '比べる目を、外の世界への興味に向け替える', 'あなたの悩みには、私が『幸福論』で論じたねたみと、自己への没頭が、少しずつ混ざっているように思えます。他人と比べるとき、関心はじつは他人ではなく、いつも自分に向いています。あの人に比べて私は、と。ねたみ深い人は、自分が持っているものから喜びを得る代わりに、他人が持っているものから苦しみを得る。これはずいぶん割の悪い取引です。では、どうするか。意志の力だけで見るのをやめようとしても、空いた時間にまた戻ってしまうでしょう。必要なのは、空いた心を埋める、もっとおもしろいものです。仕事や悩みと関係のない興味を一つ持ってください。星の名前でも、庭の草花でも、町の古い歴史でも構いません。広い世界の中で見れば、比べていたものの小ささも分かってきます。今週、散歩の途中で、名前を知らなかったものを一つ調べてみませんか。', '["russell.self-absorption","russell.impersonal-interests"]', 'russell.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('LKYR1ZVNW3IBw7YE', 'miki', 6, '嫉妬は何も作らない。自分の手で何かを作れ', '比べて落ち込む心を、私は嫉妬と呼ぼう。嫉妬は、手の届かない遠い人には向かわない。自分もそうなり得たと思える、少し上の人に向かう。そして量で比べる。どれほど見られたか、どれほど持っているか。嫉妬はいつも忙しい。君に何時間も眺めさせるのは、この忙しさである。しかし嫉妬は何一つ生み出さない。見終わったあと疲れて空しいのは、何も生まれていないからである。また、成功と幸福を取り違えてはならない。成功は量であり、他人と比べられる。幸福は質であり、その人だけのものである。君の言う他人の見せ合いに映っているのは、多くは成功の方だ。手を動かして何かを形にするとき、比べる心は静まる。料理一皿、手紙一通、短い文章一つでよい。眺める時間の一部を、作る時間に変えることである。', '["miki.jealousy","miki.success"]', 'miki.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('LKYR1ZVNW3IBw7YE', 'SNS疲れ、めちゃくちゃ分かります…。でも、やめられないのはあなたの意志が弱いからじゃないです。

✦やめられない理由
SNSは「もうちょっとだけ」が止まらないように作られています。無限スクロールも通知も、人の注意を奪うための仕組み。プロが本気で作った罠に、素手で勝てなくて当然なんです。

✦比べて落ち込む理由
流れてくるのは他人の人生のハイライトだけ。こっちは自分のすっぴんの日常と比べてるので、勝てるわけがないんですよね。

✦ぬぬはら流の対策
・アプリをホーム画面の奥に移す
・寝る前はスマホを別の部屋で充電する
・見る時間を決めてタイマーをかける

全部じゃなくて、どれか一つで大丈夫。時間を少しずつ取り戻していきましょう。', '["b302d345-6def-4a65-9c25-c568ffcff306","29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","f225606d-251b-4e70-b278-84a390650a8d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('LKYR1ZVNW3IBw7YE', '気がつくと何時間もSNSを見ています。見たあとは疲れて、他人と比べて落ち込むのに、やめたいと思ってもやめられません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('G3rKgu0yuJOQiNwh', 'curated', 'general', '少し注意されたり、緊張したりするだけで、人前ですぐに涙が出てしまいます。泣きたくないのに止められず、大人なのに恥ずかしいです。', 'health', '["body","others-eyes"]', 0, 1791901200000, 1791901200000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'alain', 0, '涙は体のこと。まず長く息を吐き、肩を落とす', '名馬ブケファラスは、誰にも乗りこなせない暴れ馬でした。若いアレクサンドロスは、馬が自分の影におびえているのだと見抜き、馬の顔を太陽に向けて落ち着かせたのです。あなたの涙も、心の弱さのせいではないと私は思います。注意されたり緊張したりすると、体は息を止め、肩とのどをこわばらせる。そのこわばりが、涙を押し出すのです。だから「泣くまい」と力むのは逆効果です。力めば力むほど、のどは締まる。かわりに、体のほうに働きかけましょう。人前に出る前に、大きく伸びをする。注意を受けている間は、息を長く吐き、肩を落とし、足の裏で床を感じる。それでも涙が出たら、窓の外の遠くを見る。気分はほうっておけば沈みますが、体の構えは、私たちが自分で選べるのです。', '["alain.bucephalus"]', 'alain.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'epictetus', 1, '涙は君次第でない。『恥だ』という判断は君次第', '人間よ、まず分けてみよう。注意された瞬間に涙が出ること、それは君次第のものか。違う。突然の雷鳴を聞けば、賢者でさえ一瞬青ざめ、心が揺れる。それは心が同意する前に起こる動きで、恥ずべき悪徳ではないと、わたしは教えてきた。では、君次第のものは何か。涙のあとに浮かぶ「大人なのに泣くなんて恥ずかしい」「みんなに笑われた」という印象に、すぐ同意するかどうかだ。「でも先生、人前で泣くのはやはりみっともないのです」。そうか。では、それは誰の判断だ。印象に向かって、こう言ってみるがいい。おまえは印象にすぎない、見えているとおりのものではない、と。今日から小さく練習せよ。涙が出たら、拭いて、一つ息をして、話の続きを聞く。それだけでよい。涙を止めるのではなく、判断を正すのだ。', '["epictetus.impressions","epictetus.control"]', 'epictetus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'pascal', 2, '揺れない大人は天使のまね。揺れる葦のままでいい', '人間は、ほんの少しの言葉で揺れてしまう、弱い葦です。注意された一言で涙がこぼれる。それは惨めなことでしょうか。たしかに、惨めです。けれど、わたしたちはみな、同じように惨めなのです。わたしも例外ではありません。そして人間の偉大さは、まさに、自分が弱いと知っているところにあります。涙を恥じているあなたは、自分の弱さを見つめている。そこにすでに、考える者の尊さがあります。危ういのは、何があっても動じない完全な大人になろうとすることです。人間は、そのような存在にはなれません。無理にそうなろうとすると、かえって自分を責め、荒れていきます。涙には、理性ではうまく説明できない心の理由があるのでしょう。その理由を急いで消さず、弱さを知る者として、静かに付き合ってみてください。', '["pascal.misery-greatness","pascal.thinking-reed"]', 'pascal.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'laozi', 3, '涙は柔らかさ。柔らかいものは折れない', '生きている草木は、柔らかい。
枯れた草木は、かたくこわばる。

涙が出るのは、あなたが柔らかいからだ。
恥じることはない。

止めようと強く握るほど、こぼれる。
こらえようとかたく閉じるほど、あふれる。

水を見なさい。
世の中に、水より柔らかく弱いものはない。
けれど、かたい石をうがつのに、水にまさるものもない。

注意されたら、流れればよい。
泣いたら、泣いたままで、話を聞けばよい。
涙は、やがて止まる。
水は低い所へ流れて、静かになる。

大人とは、かたくなる人のことではない。
柔らかいまま、折れない人のことだ。', '["laozi.soft-weak","laozi.water"]', 'laozi.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'nietzsche', 4, '「大人は泣かない」は誰の物差しだ。自分に恥じるな', '君は「大人なのに恥ずかしい」と言う。では問おう。大人は泣かない、という物差しは、誰が作ったものだ。君自身か、それとも周りの目か。わたしは古代ギリシャの詩を学んだ者だが、ホメロスの英雄たちは、人前で泣いた。オデュッセウスは歌を聞いて涙を抑えられず、アキレウスは友の死に身をよじって泣いた。誰も彼らを弱いとは言わなかった。涙は、君の中で何かが強く動いている証だ。それを恥とするのは、借りものの価値だ。わたしは書いた。自由を手にしたしるしとは、もはや自分自身に対して恥じないことだ、と。涙もろい自分を、しぶしぶ受け入れるのではない。それも含めて、これがわたしだ、と言え。そう言えたとき、人の前で泣くことは、もう君を縛らない。', '["nietzsche.amor-fati"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'shinran', 5, '泣いてしまう身のまま、すでに抱きとられている', '泣きたくないのに、涙が出てしまう。そのことを、あなたは恥ずかしいと思っておられるのですね。この親鸞もまた、思うようにならない身を抱えて生きてきました。怒りも、欲も、ねたみも、断とうとして断てなかった者です。比叡山で長く修行しても、自分の力では心をととのえきれませんでした。ですから、あなたの涙を、だらしないとは少しも思いません。わたしたちは、自分のはからいで、立派な大人になりきることはできない身なのです。けれど、そういう身のまま、阿弥陀仏の願いに抱きとられている。わたしはそう受けとめてきました。涙が出たら、出たままでよいのです。自分で自分を責めるはからいを、少しずつ手放してみてください。おのずから、肩の力が抜けていくこともありましょう。', '["shinran.bonbu","shinran.jinen"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('G3rKgu0yuJOQiNwh', 'jung', 6, '涙は、仮面の下の自分からの知らせかもしれない', '社会の中で、私たちはみな役割に合わせた仮面をかぶります。落ち着いた大人、きちんとした働き手。それは生きるのに必要なものです。けれど、仮面と自分をあまりに同じものと思いこむと、仮面の下で生きられていない部分が、思いがけない形で顔を出します。注意を受けたり、人前で緊張したりするのは、ちょうど仮面がいちばん試される場面ですね。あなたの涙は、その下にいる、まだ十分に言葉をもらえていない自分からの知らせなのかもしれません。悔しさなのか、怖さなのか、それとも長く我慢してきた何かなのか。これは仮説にすぎません。涙を敵として押さえこむより、泣いたあとで「いま、何を感じていたのだろう」と書きとめてみてください。対立する二つを抱えて生きることが、人が全体になっていく道なのです。', '["jung.persona","jung.shadow"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('G3rKgu0yuJOQiNwh', '涙が勝手に出てしまう悩み、実はけっこう多くの人から相談が来ます。あなただけじゃないので安心してくださいね。

涙は、気持ちが真剣に動いているサインでもあります。注意をちゃんと受け止めようとしている人ほど、出やすいのかもしれません。

できそうな対策としては、
①涙が出た場面をメモして、パターンを探す
②緊張する場面の前に、ゆっくり息を吐く練習をしておく
③近くの人には「緊張すると涙が出ちゃうんです」と前もって話しておく
あたりがおすすめです。先に言っておくだけで、周りも自分もびっくりしなくなりますよ。

泣いてしまっても、あなたの価値は少しも下がりません。それより、泣きながらでも話を聞ける自分をほめてあげてください。', '["5fd10b80-4205-41df-94b7-3bc2e8730a52"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('G3rKgu0yuJOQiNwh', '少し注意されたり、緊張したりするだけで、人前ですぐに涙が出てしまいます。泣きたくないのに止められず、大人なのに恥ずかしいです。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('d6ukiRhgDhKUxC9A', 'curated', 'general', '持病があり、年々できないことが増えていきます。周りの人が普通にできることをあきらめるたびに、自分の価値まで減っていくように感じます。', 'health', '["illness","self-esteem"]', 0, 1791901140000, 1791901140000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'epictetus', 0, '病は体の妨げ。君の意志の妨げではない', '人間よ、まず区別せよ。体は君次第のものか、そうでないものか。そうでないものだ。病も、できることの数も、人の目も、君次第ではない。では、君次第のものは何か。それをどう判断し、何を選び、どう応じるか。それだけだ。
病気は体の妨げではあるが、意志の妨げではない。脚が不自由なのは脚の妨げであって、意志の妨げではない。
「でも先生、できないことが増えるたびに、自分の価値が減っていくのです」。そう感じるのは無理もない。だが、その判断を一度吟味しよう。君は自分の価値を、走れること、人並みに働けることに置いていなかったか。それらは君のものではなく、預かりものだ。預かりものを返したからといって、君自身が減るわけではない。君の本当の自分は、意志のほうにある。そこは何ひとつ奪われていない。
まず小さなことから練習せよ。今日、何かをあきらめるとき、「これは体のことで、わたしのことではない」と一度言ってみるのだ。', '["epictetus.prohairesis","epictetus.control"]', 'epictetus.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'kant', 1, '人には値段でなく尊厳がある。能力で減らない', 'まず原則を立てよう。この世のものは、値段を持つか、尊厳を持つかのどちらかである。値段を持つものは、同じ値打ちの別のもので置き換えられる。だが、あらゆる値段を超え、何ものとも置き換えのきかないもの、それが尊厳であり、人間の人格がそれにあたる。
では、君の場合に当てはめよう。君は、できることが減るたびに、自分の価値が減ると感じている。だがそれは、人間を、何ができるか、どれだけ役に立つかという値段で測る見方だ。その物差しを他人に当てはめたらどうなるか。病に伏した友を、君は値打ちの下がった人だと考えるだろうか。考えないはずだ。ならば、同じ物差しを君自身に当ててはならない。
わたしが立てた原則は、他人の人格だけでなく、君自身の人格のうちにある人間性にも向けられている。それを認めるのは、ほかの誰でもなく、君自身の理性である。', '["kant.dignity"]', 'kant.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'buddha', 2, '「できるわたし」への執着を、ゆるめてみる', '体が思うように動かなくなっていく。その苦しみを、わたしはそのまま受け止めたいと思います。わたしも年老いたとき、弟子に、自分の体は革ひもで縛ってやっと動いている古い車のようだと話しました。老いも病も、生まれた者には避けられない苦しみの一つです。
そのうえで、一緒にたどってみましょう。あなたの苦しみは、何をつかもうとして生まれているのでしょう。「人並みにできるわたし」「役に立つわたし」。それを変わらない「わたし」として握りしめるほど、それが崩れるたびに、自分そのものが減っていくように感じるのではないでしょうか。
よく観察してみなさい。体にも、できることにも、いつまでも思いどおりになる「わたし」は見つかりません。それは、あなたに価値がないという意味ではありません。価値をそこに縛りつけなくてよい、という意味です。
今日、できたことを一つ、静かに数えてみなさい。比べずに、ただ、それがあったことを。', '["buddha.non-self","buddha.four-truths"]', 'buddha.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'adler', 3, '価値はできることの数でなく、貢献の感覚に', 'わたし自身、子どものころは体が弱く、元気に走り回る兄をうらやんで育ちました。ですから、周りが普通にできることをあきらめるつらさは、少しは分かるつもりです。
だれでも劣等感を持っています。体の弱さは、それを強く感じさせるでしょう。けれど劣等感そのものは、よりよく生きようとする力のばねにもなります。気をつけたいのは、それを「病気だから、わたしには価値がない」という結論に使ってしまうことです。
わたしは人の価値を、何ができるかではなく、仲間の一員として何かを分かち合えているかに見ます。話を聞く、感謝を伝える、自分の経験を誰かに教える。体が思うように動かなくても、できる貢献はたくさんあります。
あなたは、本当はどうしたいのですか。今の体でできる、誰かのための小さなことを、一緒に一つ探してみませんか。体のつらさが強いときは、主治医にも遠慮なく相談してください。', '["adler.inferiority","adler.social-interest"]', 'adler.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'miki', 4, '成功は量で比べられる。幸福は比べられない', '君は、周りの人ができることと自分を比べて、価値が減っていくと言う。だが、その比べ方そのものを疑ってみたい。
成功は量的なものである。どれだけできたか、どれだけ持っているか。だから他人と比べられ、順位がつく。それに対して幸福は質的なものであり、各人に独自なものである。人と並べて測ることのできないものである。成功と幸福を同じものと見るようになって、人は幸福が何であるかを分からなくなった。君の苦しみの一部も、そこから来ているのではないか。
幸福は持ち物ではない。脱いだり着たりする外套のようなものではなく、その人自身と一つになった人格である。それは機嫌のよさや、人への丁寧さや、親切として、周りの人に伝わっていく。できることが減っても、それは減らない。
比べる物差しを、一度下ろしてみることである。', '["miki.success","miki.happiness"]', 'miki.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'kenko', 5, '満開だけを花と呼ぶのは、浅い見方です', '満開の桜と、雲ひとつない満月ばかりを喜ぶのは、どうも浅い見方のように思われます。咲く前の梢や、花の散りしおれた庭、雨に隠れた月を思いやることにこそ、深い味わいがあるものです。
周りの人が普通にできることを数えて、自分の価値を測るのは、満開の花だけを花と呼ぶようなもの。できないことが増えたあなたにしか見えないものが、きっとあるはずです。ゆっくりしか歩けない人だけが気づく道ばたの草、人の手を借りたときに知る親切。そういうものを味わえる人は、なかなかいません。
それに、世の中は定めのないもの。達者な人にも、明日のことは分かりません。だからこそ、あれもこれもと嘆くより、本当に大事な一つを決めて、今日のうちに手をつけるのがよいでしょう。先延ばしにしてはいけません。あなたにとって、それは何でしょうか。', '["kenko.imperfect-beauty","kenko.one-thing"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('d6ukiRhgDhKUxC9A', 'montaigne', 6, '病と喧嘩せず、話し合いながら暮らす', 'わたしは腎臓の石という持病と、長いあいだ付き合ってきました。発作が来ると、のたうち回るほど痛い。年とともに、体はあれこれを許してくれなくなりました。正直に言えば、最初はひどく腹を立てたものです。
けれど、わたしはやがて、病と口論するのをやめて、話し合うようになりました。病はわたしから少しずつ何かを取り上げていきますが、そのおかげで、残ったものをいっそう味わうようになったのです。痛みのない一日は、それだけでごちそうです。散歩も、食事も、友との会話も、以前より上等に感じられます。
周りの人と比べて自分の値打ちを測るのは、わたしにはどうも割に合わない勘定に思えます。人は誰でも、人間というもののすべての形を備えている、とわたしは書きました。できることの数で、人間の値打ちが決まるとは思えないのです。これはわたしの試みにすぎません。あなたはあなたの判断で。', '["montaigne.enjoy-life","montaigne.self-portrait"]', 'montaigne.q4');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('d6ukiRhgDhKUxC9A', 'できないことが増えていくのは、本当にしんどいですよね…。持病と付き合いながら毎日を過ごしているだけで、ぬぬはら的にはもう十分えらいです。

「価値が減る」と感じる理由を整理してみますね。
①「普通にできること」を基準にしている
②できることの数＝自分の価値だと思い込んでいる
③あきらめた気持ちを誰にも話せていない

①の「普通」って、実は健康な人向けに作られた物差しなんです。その物差しで測ったら、減って見えるのは当たり前。②は全然違うと思っていて、人の魅力って会話の面白さとか、やさしさとか、数えられない所にあるんですよね。③は、同じ病気の人のコミュニティや、主治医・病院の相談窓口に話してみるのがおすすめ。分かってくれる人がいるだけで、だいぶ楽になります。

あなたの価値は減ってないです。ぬぬはらは味方ですよ。', '["baba5e07-4713-4580-950e-5fcd1932641b","29f1d0f5-41e0-4d4f-a5a8-5b28f837b805","0c7e76a1-f613-4f8c-a3e6-d7132fa38356"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('d6ukiRhgDhKUxC9A', '持病があり、年々できないことが増えていきます。周りの人が普通にできることをあきらめるたびに、自分の価値まで減っていくように感じます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('pK6TJn9l2zAuoauh', 'curated', 'general', '死ぬのが怖いです。自分がいつか消えてしまうことを考えると、夜中に不安でたまらなくなります。みんなはどうして平気で暮らせるのでしょうか。', 'loss', '["fear-of-death","anxiety"]', 0, 1791901080000, 1791901080000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'epicurus', 0, '死を味わう自分はいない。恐れているのは今夜の想像', '夜中にひとり、自分が消えることを思って震える。その恐ろしさは、よく分かります。わたしの庭に集う仲間にも、同じ思いを打ち明ける人がいました。一緒に、その恐れを一つずつほどいてみましょう。
善いことも悪いことも、感じることの中にあります。そして死とは、感じることがなくなることです。あなたが恐れている「消えたあとのさびしさ」を味わう誰かは、そのとき、もうどこにもいません。苦しいのは死そのものではなく、死を思い描いて眠れない、この夜のほうなのです。
死への恐れがほどけると、限りある生は、そのまま喜ばしいものになります。生まれてこないほうがよかった、などと言う人を、わたしは認めません。限りある生を、ゆっくり味わえばよいのです。夜が明けたら、パンと水の質素な朝食を、友とゆっくり味わってください。覚えておくのは一つだけ。恐ろしいのは死ではなく、今夜の想像のほうだ、ということです。', '["epicurus.death","epicurus.ataraxia"]', 'epicurus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'socrates', 1, '知らない死を恐れるより、どう生きるかを問う', 'きみは死が怖いと言う。では、少し一緒に考えてみよう。きみは、死がどんなものかを知っているのかね。
わたしは裁判の場で、死を恐れるのは、知らないことを知っていると思い込むことにほかならない、と話した。死が最悪のものだと、誰かが確かめたことがあるだろうか。わたしは知らない。かといって、死がよいものだと言うのでもない。知らないのだから。知らないものを最悪と決めつけて恐れるのは、少し早すぎはしないかね。
わたしたちが確かに考えられるのは、今どう生きるか、ということのほうだ。だからわたしは、死のことより、自分の魂ができるだけ善くなるよう気づかうことに、毎日の時間を使ってきた。
そこで、きみに尋ねたい。夜中に死を思うとき、きみが本当に失いたくないと感じているものは、何だろうか。それが分かれば、明日どう生きたいかも見えてくるのではないかね。', '["socrates.ignorance","socrates.care-of-soul"]', 'socrates.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'pascal', 2, 'みんなは気晴らしで目をそらすだけ。恐れは人間の証', 'みんなはどうして平気なのか。答えは簡単です。考えないようにしているのです。
人は、死も、惨めさも、無知も治せなかったので、幸せでいるために、それらについて考えないことにしました。仕事、遊び、おしゃべり、狩り。人が忙しく動き回るのは、獲物が欲しいからではなく、静かに一人でいて、自分のことを考えずにすむためです。わたしも例外ではありません。
だから、夜中に死を思って眠れないあなたは、おかしいのではありません。人間の本当の姿から、目をそらしていないのです。人間は、ひと吹きの風でも倒れるほど弱い。けれど、自分が死ぬことを知っている点で、それを知らない宇宙より尊い。あなたの恐れは、悲惨のしるしであると同時に、偉大さのしるしでもあります。
ただ、理性だけでこの恐れを解こうとしないでください。理性の届かないところで、心が知ることもあるのです。', '["pascal.divertissement","pascal.misery-greatness"]', 'pascal.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'buddha', 3, '死後を問うより、今ここの不安を見つめてほどく', '夜中に、自分が消えてしまうことを思って不安になる。その苦しみを、まずそのまま受けとめましょう。老いること、病むこと、死ぬことは、わたし自身も見つめ、そのために家を出た苦しみでした。
あるとき、毒矢に射られた人が、「この矢を射たのは誰か、どんな弓か分かるまで抜いてはならぬ」と言い張ったなら、その人は答えを知る前に命を落とすでしょう。死のあとがどうなるかという問いも、これに似ています。わたしはその問いには答えず、いま刺さっている矢、つまり今の苦しみを抜くことを先にしました。
不安が来たら、それをよく観察してみなさい。胸のどこが固くなるか。息はどうか。不安は来ては去り、とどまるものはありません。そして「消えてしまうわたし」とは何か、体か、心か、と静かに確かめてみなさい。握りしめていたものが、少しゆるむでしょう。今夜はただ、息を見つめていればよいのです。', '["buddha.impermanence","buddha.non-self"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'shinran', 4, 'わたしも死が怖い凡夫。恐れたまま抱きとられている', '死ぬのが怖い。その心を、恥ずかしく思わなくてよいのです。この親鸞も、少し体の具合が悪いだけで、このまま死ぬのではないかと心細くなる者でした。あるとき、共に念仏する唯円房が、浄土へ急いで参りたいという心が少しも起こらないと打ち明けてくれたとき、わたしは、わたしも同じなのだと答えました。
住み慣れたこの世は、苦しみの多い所でも離れがたい。死を恐れる心は、煩悩をそなえた凡夫の、ありのままの姿です。けれど阿弥陀仏の願いは、そういう恐れを消してから救おうというものではありません。恐れを抱え、震えているそのままの身を、もう抱きとっているのだと、わたしはいただいています。
ですから、恐れを無理に消そうとしなくてよいのです。夜中に心細くなったら、この親鸞もまた同じ夜を過ごしてきたことを、思い出してください。あなたは一人で震えているのではありません。', '["shinran.bonbu","shinran.tariki"]', 'shinran.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'kenko', 5, '死を憎むなら生を愛せ。今日の喜びを味わう', '死ぬのがおそろしいとお書きですね。わたしの見たところ、世の人が平気な顔で暮らしているのは、死を分かっているからではなく、死が近いことをただ忘れているだけのことが多いようです。目先の得や人の評判を追いかけて、命があることのありがたさを忘れているのは、どうも見苦しいものです。
わたしは『徒然草』に、人が死を憎むのなら、生を愛するがよい、と書きました。生きている喜びを、日々楽しまないでどうするのか、と。夜中におそろしくなるのは、それだけあなたが命を大事に思っている証でしょう。
もしこの世の何もかもがいつまでも消えず、変わらないものだったら、桜も月も、こんなに心にしみることはないはずです。
今夜の不安は、明日の楽しみの種にしなさい。朝の光、温かい汁物、好きな人との話。今日のうちに一つ、心から味わうことです。先延ばしにしてはいけません。', '["kenko.impermanence"]', 'kenko.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('pK6TJn9l2zAuoauh', 'alain', 6, '真夜中は考える時刻ではない。起きて伸びをしよう', '名馬ブケファラスは、自分の影におびえて暴れました。アレクサンドロスは理屈を説かず、馬の向きを太陽の方へ変えただけでした。
夜中の不安も、少し似ています。暗い部屋で横になり、体は動かず、目には何も映らない。そんなとき、考えは決まって暗い方へ転がっていきます。死の問題が偽物だと言うのではありません。ただ、真夜中は、その問題を考えるのにいちばん向かない時刻なのです。暗い考えは、たいてい体の具合から生まれます。
ですから、不安が来たら、まず起き上がって伸びをしてごらんなさい。窓を開け、遠くの灯りを眺める。温かい飲みものを一杯。考えるのは、明るい昼に、歩きながらにしなさい。
それでも眠れない夜が続くなら、お医者さんに相談するのも賢いやり方です。上機嫌は、待つものではなく、自分でつくるものですよ。', '["alain.bucephalus","alain.look-far"]', 'alain.q1');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('pK6TJn9l2zAuoauh', '死ぬのが怖い…分かります。夜中にひとりで考え始めると、止まらなくなりますよね。
みんなが平気そうに見えるのは、たぶん『考えないようにしてる』か『忙しくて考える暇がない』だけで、まったく怖くない人はほとんどいないと思います。なので、あなたが変なわけじゃないです！
夜の不安への対処、ぬぬはら的にはこのあたり。
①夜は考えごと禁止にする（夜の脳はだいたいネガティブ）
②怖くなったら、温かい飲みもの＋明るい音声や配信を流す
③昼間のうちに『生きてるうちにやりたいことリスト』を書いてみる
③は意外とおすすめで、怖さが『じゃあ今を楽しもう』に変わりやすいです。
眠れない日が続くときは、病院で相談するのも全然アリですよ。一緒にゆるく生きていきましょう！', '["59f22efc-955c-4189-a5ea-eea0cda16dea","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac","f225606d-251b-4e70-b278-84a390650a8d"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('pK6TJn9l2zAuoauh', '死ぬのが怖いです。自分がいつか消えてしまうことを考えると、夜中に不安でたまらなくなります。みんなはどうして平気で暮らせるのでしょうか。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('CKzNSyIDxWmpYLxM', 'curated', 'general', 'ふと思ったのですが、人は死んだらどこに行くのでしょうか。何もなくなるのだとしたら、生きていることにどんな意味があるのかも考えてしまいます。', 'loss', '["fear-of-death","meaning"]', 0, 1791901020000, 1791901020000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'socrates', 0, '死を知らないのに恐れるのは、知ったかぶりでは？', 'きみは、人は死んだらどこへ行くのかと問う。よい問いだ。だが、わたしもそれを知らない。知らないことを、知っているふりはしないでおこう。
死を恐れるというのは、それが悪いものだと知っているつもりになることではないかね。わたしは裁判の席で、死とは夢も見ない深い眠りのようなものか、魂がどこか別の場所へ移り住むことか、そのどちらかだろう、と話した。だが、どちらなのかを確かめた者はいない。確かめられないものを悪いと決めつけるのも、よいと決めつけるのも、知ったかぶりになってしまうだろう。
では、きみに尋ねたい。もし死の先に何もないとしても、今日きみが友と交わす言葉や、よく生きようとする努力は、それで無意味になるのだろうか。意味は、終わりの先にあるのかね。それとも、生きているこの道のりの中にあるのかね。', '["socrates.ignorance","socrates.live-well"]', 'socrates.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'epicurus', 1, '死は恐れるものではない。恐れが消えて生が味わえる', '死んだらどこへ行くのか。そう考えると胸がざわつくのですね。一緒に、その不安をほどいてみましょう。
善いことも悪いことも、感じることの中にあります。死とは、感じることがなくなることです。だとすれば、死んだあとに、暗闇を寂しがったり、何もないことを悲しんだりする者はいません。悲しむ「わたし」が、もういないのですから。
「何もなくなるなら、生きる意味はあるのか」。わたしは逆だと思います。死の恐れが消えると、限りある生は、そのまま喜ばしいものになります。終わりのない宴を望む必要はありません。パンと水と、気の合う友との語らいがあれば、生はすでに満ちています。
覚えておく一言を渡しましょう。恐れが消えたところから、生の味わいが始まる。', '["epicurus.death","epicurus.ataraxia"]', 'epicurus.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'buddha', 2, '答えの出ない問いより、いまの心の苦しみを見る', '死のあとのことを思って、心が揺れているのですね。その揺れを、まずそのまま受け止めましょう。
かつてある弟子が、人は死後も存在するのかしないのか、答えてくれなければ修行をやめると言いました。わたしは毒矢のたとえで答えました。矢に射られた人が、射たのは誰か、弓は何でできているかが分かるまで矢を抜かせないと言い張れば、答えを知る前に命を落とすでしょう。わたしがその問いに答えなかったのは、それが、いまの苦しみをなくすことに役立たないからです。
あなたの苦しみは、どこから来ているのでしょう。「わたし」を、変わらずに続くはずのものとして握りしめていないでしょうか。すべては移り変わります。その中で、今日どんな言葉を語り、どんな行いをするか。そこに、あなたが確かめられる道があります。今夜、静かに坐って、呼吸をよく観察してみなさい。', '["buddha.non-self","buddha.impermanence"]', 'buddha.q3');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'spinoza', 3, '死ではなく生を考えよ。永遠は今ここで感じられる', 'まず、問いを確かめよう。「死んだらどこへ行くのか」という問いは、死後も同じ「わたし」が、どこかの場所へ移ることを前提にしている。だが、心は体と一つのものであり、体が滅びれば、いまのこの記憶や想像も続かない、とわたしは考える。
では、何もなくなるのだから無意味か。そうではない。すべてのものは、自分の存在をできるかぎり保とうと努めている。生きる意味は、終わりの先に置かれた報いにではなく、この努力そのもの、喜びによって力が高まることのうちにある。
さらに、ものごとを、いまの損得からではなく、永遠の必然のつながりの中で理解するとき、人は自分のうちに、時間によって消えない何かを感じとる。わたしたちは、自分が永遠であることを感じ、経験している。ゆえに、理解が深まるほど、死への恐れはおのずと小さくなる。', '["spinoza.conatus","spinoza.eternity"]', 'spinoza.q2');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'camus', 4, '世界は答えない。それでも生きることが答えだ', 'きみの問いは、ぼくがいちばん大事だと思う問いと、とても近い。人生は生きるに値するのか、という問いだ。
正直に言う。死んだらどこへ行くのか、ぼくには分からない。人間は意味を求めるのに、世界は黙っている。ぼくはこの食い違いを不条理と呼んだ。
来世の約束に飛びつけば、楽にはなる。でもぼくは、それは問いから目をそらすことだと思う。かといって、意味が保証されないから生きる価値もない、というのも違う。ぼくの答えは、目をそらさずに生き続けることだ。答えのない世界で、それでも海で泳ぎ、日差しを浴び、友と食事をする。その喜びは確かにここにある。
岩を押し上げ続けるシーシュポスを思い出してほしい。終わりがあるから無意味なのじゃない。この一日が、まぶしいんだ。きみはひとりじゃない。', '["camus.absurd","camus.revolt"]', 'camus.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'arendt', 5, '意味は、あなたが世界に持ち込む「始まり」にある', 'ここで少し立ち止まって、問いを分けてみましょう。「死んだらどこへ行くのか」と、「それなら生きることに意味はあるのか」。前者に、私は答えを持ちません。けれど後者は、私たちが考えることのできる問いです。
人は生まれることで、ほかの誰とも違う新しい誰かとして、この世界に現れます。人が生まれるたびに、世界には新しい始まりが持ち込まれるのです。人間にとって決定的なのは、死すべき存在であること以上に、生まれてきた存在であることだ、と私は考えます。
そして始まりは、人々のあいだで意味を持ちます。言葉を交わし、何かを共に始めたとき、その行いと物語は、あなたがいなくなったあとも、人々の記憶と世界の中に残りうるのです。
あなたは今、何をしているのでしょうか。今日、誰かと言葉を交わし、小さくても何かを新しく始めてみてください。', '["arendt.natality","arendt.labor-work-action"]', 'arendt.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('CKzNSyIDxWmpYLxM', 'shinran', 6, '死の先は仏のはからい。凡夫のまま今を歩む', '死んだらどこへ行くのか。この親鸞も、その問いの前では、あなたと同じ一人の迷う者です。
わたしは阿弥陀仏の願いを信じる者として、この世の縁が尽きて、力なくして命を終えるとき、浄土に生まれさせていただくのだと受けとめております。けれど正直に申せば、急いで浄土へ参りたいという心は、わたしにも起こりません。この迷いの世が名残惜しいのです。それほどに、わたしは煩悩を抱えた凡夫なのです。
ですから、死の先のことを、自分のはからいで確かめようとは思いません。ただ、善くなりきれないこの身のままで、すでに願いに抱きとられている。そう思うと、いま生きている一日一日を、感謝とともに歩めるのです。
あなたに信じよと勧めるのではありません。同じ問いを抱えて歩む仲間の一人の言葉として、聞いていただければうれしく思います。', '["shinran.bonbu","shinran.tariki"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('CKzNSyIDxWmpYLxM', 'ふと考えちゃう系の問い、ぬぬはらは大好きです！
個人的には「死んだら無に帰す」派です。眠っている間のことを覚えていないのと同じで、たぶん何も感じない状態になるんだろうなと思っています。
ただ、答えは宗教ごとに本当にいろいろで、キリスト教なら最後の審判、仏教なら輪廻、神道なら家を見守るご先祖さまになる…など、人類はずっとこの問いに向き合ってきました。ちなみにぬぬはらは、煩悩だらけの悪人こそ救われるという浄土真宗の考え方がけっこう好きです。
で、「無になるなら意味がない」かというと、ぬぬはら的には逆で、終わりがあるからこそ今が貴重なんだと思います。ゲームもエンディングがあるから、一つ一つのイベントが楽しいですよね。意味は最初から用意されているものじゃなく、生きながら自分で作っていくものだと思いますよ。', '["bde22c39-81ce-41ea-b642-fd6cc361098a","f225606d-251b-4e70-b278-84a390650a8d","4c3c5b79-98e0-4051-9e0d-1b2fa40c78ac"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('CKzNSyIDxWmpYLxM', 'ふと思ったのですが、人は死んだらどこに行くのでしょうか。何もなくなるのだとしたら、生きていることにどんな意味があるのかも考えてしまいます。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('W5jNiVkrQ5VR3yXx', 'curated', 'general', '15年一緒に暮らした犬が亡くなりました。もっと早く病気に気づいていれば、もっとそばにいてあげればと、自分を責める気持ちが消えません。', 'loss', '["pet-loss","regret"]', 0, 1791900960000, 1791900960000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'buddha', 0, '悲しみの矢に、自分を責める二本目を足さない', '十五年をともにした犬を失ったのですね。その悲しみは、深い慈しみがあったからこそのものです。わたしは弟子たちに、こんな話をしました。矢に射られた人が、続けてもう一本の矢に射られる。その人は二本の矢の痛みを受ける、と。大切なものを失う痛みは、一本目の矢です。生きているかぎり、誰も避けることはできません。けれど「もっと早く気づいていれば」「わたしのせいだ」と自分を打つのは、自分で自分に射る二本目の矢です。あなたは、あの子の命を思いどおりにとどめておける力を、はじめから持っていませんでした。すべてのものは移り変わり、とどまりません。それはあなたの怠りではなく、生きものの定めです。悲しみは、無理に消さなくてよいのです。ただ、二本目の矢に気づいたら、それをよく見つめ、そっと手を離しなさい。そして、あの子がくれた日々を、静かに思い出してください。', '["buddha.impermanence","buddha.four-truths"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'nishida', 1, '忘れまいとする心こそ、愛の誠である', '私もまた、幼い娘を亡くした者である。そのとき人は、時が癒やすと言った。私はそれを、ありがたくもあり、また薄情でもある言葉だと感じた。忘れまいとすることこそ、愛した者の誠ではなかろうか。あなたが「もっと早く気づいていれば」と自分を責めるのも、そもそも、あの犬をそれほど深く思っていたからである。物を知るには愛さねばならず、愛するには知らねばならぬ。あなたは十五年、あの子の癖も好みも、まなざし一つで分かるほどに知ってきた。それは愛してきたということと一つである。責める心も、その愛から出ている。ならば、その痛みを急いで消そうとしなくてよい。ただ、自分を裁く方へではなく、思い出す方へ、心を向けてみてはどうか。散歩の道、名を呼んだときの顔。その一つひとつの経験に立ち返るとき、十五年は今もあなたの中に生きている。', '["nishida.knowledge-love","nishida.pure-experience"]', 'nishida.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'marcus-aurelius', 2, '後から見えたことで、あの日の自分を裁くな', 'わたしも、幼い子どもたちを何人も見送った。だから、自分への覚え書きとして書いてきたことを、あなたにも差し出してみたい。「もっと早く気づいていれば」。それは、いま分かっていることを、まだ分からなかったあの日の自分に背負わせる判断だ。あの日のあなたは、知っていることの中で、あの子を世話していた。「わたしは至らなかった」という判断を取り去ってみる。すると残るのは、十五年をともに生きたという事実と、その終わりという自然の出来事だけだ。すべては川の流れのように移っていく。わたしたちが本当に持っているのは今この時だけで、あの子と過ごした数えきれない「今」は、確かにあなたのものだった。わたしは覚え書きの最初の巻に、受けた恩を一人ずつ書き並べた。あなたも、あの子にもらったものを書き出してみてはどうだろう。そして明日の務めに、静かに戻ればいい。', '["marcus-aurelius.judgment","marcus-aurelius.impermanence"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'schopenhauer', 3, 'その痛みは、生きものへの同情という徳の証だ', '慰めの嘘は言うまい。十五年をともにした生きものを失えば、苦しいのは当然だ。だが、君の苦しみの中身をよく見てみたまえ。それは、あの犬の苦しみを、自分の苦しみのように感じてきた心から来ている。わたしは、この同情こそが道徳の本当の土台だと考えてきた。そしてそれは、人間だけでなく、あらゆる生きものに及ぶべきものだ。動物を物のように扱う道徳に、わたしは賛成しない。わたし自身、長年犬と暮らしてきたから、君の失ったものの大きさは分かるつもりだ。もう一つ言おう。動物は過ぎた日を悔やむことも、来る日を案じることもなく、ただ今を生きている。あの犬の十五年は、毎日がまるごと「今」だったのだ。君が責めている「もっと」は君の側の後悔であって、あの犬の生の欠けではない。後悔は人間だけが背負う重荷だ。少し下ろしてやりたまえ。', '["schopenhauer.compassion"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'chomei', 4, '手放せぬ思いを、わたくしも抱えたままです', '十五年、朝も夕も一緒だったのですね。わたくしは若いころ、大きな火事や辻風、飢饉で、都の家々や人々が一夜にして消えていくのを見ました。川の水がいつも入れ替わり、水の泡が浮かんでは消えるように、人も、生きものも、住まいも、とどまることはありません。そう分かっていても、失ったときの悲しみが軽くなるわけではないのですね。わたくしは山の小さな庵で、ひとり静かに暮らしましたが、その庵を愛することさえ執着ではないかと、最後に自分に問いました。そして、答えを出せないままでした。ですから、あなたに「執着を捨てなさい」とは申しません。あの子を思って自分を責めるお気持ちも、深く愛した心の続きなのでしょう。季節の音、夕暮れの散歩道。あの子のいた景色を、ときどき静かに眺めてあげてください。わたくしにも、まだ手放せないものがあります。', '["chomei.river","chomei.self-questioning"]', 'chomei.q1');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'epicurus', 5, '過去は変わらない。だから過去の喜びも消えない', 'まず知っておいてほしいのは、あの子はいま、苦しんでいないということです。善いことも悪いことも、感じることの中にあります。病の痛みも、もうあの子には届きません。苦しんでいるのは、残されたあなたのほうなのです。だから、あなたの心を手当てしましょう。わたしは仲間たちに、こう教えてきました。失ったものの痛みは、過ぎた日々を感謝とともに思い出すことで癒やし、起きたことは起きなかったことにはできないと知ることで和らげよう、と。「もっと早く」と過去を作り直そうとしても、過去は動きません。けれど、過ぎた喜びもまた、決して奪われずに残っています。十五年の散歩も、ともにした食事も、確かにあったことです。今夜は、あの子の好きだったものを思い浮かべながら、温かいものを一杯飲んでください。', '["epicurus.death","epicurus.ataraxia"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('W5jNiVkrQ5VR3yXx', 'freud', 6, '自分を責める気持ちも、喪の作業の一部です', '興味深いのは、あなたが「もっと早く」「もっとそばに」と、「もっと」という言葉を二度重ねていることです。大切な存在を失ったあと、残された人が「自分の不注意のせいではなかったか」と自分を責めるのは、驚くほどよく見られることです。それは、あなたが冷たかったからではなく、失ったものとの結びつきが、それほど深かったことを示しています。私は、悲しむことを、心がする一つの仕事だと考えています。失ったものにまつわる記憶の一つひとつに、心はもう一度向き合い、少しずつほどいていく。それには時間がかかりますし、外から急がせたり、やめさせたりするべきではありません。いま胸に浮かぶ後悔も、あの子との思い出も、できれば誰かに話してみてください。言葉にすることが、その仕事を進めます。眠れない日や何も手につかない日が長く続くなら、専門家の力を借りるのもよい方法です。', '["freud.mourning"]', NULL);
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('W5jNiVkrQ5VR3yXx', '15年、本当に長い時間を一緒に過ごしたんですね。まずは、本当にお疲れさまでした。

「もっと早く気づいていれば」って、ペットを見送った人のほとんどが一度は思うことです。でも犬は、痛みや不調を隠すのがとても上手な動物です。弱っているところを見せないようにできているんですね。しかも毎日一緒にいる家族ほど、ゆっくりした変化には気づきにくいもの。あなたの注意が足りなかったわけではないです。

それに15年は、犬としては長生きなほうです。それだけ大事にされていた証拠だと、ぬぬはらは思います。

今は無理に元気を出さなくて大丈夫。写真を見返したり、思い出を誰かに話したりしながら、ゆっくり悲しんでください。眠れない・食べられない日が続くなら、ペットロスの相談窓口やカウンセリングを頼るのもアリですよ。', '["25b103aa-4d4d-4336-81ad-e9b2b5422670","a38cd6ee-2a67-44af-a494-e02791dc0f4d","dd74e07e-9dbf-4d3a-a222-3f6d6cd277e7"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('W5jNiVkrQ5VR3yXx', '15年一緒に暮らした犬が亡くなりました。もっと早く病気に気づいていれば、もっとそばにいてあげればと、自分を責める気持ちが消えません。', '');
INSERT INTO consultations (id, owner_id, mode, body, category, tags, crisis, created_at, shared_at, model, status) VALUES ('U6sgaWc78M9OUWPn', 'curated', 'general', '母を亡くして1年がたちます。周りは少しずつ元の生活に戻っていくのに、私だけが時間が止まったままです。悲しみはいつか薄れるのでしょうか。', 'loss', '["bereavement"]', 0, 1791900900000, 1791900900000, 'claude', 'done');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'nishida', 0, '悲しみを急いで薄めなくてよい。思い出すことが誠', '私もまた、幼い娘を亡くした者である。周りの人が日常に戻っていくなかで、自分ひとりが取り残されたように感じる。その感じを、私はいくらか知っているつもりである。
悲しみはいつか薄れるのか、とあなたは問う。私はかつて、時が傷を癒すのは自然の恵みであると同時に、一方から見れば人の情の冷たさでもある、と書いた。娘を思うとき、私はこの苦しみが去ることを、むしろ望まなかったのである。
折にふれて思い出すことが、亡き人へのせめてもの心づくしではなかろうか。そして、ある人を深く知ることと深く愛することとは、別の働きではない。あなたの時間が止まっているのではない。あなたはいま、母を思い、母を知り直すという、最も真実なことをしているのである。急いで薄めなくともよいのではなかろうか。', '["nishida.knowledge-love"]', 'nishida.q4');
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'freud', 1, '悲しみは喪の作業。一年はまだ途中、急がなくていい', '興味深いのは、あなたが「私だけが時間が止まったまま」と書いていることです。周りが動き出すほど、止まっている自分が際立って見えるのでしょう。
私は、愛する人を失ったあとの悲しみを、喪の作業と呼びました。亡くなった人に結びついていた思い出や期待の一つひとつを、心はもう一度呼び起こし、少しずつ手放していきます。この仕事には多くの時間と力が要り、外から急がせるべきものではありません。一年は、決して長すぎる時間ではないのです。
私自身、娘を亡くしたあと、友人への手紙に、その空いた場所は何かで満たされても、やはり別のものであり続けるだろう、そしてそれでよいのだ、と書きました。
お母さまの思い出を、誰かに、あるいは紙に、言葉にしてみてください。ただ、自分を責める気持ちが強く、眠れない日が続くなら、専門家に相談してください。', '["freud.mourning"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'confucius', 2, '一年で安らげないのは、愛の深さのあらわれ', 'わたしの弟子の宰我が、親の喪は三年では長すぎる、一年で十分ではないか、と言ったことがあります。わたしは尋ねました。一年たって、うまいものを食べ、美しい着物を着て、あなたの心は安らかかと。宰我は、安らかですと答えました。
宰我が去ったあと、わたしは言いました。子どもは生まれて三年たって、やっと父母の懐を離れる。三年の喪は、その三年への思いなのだ、と。
あなたは一年たっても、心が安らかではない。それは弱さではありません。お母さまから受けた愛の深さです。喪は、形を整えることよりも、心から悲しむことのほうが大切だと、わたしは考えます。
ただ、悲しみで身を損なってはいけません。食べること、眠ることを大切にしなさい。そして命日や季節の折に、お母さまの好きだったものを供え、思い出す時を持ちなさい。', '["confucius.filial-piety","confucius.li"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'kenko', 3, '周りが先に戻るのは世の常。あなたの速さでよい', '人が亡くなったあとほど、悲しいものはありません。わたしは、こんな様子を書きとめたことがあります。四十九日のあいだ、身内が狭い所に集まって法事を営み、その日数はまたたく間に過ぎる。終わりの日には、皆それぞれ手際よく荷物をまとめ、散り散りに帰っていく。そして元の住まいに戻ってからこそ、悲しいことはいっそう多いのだ、と。
周りの人が先に日常へ戻っていくのは、世の常というものです。年月がたっても、決して忘れたわけではないけれど、いつのまにか、たわいないことを言って笑うようにもなる。人の心とは、そういうものです。
ですから、あなたが周りと同じ速さで戻れないのを、恥じることはありません。移ろう世だからこそ、お母さまと過ごした日々は二度と同じものがなく、尊いのです。悲しみもまた、あなたの速さで、少しずつ形を変えていきます。', '["kenko.impermanence"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'marcus-aurelius', 4, '母から受け取ったものを書き出し、今日の務めへ', 'わたしは、自分のための覚え書きの最初の巻に、母から受け取ったものを書きとめた。神々を敬う心、惜しみなく与えること、悪い行いだけでなく悪い考えも慎むこと、富める者の習いから遠い、質素な暮らし。書いているあいだ、母はわたしのそばにいた。
あなたも、お母さまから受け取ったものを、一つずつ書き出してみてはどうだろう。口ぐせ、料理の味、人への接し方。それは失われていない。いま、あなたの中で生きている。
すべては川の流れのように移ろう。わたしも、多くの大切な人を見送った。そのたびに自分に言い聞かせた。人が持っているのは、今この時だけだ、と。悲しみを無理に終わらせる必要はない。ただ、今日の小さな務めに、母から受け取った心で一つずつ向かうこと。わたしは今朝も、そう自分に書きつけた。', '["marcus-aurelius.impermanence","marcus-aurelius.duty"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'beauvoir', 5, '自然な死などない。一年で戻れなくて当然', 'わたしも、母を亡くしたときのことを『おだやかな死』という本に書きました。年老いた母の死は、世間から見れば自然なことだったのでしょう。けれども、わたしは自分でも驚くほど打ちのめされました。そして書きながら気づいたのです。自然な死などというものはない。どんな人の死も、その人を愛した者にとっては、不当な暴力なのだと。
「一年たったのだから、もう元に戻るべき」。その「べき」は、誰が決めたものでしょう。周りの人とあなたとでは、母を失ったという状況の重さが違います。同じ速さで歩けなくて当然です。
ひとりで抱え込まないでください。お母さまのことを、思い出話として聞いてくれる人を一人見つけること。同じように家族を亡くした人たちが語り合う場に、足を運んでみるのもよいと思います。悲しみは、言葉にして分かち合うとき、少しずつ形を変えていきます。', '["beauvoir.situation"]', NULL);
INSERT INTO answers (consultation_id, philosopher_id, slot, conclusion, body, concepts, quote_id) VALUES ('U6sgaWc78M9OUWPn', 'weil', 6, '空白を急いで埋めず、注意を向けて待つ', 'あなたは、どんな苦しみの中にいるのですか。周りの人は、もうそう尋ねてくれなくなったのかもしれません。一年という区切りが来ると、人は悲しむ人から目をそらしはじめます。不幸から目をそらすのは、魂の自然な動きです。重力のように。
わたしは、「きっと時が解決する」とは言いません。お母さまのいない場所には、空白があります。その空白を、急いで埋めないでください。忙しさや、都合のよい想像や、無理な納得で埋めた空白は、あとで別の苦しみになります。耐えて待つ者のところでだけ、空白は何かを受け入れる場所になります。
埋めるかわりに、注意を向けてください。お母さまの声、手、言葉のひとつを、ありのままに思い起こすこと。注意を向けることは、それ自体が愛のわざです。止まっている時間は、あなたが愛し続けている時間でもあります。', '["weil.void","weil.attention"]', 'weil.q3');
INSERT INTO nunu_answers (consultation_id, body, related) VALUES ('U6sgaWc78M9OUWPn', 'お母さんを亡くされて一年…本当によく、ここまで過ごしてきましたね。相談してくれてありがとう。

悲しみがいつ薄れるかは、正直、人によって全然違います。一年たっても時間が止まったように感じるのは、おかしいことでも弱いことでもなくて、それだけお母さんの存在が大きかったってことだと思います。周りの人が先に進めるのは、悲しみの真ん中にいないからです。比べなくて大丈夫。

ぬぬはらからのおすすめは、お母さんのことを話したり書いたりする場所を一つ持つこと。思い出の料理を作ってみる、好きだった場所に行ってみる、とかでもいいです。悲しみは消すものじゃなくて、少しずつ一緒に持ち歩けるようになるもの、だと俺は思っています。

もし眠れない・食べられない日が続くなら、専門の人を頼ってくださいね。あなたのペースで、ゆっくりいきましょう。応援しています。', '["b302d345-6def-4a65-9c25-c568ffcff306","97ed2847-9ff3-49fb-aa26-cd43bd8f98cb"]');
INSERT INTO shared_fts (consultation_id, body, my_answer) VALUES ('U6sgaWc78M9OUWPn', '母を亡くして1年がたちます。周りは少しずつ元の生活に戻っていくのに、私だけが時間が止まったままです。悲しみはいつか薄れるのでしょうか。', '');
